/** DataNexus IAA 枚举（对齐 mini-game-workspace/shared/sdk/datanexus/iaa.js） */

/** 激励点位枚举：2 体力、27 跳过、68 其他 */
export const IAA_PLACEMENT = {
  index_reward: 2,
  play_reward: 27,
  entry_reward: 68,
  play_click_reward: 68,
  play_undo_reward: 27,
  play_shuffle_reward: 27,
  default_reward: 68,
};

/** 1 激励 2 插屏 3 格子 4 banner/原生 */
export const IAA_AD_TYPE = {
  rewarded: 1,
  interstitial: 2,
  grid: 3,
  native: 4,
};

/** 道具类型：随关卡结束事件汇总到 items 参数 */
export const IAA_ITEM = {
  UNDO: 15,
  SHUFFLE: 20,
  HINT: 27,
  OTHER: 46,
};

export function placementNameOf(code) {
  const n = IAA_PLACEMENT[code];
  return n == null ? 68 : n;
}

export function impressionTypeOf(adTypeKey) {
  if (adTypeKey === "INSERT_SCREEN" || adTypeKey === "interstitial" || adTypeKey === 2) {
    return IAA_AD_TYPE.interstitial;
  }
  if (adTypeKey === "GRID" || adTypeKey === "grid" || adTypeKey === 7) {
    return IAA_AD_TYPE.grid;
  }
  if (adTypeKey === "REWARDED_VIDEO" || adTypeKey === "rewarded" || adTypeKey === 1) {
    return IAA_AD_TYPE.rewarded;
  }
  return IAA_AD_TYPE.native;
}

export function round2(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return 0;
  return Math.round(Math.min(1, Math.max(0, x)) * 100) / 100;
}

export function formatItemList(itemMap) {
  const keys = Object.keys(itemMap || {});
  if (!keys.length) return null;
  return keys.map((type) => {
    const num = Number(itemMap[type]) || 1;
    return `{item_type:${Number(type)},item_num:${num}}`;
  });
}

/**
 * LEVEL_ENTER / LEVEL_* 公共参数，字段与 shared/sdk/datanexus 完全一致。
 */
export function buildLevelEnterParams(info) {
  const levelId = Math.max(1, Number(info && info.level_id) || 1);
  const total = Number(info && info.level_total) || 0;
  const params = {
    level_id: levelId,
    game_mode: (info && info.game_mode) || "简单模式",
  };
  if (total > 0) params.enter_level_id = round2(levelId / total);
  else if (info && info.enter_level_id != null) {
    params.enter_level_id = round2(info.enter_level_id);
  }
  if (info && info.enter_level_name) {
    params.enter_level_name = String(info.enter_level_name);
  }
  if (info && info.chapter_id != null) {
    params.chapter_id = Number(info.chapter_id) || 0;
  }
  if (info && info.coin_amount != null) {
    params.coin_amount = Number(info.coin_amount) || 0;
  }
  if (info && info.stamina_value != null) {
    params.stamina_value = Number(info.stamina_value) || 0;
  }
  if (info && info.level_value != null) {
    params.level_value = Number(info.level_value) || 0;
  }
  return params;
}

export function attachLevelEndParams(base, session) {
  const params = { ...base };
  params.ad_cnt = Math.max(0, Number(session && session.adCnt) || 0);
  const started = session && session.startedAt;
  if (started) {
    params.duration = Math.max(0, Math.round((Date.now() - started) / 1000));
  }
  const items = formatItemList(session && session.items);
  if (items) params.items = items;
  return params;
}

export function readDefaultLevelInfo(levelId, extra = {}) {
  let stamina;
  try {
    const root =
      typeof GameGlobal !== "undefined"
        ? GameGlobal
        : typeof globalThis !== "undefined"
          ? globalThis
          : null;
    const lives = root && root.lives;
    stamina =
      extra.stamina_value != null
        ? extra.stamina_value
        : lives && lives.current != null
          ? lives.current
          : undefined;
  } catch (e) {
    stamina = extra.stamina_value;
  }
  return Object.assign({ level_id: levelId, stamina_value: stamina }, extra);
}
