
// 抖音小程序

/*
	插屏广告加载器
*/
class InterstitialAdLoader {
	constructor(params) {
		/**
		 * @description: 初始化一个插屏广告，开发者需要将参数置换为自己小程序的广告id
		 */

		// 提取 autoOffTime，不传给平台 API
		this.autoOffTime = (params.autoOffTime && Number.isFinite(+params.autoOffTime) && +params.autoOffTime > 0)
			? +params.autoOffTime
			: 0;
		const adParams = Object.assign({}, params);
		delete adParams.autoOffTime;

		this.ad = tt.createInterstitialAd(adParams);

		// 记录注册的 onClose 回调，用于 autoOffTime 触发
		this._closeCallbacks = [];
		this._autoCloseTimer = null;
	}

	async load() {
		if (!this.ad) return Promise.resolve();
		return this.ad.load();
	}

	async show() {
		if (!this.ad) return Promise.reject(new Error('插屏广告对象未初始化或已被销毁'));
		const result = await this.ad.show();

		// show 成功后，若设置了 autoOffTime，则启动自动关闭定时器
		if (this.autoOffTime > 0) {
			this._clearAutoCloseTimer();
			console.log(`⏰ [TTInterstitialAdLoader] 启动自动关闭定时器，${this.autoOffTime}秒后销毁广告`);
			this._autoCloseTimer = setTimeout(async () => {
				this._autoCloseTimer = null;
				console.log(`⏰ [TTInterstitialAdLoader] autoOffTime 到期，触发自动关闭`);
				const callbacks = [...this._closeCallbacks];
				await this.destroy();
				callbacks.forEach(cb => {
					try { cb(); } catch (e) { /* 忽略回调错误 */ }
				});
			}, this.autoOffTime * 1000);
		}

		return result;
	}

	/** 清除自动关闭定时器 */
	_clearAutoCloseTimer() {
		if (this._autoCloseTimer) {
			clearTimeout(this._autoCloseTimer);
			this._autoCloseTimer = null;
		}
	}

	async destroy() {
		this._clearAutoCloseTimer();
		this._closeCallbacks = [];
		if (this.ad) {
			try {
				if (typeof this.ad.destroy === 'function') {
					await this.ad.destroy();
				}
			} catch (e) {
				console.warn('⚠️ [TTInterstitialAdLoader.destroy] 销毁插屏广告实例出错:', e);
			}
			this.ad = null;
		}
	}

	onLoad(callback) {
		if (!this.ad) return;
		if (callback && typeof callback == 'function' && typeof this.ad.onLoad == 'function') {
			this.ad.onLoad(callback);
		}
	}
	onError(callback) {
		if (!this.ad) return;
		if (callback && typeof callback == 'function' && typeof this.ad.onError == 'function') {
			this.ad.onError(callback);
		}
	}

	onClose(callback) {
		if (callback && typeof callback == 'function') {
			// 收集 onClose 回调供 autoOffTime 使用
			if (this._closeCallbacks && !this._closeCallbacks.includes(callback)) {
				this._closeCallbacks.push(callback);
			}
			if (this.ad && typeof this.ad.onClose == 'function') {
				this.ad.onClose(callback);
			}
		}
	}

	offLoad(callback) {
		if (!this.ad) return;
		if (callback && typeof callback == 'function' && typeof this.ad.offLoad == 'function') {
			this.ad.offLoad(callback);
		}
	}
	offError(callback) {
		if (!this.ad) return;
		if (callback && typeof callback == 'function' && typeof this.ad.offError == 'function') {
			this.ad.offError(callback);
		}
	}
	offClose(callback) {
		// 从自动关闭回调列表中移除
		if (callback && this._closeCallbacks) {
			this._closeCallbacks = this._closeCallbacks.filter(cb => cb !== callback);
		}
		// 如果列表已空，取消定时器
		if (this._closeCallbacks && this._closeCallbacks.length === 0) {
			this._clearAutoCloseTimer();
		}
		if (!this.ad) return;
		if (callback && typeof callback == 'function' && typeof this.ad.offClose == 'function') {
			this.ad.offClose(callback);
		}
	}

}


//根据key升序排列后取值作为key返回
function paramsConvertToKey(params) {
	return Object.values(sortByKey(params)).join("");
}

function sortByKey(obj) {
	const newKey = Object.keys(obj).sort()
	let newObj = {};
	for (let i = 0; i < newKey.length; i++) {
		newObj[newKey[i]] = obj[newKey[i]]
	}
	return newObj;
}


/*
	 激励视频广告加载器
*/
class RewardedVideoAdLoader {
	constructor(params) {
		//参数检查
		if (params.multiton) {
			try {
				//范围1-4
				params.multitonRewardTimes = Math.min(4, params.multitonRewardTimes || 1)
				params.multitonRewardMsg = params.multitonRewardMsg || []
				for (let i = 0; i < params.multitonRewardMsg.length; i++) {
					params.multitonRewardMsg[i] = params.multitonRewardMsg[i].substring(0, 7)
				}
			} catch (error) {
				//报错时，将配置降级，确保广告能展示
				params = {
					adUnitId: params.adUnitId
				}
			}

		}

		this.params = params

		this.ad = tt.createRewardedVideoAd(params);
	}

	/**
	 * @description
	 * 比较配置文件，是否相同
	 * @param {Object} params
	 */
	isSame(params) {
		let myKey = paramsConvertToKey(this.params)
		let key = paramsConvertToKey(params)
		return myKey == key
	}


	async load() { return this.ad.load(); }

	async show() { return this.ad.show(); }

	async destroy() {
		return this.ad.destroy()
	}

	onLoad(callback) {
		if (callback && typeof callback == 'function' && typeof this.ad.onLoad == 'function') {
			this.ad.onLoad(callback);
		}
	}

	onError(callback) {
		if (callback && typeof callback == 'function' && typeof this.ad.onError == 'function') {
			this.ad.onError(callback);
		}
	}

	onClose(callback) {
		if (callback && typeof callback == 'function' && typeof this.ad.onClose == 'function') {
			this.ad.onClose(callback);
		}
	}

	offLoad(callback) {
		if (callback && typeof callback == 'function' && typeof this.ad.offLoad == 'function') {
			this.ad.offLoad(callback);
		}
	}
	offError(callback) {
		if (callback && typeof callback == 'function' && typeof this.ad.offError == 'function') {
			this.ad.offError(callback);
		}
	}
	offClose(callback) {
		if (callback && typeof callback == 'function' && typeof this.ad.offClose == 'function') {
			this.ad.offClose(callback);
		}
	}
}

/*
	  配置
*/
const getConfigData = () => {
	return {
		platform: 'DY',
		payPlatform: 'douyin'
	}
}
export default {
	InterstitialAdLoader,
	RewardedVideoAdLoader,
	getConfigData
};