//当前环境production development preview
// const ENV = microapp?.envType || 'production'
const ENV = 'production'
let APP_VERSION = microapp?.mpVersion || "1.0.0";

// 这些变量将在 readyAsync 中设置
let APP_ID = null;
let APP_NAME = null;

// fbisdk 将在 readyAsync 中初始化
let fbisdk = null;

// 「平台 getLaunchOptionsSync + 手动 params」解析后的扁平启动参数（全局单例）
let __resolved_launch_options__ = null;
// 手动 setLaunchOptions 后锁定：页面切换 / 无参重置不得冲掉 channel 等字段
let __launch_options_sealed__ = false;

const __isEmptyLaunchVal = (v) => v == null || v === "";

/**
 * 合并 query：已有非空字段优先；channel 一旦是非 xcx，禁止被 xcx/空值降级
 */
const __mergeLaunchQuery = (baseQuery, ...incomings) => {
	const out = { ...(baseQuery || {}) };
	for (const incoming of incomings) {
		if (!incoming || typeof incoming !== "object") continue;
		Object.keys(incoming).forEach((key) => {
			const next = incoming[key];
			if (__isEmptyLaunchVal(next)) return;
			const prev = out[key];
			if (key === "channel") {
				if (prev && prev !== "xcx" && next === "xcx") return;
				if (__launch_options_sealed__ && prev && prev !== "xcx") return;
			} else if (__launch_options_sealed__ && !__isEmptyLaunchVal(prev)) {
				return;
			}
			out[key] = next;
		});
	}
	return out;
};

/**
 * 将平台形态 { path, scene, query, ... } 解析为 SDK 扁平启动参数
 */
const __buildResolvedLaunchOptions = (options) => {
	options = options || { query: {}, path: "", scene: "0" };
	let {
		path,
		scene,
		refererInfo,
		showFrom,
		query
	} = options;

	query = query || {};
	scene = String(scene || query.scene || "");

	let adParams = "";
	try {
		adParams = query.ad_params ? JSON.parse(query.ad_params) : "";
	} catch (e) {
		adParams = "";
	}
	let clickId = query.clickid ? query.clickid : "";
	let aid = query.aid ? query.aid : "";
	let androidId = query.androidId ? query.androidId : "";
	let animation = "open";
	let caId = query.caId ? query.caId : "";
	let caIdMd5 = query.caIdMd5 ? query.caIdMd5 : "";
	let idfa = query.idfa ? query.idfa : "";
	let idfaMd5 = query.idfaMd5 ? query.idfaMd5 : "";
	let imeiMd = query.imeiMd ? query.imeiMd : "";
	let mid = query.mid ? query.mid : "";
	let oaId = query.oaId ? query.oaId : "";
	let oaIdMd5 = query.oaIdMd5 ? query.oaIdMd5 : "";
	let requestId = query.requestId
		? query.requestId
		: adParams && adParams.log_extra
			? adParams.log_extra.req_id
			: "";

	let launch_from = options.launch_from || query.launch_from || "";
	let location = options.location || query.location || "";

	let compilationsId = query.id || "";
	let tt_album_id = query.tt_album_id || "";
	let tt_episode_id = query.tt_episode_id || "";

	// 已锁定的全局 channel 优先，避免再次解析时掉回默认 xcx
	let channel =
		(__resolved_launch_options__ &&
			__resolved_launch_options__.channel &&
			__resolved_launch_options__.channel !== "xcx"
			? __resolved_launch_options__.channel
			: null) ||
		query.channel ||
		"xcx";
	refererInfo = refererInfo
		? typeof refererInfo === "string"
			? refererInfo
			: JSON.stringify(refererInfo)
		: JSON.stringify({});
	showFrom = showFrom || "";

	return {
		...query,
		path,
		scene,
		refererInfo,
		showFrom,
		aid,
		androidId,
		animation,
		caId,
		caIdMd5,
		idfa,
		imeiMd,
		idfaMd5,
		mid,
		oaId,
		requestId,
		oaIdMd5,
		clickId,
		platform: getConfigData().platform,
		compilationsId,
		tt_album_id,
		tt_episode_id,
		channel,
		launch_from,
		location,
	};
};

/**
 * 同步到 fbisdk / uniCompatible，保证埋点、登录参数读到同一份全局启动参数
 */
const __syncLaunchOptionsToRuntime = (launchOptions, rawOptions) => {
	__resolved_launch_options__ = launchOptions;
	uniCompatible.setLaunchOptionsOverride(rawOptions);
	uniCompatible.setResolvedLaunchOptions(launchOptions);

	if (fbisdk) {
		fbisdk.launchOptions = { ...launchOptions };
		fbisdk.__login_params__ = {
			...(fbisdk.runtimeConfig || {}),
			...launchOptions,
		};
		fbisdk.setLaunchOptions(function () {
			return __resolved_launch_options__;
		});
	}
};

/**
 * 合并平台原生启动参数 + 手动 params，写入全局启动参数
 * 特殊页 wx.getLaunchOptionsSync 拿不到时靠 params；已 seal 后禁止无参重置把 channel 打成 xcx
 */
const __setLaunchOptionsFun = (params = null) => {
	if (!fbisdk) {
		console.warn("⚠️ [Deploy] fbisdk未初始化，无法设置启动参数");
		return;
	}

	const manual =
		params && typeof params === "object" && Object.keys(params).length > 0
			? params
			: null;

	// 已手动锁定：无参调用（超时兜底 / readyAsync 再设一次）直接忽略，防止切页后 channel→xcx
	if (__launch_options_sealed__ && !manual) {
		console.log("🔒 [Deploy] 启动参数已锁定，忽略无参重置");
		return;
	}

	const platform = uniCompatible.getPlatformLaunchOptionsSync() || {
		query: {},
		path: "",
		scene: "0",
	};
	const cached = uniCompatible.hasLaunchOptionsOverride()
		? uniCompatible.getLaunchOptionsSync()
		: null;
	const prevResolved = __resolved_launch_options__;

	const mergedQuery = __mergeLaunchQuery(
		(cached && cached.query) || {},
		platform.query || {},
		prevResolved || {},
		manual || {},
	);

	const pick = (key, fallback = "") => {
		const candidates = [
			manual && manual[key],
			prevResolved && prevResolved[key],
			cached && cached[key],
			platform[key],
		];
		// channel：优先非 xcx 的有效值，避免被默认 xcx 盖掉
		if (key === "channel") {
			for (const v of candidates) {
				if (!__isEmptyLaunchVal(v) && String(v) !== "xcx") return v;
			}
		}
		for (const v of candidates) {
			if (!__isEmptyLaunchVal(v)) return v;
		}
		return fallback;
	};

	const options = {
		...platform,
		...(cached || {}),
		path: pick("path", (prevResolved && prevResolved.path) || ""),
		scene: String(
			pick(
				"scene",
				(prevResolved && prevResolved.scene) || platform.scene || "0",
			),
		),
		refererInfo: pick(
			"refererInfo",
			(prevResolved && prevResolved.refererInfo) || platform.refererInfo,
		),
		showFrom: pick(
			"showFrom",
			(prevResolved && prevResolved.showFrom) || platform.showFrom,
		),
		launch_from: pick(
			"launch_from",
			(prevResolved && prevResolved.launch_from) || platform.launch_from || "",
		),
		location: pick(
			"location",
			(prevResolved && prevResolved.location) || platform.location || "",
		),
		query: mergedQuery,
	};

	const launchOptions = __buildResolvedLaunchOptions(options);
	// 再次保护 channel：seal 或已有推广 channel 时不被默认 xcx 覆盖
	if (
		prevResolved &&
		prevResolved.channel &&
		prevResolved.channel !== "xcx" &&
		(!launchOptions.channel || launchOptions.channel === "xcx")
	) {
		launchOptions.channel = prevResolved.channel;
		options.query = { ...options.query, channel: prevResolved.channel };
	}

	__syncLaunchOptionsToRuntime(launchOptions, options);

	if (manual) {
		__launch_options_sealed__ = true;
		console.log("✅ [Deploy] 启动参数已写入并锁定", {
			channel: launchOptions.channel,
			scene: launchOptions.scene,
			path: launchOptions.path,
		});
	} else {
		console.log("✅ [Deploy] 启动参数已写入（平台）", {
			channel: launchOptions.channel,
			scene: launchOptions.scene,
		});
	}
};

let __init__promise__;
let __ready_promise__;
let __adconfig_init_promise__;

const __init__ = () => {
	//确保执行器单列
	if (__init__promise__ != null) {
		return __init__promise__;
	}
	__init__promise__ = new Promise((resolve, reject) => {
		async function __loop_func__() {
			try {
				//归因及配置获取 渠道获取
				//sdk内部可能会请求抖音登录
				//返回归因信息 
				//--重构--
				let attributeInfo = await fbisdk.initAsync();
				//登录系统在initAsync中已完成
				let userInfo = fbisdk.__login_cache__;
				console.log("✅ [Deploy] 登录完成", {
					userId: userInfo?.userId,
					appId: userInfo?.appId || fbisdk.app_id,
					hasToken: !!userInfo?.accessToken,
				});

				let result = {
					attributeInfo,
					userInfo
				};

				return result;
			} catch (error) {
				console.error("❌ [__loop_func__] 核心初始化逻辑失败:", error);
				throw error;
			}
		}

		let __loop__ = () => {
			__loop_func__()
				.then((result) => {
					resolve(result);
				})
				.catch((error) => {
					uniCompatible.showModal({
						title: "提示",
						content: "登录失败,请重新登陆",
						showCancel: true,
						confirmText: "重试",
						cancelText: "取消",
						confirmColor: "#FF4500",
						success: function(res) {
							if (res.confirm) {
								__loop__();
							} else if (res.cancel) {
								reject(error);
							}
						},
					});
					let reason = error ? JSON.stringify(error) : ''

					// 登录失败埋点：isLogin=false，避免再次走 initAsync → user/login
					fbisdk.trackAsync(
						"$SdkError", {
							value: "login-failure",
							reason
						},
						false,
					);

					console.error("init error", error);
				});
		};

		__loop__();
	});

	return __init__promise__;
};

class Deploy {
	constructor() {
		this.__config = {};
		this.__is_ready = false;

		// 新增属性：支持新API - 延迟获取配置，避免时序问题
		this.platformConfig = null;
		this.initialized = false;
	}

	// 添加fbisdk的getter
	get fbisdk() {
		if (fbisdk) {
			// SDK已初始化，返回真实的fbisdk实例
			return fbisdk;
		} else {
			// SDK未初始化，返回临时的兼容对象
			console.warn("⚠️ [Deploy.fbisdk] SDK未初始化，使用临时兼容对象");
			return {
				requestAsync: async (options) => {
					console.log(
						"🚀 [Deploy.fbisdk.requestAsync] 临时模式：使用基础HTTP请求",
					);

					// 获取配置进行签名
					let config;
					try {
						const {
							getExtConfig
						} = require("../../src/ext-config-handler.js");
						config = getExtConfig();
					} catch (error) {
						config = ext_config || {};
					}

					// 准备请求数据并签名
					const requestData = options.data || {};
					let finalData = requestData;

					// 创建Api实例发送请求
					const api = fbiCoreHttp.enviroment("production");
					return await api.requestAsync(
						options.method || "GET",
						options.url,
						finalData,
					);
				},
				// 临时埋点方法 - SDK未初始化时静默忽略
				trackAsync: async (eventName, properties) => {
					console.warn(
						`⚠️ [临时fbisdk] SDK未初始化，事件 '${eventName}' 被忽略。请先调用 Deploy.readyAsync(config)`,
					);
					return false;
				},
				trackAfterLoginAsync: async (eventName, properties) => {
					console.warn(
						`⚠️ [临时fbisdk] SDK未初始化，事件 '${eventName}' 被忽略。请先调用 Deploy.readyAsync(config)`,
					);
					return false;
				},
			};
		}
	}

	// 添加config的getter，延迟获取配置避免时序问题
	get config() {
		try {
			// 使用ext-config-handler统一处理配置获取
			const {
				getExtConfig
			} = require("../../src/ext-config-handler.js");
			return getExtConfig();
		} catch (error) {
			console.warn(
				"⚠️ [Deploy.config] 配置获取失败，回退到全局变量:",
				error,
			);
			return ext_config || {};
		}
	}

	/**
	 * 检查Deploy是否已经准备就绪
	 * @returns {boolean} 是否已准备就绪
	 */
	isReady() {
		return this.__is_ready;
	}

	/**
	 * 是否小游戏：小游戏包 BUILD_TARGET=minigame，或 readyAsync(config) 注入过配置
	 */
	isMinigame() {
		try {
			if (
				typeof process !== "undefined" &&
				process.env &&
				process.env.BUILD_TARGET === "minigame"
			) {
				return true;
			}
		} catch (e) {}
		return !!__is_minigame__;
	}

	/**
	 * 是否接入微信小游戏 DH 官方 SDK（config.isWXGameSDK === true）
	 */
	isWXGameSDK() {
		return !!__is_wx_game_sdk__;
	}

	/**
	 * @deprecated 业务无需调用。DataNexus 已在 SDK 内自动接入（配置 wxGameCode + wxGameSecretKey 即可）。
	 * 仅调试 / 扩展时使用。
	 */
	getDataNexus() {
		try {
			const {
				default: dataNexusManager
			} = require("../datanexus/DataNexusManager.js");
			return dataNexusManager.getFacade();
		} catch (e) {
			return {
				isReady: () => false,
				isConfigured: () => false,
				track: () => ({ code: 100, message: "datanexus unavailable" }),
				flush: () => {},
				reportLoadFinish: () => ({ code: 100, message: "datanexus unavailable" }),
				reportHomepageView: () => ({ code: 100, message: "datanexus unavailable" }),
				reportTutorialStart: () => ({ code: 100, message: "datanexus unavailable" }),
				reportTutorialFinish: () => ({ code: 100, message: "datanexus unavailable" }),
				reportAdPlacementShow: () => {},
				reportAdClick: () => {},
				reportAdVideoFinish: () => {},
				reportAdImpression: () => {},
				reportItemUsed: () => {},
				levelEnter: () => ({ code: 100, message: "datanexus unavailable" }),
				levelPass: () => ({ code: 100, message: "datanexus unavailable" }),
				levelLose: () => ({ code: 100, message: "datanexus unavailable" }),
				levelExit: () => ({ code: 100, message: "datanexus unavailable" }),
			};
		}
	}

	/**
	 * 获取全局启动参数（平台 + 手动 params 合并结果，锁定后不变）
	 */
	getLaunchOptions() {
		if (__resolved_launch_options__) {
			return { ...__resolved_launch_options__ };
		}
		const fromUni = uniCompatible.getResolvedLaunchOptions();
		if (fromUni) {
			return fromUni;
		}
		if (fbisdk && fbisdk.launchOptions) {
			return { ...fbisdk.launchOptions };
		}
		// 尚未写入时，按当前可读来源即时解析（不落库、不锁定）
		return __buildResolvedLaunchOptions(uniCompatible.getLaunchOptionsSync());
	}

	/**
	 * 开发者手动更新设置setLaunchOptions
	 * 返回Promise，等待SDK初始化完成后回调
	 */
	async setLaunchOptions(params = {}) {
		console.log("🔍 [Deploy] 手动更新设置setLaunchOptions", params);
		let newParams = JSON.parse(JSON.stringify(params))
		if(newParams.adParam)delete newParams.adParam;

		// 调用内部的setLaunchOptions方法，传入开发者的启动参数
		__setLaunchOptionsFun(newParams);

		// 清除1秒超时兜底定时器
		if (setLaunchOptionsTimeout) {
			clearTimeout(setLaunchOptionsTimeout);
			setLaunchOptionsTimeout = null;
			isSetLaunchOptionsTimeout = true;
		}

		// 如果有等待的Promise，则解决它
		if (setLaunchOptionsResolve) {
			setLaunchOptionsResolve();
			setLaunchOptionsResolve = null;
			setLaunchOptionsPromise = null;
		}

		// 等待SDK初始化完成
		await this.readyAsync();
	}

	/**
	 * 获取当前程序用户初始化
	 */
	getUserInfo() {
		return this.__config.userInfo;
	}

	/**
	 * 获取当前环境 production 还是 develop
	 */
	getEnviroment() {
		return ENV;
	}

	/**
	 * 获取OSS公共路径
	 */
	getOssHost() {
		// 动态获取OSS_HOST，确保域名替换正确生效
		return
	}

	/**
	 * 输出静态全局配置
	 * 深拷贝输出，可直接使用
	 */
	getExtConfig() {
		try {
			const {
				getExtConfig
			} = require("../../src/ext-config-handler.js");
			let config = getExtConfig();
			config = config?.extConfig ? config.extConfig : config ? config : {};
			const resolved = JSON.parse(JSON.stringify(config || {}));
			if (Object.keys(resolved).length > 0) {
				return resolved;
			}
		} catch (error) {
			console.warn(
				"⚠️ [Deploy.getExtConfig] 使用ext-config-handler失败，回退到全局变量:",
				error,
			);
		}

		return JSON.parse(JSON.stringify(ext_config || {}));
	}

	getAppId() {
		return APP_ID;
	}

	/**
	 * 获取 HTTPS 域名配置（来自 readyAsync(config) 或 getExtConfigSync）
	 * 对外返回时去掉末尾 `/`
	 * @returns {{ trackHTTPS: string, requestHTTPS: string, cdnHTTPS: string }}
	 */
	getHttps() {
		const stripTrailingSlash = (url) => {
			if (typeof url !== "string") return "";
			return url.trim().replace(/\/+$/, "");
		};

		let config = {};
		try {
			config = comfortable.getExtConfigSync() || {};
		} catch (e) {
			config = {};
		}
		if (!config || Object.keys(config).length === 0) {
			config = ext_config || {};
		}
		const track = stripTrailingSlash(config.trackHTTPS);
		const request = stripTrailingSlash(config.requestHTTPS);
		const cdn = stripTrailingSlash(config.cdnHTTPS);
		return {
			trackHTTPS: track || "https://md.898mk.cn",
			requestHTTPS: request || "https://apile.898mk.cn",
			cdnHTTPS: cdn || "https://cdn.898mk.cn",
		};
	}

	getAppName() {
		return APP_NAME;
	}

	getDramaSource() {
		return ext_config.source;
	}

	getAppVersion() {
		return APP_VERSION;
	}

	getPrivacyPolicy() {
		return ext_config.privacyPolicy;
	}

	getUserPolicy() {
		return ext_config.userPolicy;
	}

	// 获取小程序入口场景码（走合并后的启动参数）
	getScene() {
		try {
			const opts = this.getLaunchOptions();
			return String((opts && opts.scene) || "");
		} catch (error) {
			console.warn("[Deploy] 获取scene失败:", error);
			return "";
		}
	}

	/**
	 * 将 readyAsync(config) 传入的配置同步注入到各配置源
	 * 小游戏入口会传 config；小程序一般不传，后续走 getExtConfigSync
	 */
	_applyRuntimeConfig(runtimeConfig) {
		if (!runtimeConfig || typeof runtimeConfig !== "object" || Object.keys(runtimeConfig).length === 0) {
			return false;
		}
		ext_config = runtimeConfig;
		// 有传入 config = 小游戏入口（小程序走 getExtConfigSync，一般不传）
		__is_minigame__ = true;
		// isWXGameSDK：默认 false；显式 true 才接入 DH
		__is_wx_game_sdk__ = runtimeConfig.isWXGameSDK === true;
		try {
			comfortable.setConfig(runtimeConfig);
		} catch (error) {
			console.warn("⚠️ [Deploy] 设置 utilsComfortable 配置失败:", error);
		}
		try {
			const {
				setRuntimeConfig
			} = require("../../src/ext-config-handler.js");
			setRuntimeConfig(runtimeConfig);
		} catch (error) {
			console.warn("⚠️ [Deploy] 设置 ext-config-handler 配置失败:", error);
		}
		return true;
	}

	/**
	 * 异步准备方法，用于初始化配置和SDK
	 * @param {Object|null} runtimeConfig - 仅小游戏入口需要传入；小程序可不传，走 getExtConfigSync
	 * @returns {Promise<void>}
	 */
	async readyAsync(runtimeConfig = null) {
		// 小游戏：有 config 时立刻同步注入，再进锁
		if (this._applyRuntimeConfig(runtimeConfig)) {
			console.log("✅ [Deploy.readyAsync] 已同步注入运行时配置");
		}

		if (this.__is_ready) {
			console.log("✅ [Deploy.readyAsync] 已初始化，跳过");
			return;
		}

		if (__ready_promise__ != null) {
			return __ready_promise__;
		}

		__ready_promise__ = this._runReadyAsync(runtimeConfig).catch((error) => {
			__ready_promise__ = null;
			throw error;
		});

		return __ready_promise__;
	}

	async _runReadyAsync(runtimeConfig = null) {
		// 小游戏：readyAsync(config) 已注入 → 直接用
		// 小程序：未传 config → comfortable.getExtConfigSync()
		if (ext_config && Object.keys(ext_config).length > 0) {
			console.log("✅ [Deploy.readyAsync] 使用 readyAsync(config) 传入的配置");
		} else if (runtimeConfig && typeof runtimeConfig === "object" && Object.keys(runtimeConfig).length > 0) {
			this._applyRuntimeConfig(runtimeConfig);
			console.log("✅ [Deploy.readyAsync] 使用 readyAsync(config) 传入的配置");
		} else {
			ext_config = comfortable.getExtConfigSync();
			// 小程序路径：同步注入，使 requestHTTPS / trackHTTPS 能被 getInterfaceApi 覆盖域名
			// 不走 _applyRuntimeConfig，避免误标为小游戏
			if (ext_config && typeof ext_config === "object" && Object.keys(ext_config).length > 0) {
				try {
					comfortable.setConfig(ext_config);
				} catch (error) {
					console.warn("⚠️ [Deploy] 同步 getExtConfigSync 配置失败:", error);
				}
			}
			console.log("✅ [Deploy.readyAsync] 使用 getExtConfigSync 获取配置");
		}

		console.log("【Deploy】 readyAsync--->", ext_config);

		// 检查配置获取结果
		if (!ext_config || Object.keys(ext_config).length === 0) {
			throw new Error(
				"未能获取到配置：小程序请配置 ext；小游戏请调用 readyAsync(config) 传入配置",
			);
		}

		// 设置应用配置变量（非运行时配置分支）
		APP_ID = ext_config.appId;
		APP_NAME = ext_config.appName;
		console.log("【Deploy】ext_config---->", ext_config);

		// 微信小游戏 DH 官方 SDK：isWXGameSDK=true 时优先初始化（登录/激励广告走 DH）
		if (__is_wx_game_sdk__) {
			try {
				const {
					default: dhMiniSDKManager
				} = await import("../dhminisdk/DHMiniSDKManager.js");
				await dhMiniSDKManager.initAsync({
					isWXGameSDK: true,
					wxGameCode: ext_config.wxGameCode,
					wxGameSDKConfig: ext_config.wxGameSDKConfig,
					appVersion: APP_VERSION || ext_config.appVersion || "1.0.0",
					appId: ext_config.appId || APP_ID,
				});
				console.log("✅ [Deploy.readyAsync] DH 官方 SDK 已接入");
			} catch (error) {
				console.error("❌ [Deploy.readyAsync] DH 官方 SDK 初始化失败:", error);
				throw error;
			}
		}

		// 腾讯营销 DataNexus：同时配置 wxGameCode + wxGameSecretKey 时启用
		try {
			const {
				default: dataNexusManager
			} = await import("../datanexus/DataNexusManager.js");
			dataNexusManager.configure({
				wxGameCode: ext_config.wxGameCode,
				wxGameSecretKey: ext_config.wxGameSecretKey,
				appId: ext_config.appId,
				debug: ext_config.debug === true,
			});
		} catch (error) {
			console.warn("⚠️ [Deploy.readyAsync] DataNexus 配置跳过:", error && error.message);
		}

		// 初始化SDK（进行中的初始化复用同一实例，避免并发重复创建）
		if (!fbisdk) {
			fbisdk = initFBISDK(
				APP_ID,
				APP_NAME,
				APP_VERSION,
				ENV,
				ext_config,
			);
		}


		// 是否等待 setLaunchOptions：只看平台原生 query，避免读到手动覆盖后误判
		let options = uniCompatible.getPlatformLaunchOptionsSync();

		// 判断options.query是否为空对象
		// 当options.query为空对象时，需要等待setLaunchOptions调用（主要针对微信小程序）
		let isEmptyQuery = !options.query || (typeof options.query === "object" && Object.keys(options.query)
			.length === 0);

		// 检查当前平台，主要针对微信环境
		let isWeixin = false;
		try {
			isWeixin = typeof wx !== "undefined" && !!wx.getSystemInfoSync;
		} catch (error) {
			// 平台检测失败，继续执行
		}

		// 小游戏：readyAsync(config) 传入配置时，不再等待 setLaunchOptions
		// 小程序：不传 config，query 为空时仍等待 setLaunchOptions
		const fromReadyAsyncConfig = !!(
			runtimeConfig &&
			typeof runtimeConfig === "object" &&
			Object.keys(runtimeConfig).length > 0
		);

		let isSetLaunchOptions = isEmptyQuery && isWeixin && !fromReadyAsyncConfig;
		console.log("isSetLaunchOptions--->",isSetLaunchOptions)

		// 如果需要等待setLaunchOptions调用，则创建等待Promise
		if (isSetLaunchOptions) {
			// 创建等待Promise，带1秒超时兜底
			console.log("!setLaunchOptionsPromise--->",!setLaunchOptionsPromise)
			console.log("!isSetLaunchOptionsTimeout--->",!isSetLaunchOptionsTimeout)
			
			if (!setLaunchOptionsPromise && !isSetLaunchOptionsTimeout) {
				setLaunchOptionsPromise = new Promise((resolve) => {
					setLaunchOptionsResolve = resolve;

					// 1秒超时兜底，如果开发者没有调用setLaunchOptions，就主动触发
					setLaunchOptionsTimeout = setTimeout(() => {
						console.log(
							"🔍 [Deploy] 1秒超时兜底，如果开发者没有调用setLaunchOptions，就主动触发",
						);
						if (setLaunchOptionsResolve) {
							__setLaunchOptionsFun();
							setLaunchOptionsResolve();
							setLaunchOptionsResolve = null;
							setLaunchOptionsPromise = null;
							setLaunchOptionsTimeout = null;
						}
					}, 1000);
				});
			}

			// 等待setLaunchOptions被调用
			await setLaunchOptionsPromise;
			// 若等待期间已手动写入并锁定，勿再无参重置
			if (!__launch_options_sealed__) {
				__setLaunchOptionsFun();
			}
		} else if (!__launch_options_sealed__ && !__resolved_launch_options__) {
			// 直接设置启动参数（已有手动锁定/全局值则跳过，防止冲掉 channel）
			__setLaunchOptionsFun();
		} else {
			console.log("🔒 [Deploy] 跳过重复写入启动参数", {
				sealed: __launch_options_sealed__,
				channel: __resolved_launch_options__ && __resolved_launch_options__.channel,
			});
		}


		try {
			//初始化配置（含登录）
			const initResult = await __init__();

			// 从fbisdk获取初始化后的配置信息
			this.__config = {
				attributeInfo: initResult.attributeInfo || fbisdk.__attribution_cache__,
				userInfo: initResult.userInfo || fbisdk.__login_cache__,
				...initResult,
			};

			// 检查配置是否有效
			if (!this.__config.attributeInfo) {
				console.warn("⚠️ [Deploy] 警告: 归因信息为空");
			}

			if (!this.__config.userInfo) {
				console.warn("⚠️ [Deploy] 警告: 用户信息为空");
			}

			// 登录完成后拉取功能支持配置（微信: sp/mini/app/conf/function）
			// 不能调用 getAdvertConfigAsync()：其内部会 await readyAsync，在本流程中会死锁
			// 注意：DataNexus 初始化会立刻发 START_APP 等请求，必须放在广告配置之后，
			// 避免与 getAdConfig 同时占满微信小游戏「最多 5 个 request」限制。
			await this._fetchAdvertConfigAfterLogin();

			// 腾讯营销 DataNexus：广告配置拉取后再 bind。
			// LOAD_FINISH 必须由业务在 loading / 闪屏真正结束时显式上报。
			try {
				const userInfo = this.__config.userInfo;
				if (userInfo && userInfo.userId) {
					const {
						default: dataNexusManager
					} = await import("../datanexus/DataNexusManager.js");
					dataNexusManager.bindUser({
						userId: userInfo.userId,
						createdDt: userInfo.createdDt,
					});
				}
			} catch (error) {
				console.warn("⚠️ [Deploy] DataNexus bindUser 跳过:", error && error.message);
			}

			this.__is_ready = true;
			//已完成初始化，回收promise
			__init__promise__ = null;

			// 初始化 AD
			try {
				// 动态导入 AD 以避免循环依赖
				const {
					default: ad
				} = await import("./AD.js");
				if (ad && typeof ad.init === "function") {
					// 确保 fbisdk 已初始化
					if (!fbisdk) {
						console.warn(
							"⚠️ [Deploy] fbisdk 未初始化，跳过 AD 初始化",
						);
					} else {
						ad.init();
						console.log("✅ [Deploy] AD 初始化成功");
					}
				} else {
					console.warn("⚠️ [Deploy] AD 或其 init 方法不存在");
				}
			} catch (error) {
				console.error("❌ [Deploy] AD 初始化失败:", error);
				// 不抛出错误，避免影响主流程
			}

			// 🔥 SDK 初始化完成后，触发 Track 发送缓存的事件
			try {
				const track = require("./Track.js").default;
				if (
					track &&
					typeof track.flushPendingEvents === "function"
				) {
					const pendingCount = track.getPendingCount();
					if (pendingCount > 0) {
						console.log(
							`📤 [Deploy] 检测到 ${pendingCount} 个缓存事件，开始发送...`,
						);
						await track.flushPendingEvents();
					}
				}
			} catch (error) {
				console.warn("⚠️ [Deploy] 发送缓存事件失败:", error);
				// 不抛出错误，避免影响主流程
			}
		} catch (error) {
			console.error("❌ [Deploy] readyAsync() 执行失败:", error);
			console.error("❌ [Deploy] 错误堆栈:", error.stack);
			throw error;
		}
	}

	/**
	 * 登录完成后拉取功能支持配置（供 readyAsync 内部使用，避免与 readyAsync 死锁）
	 */
	async _fetchAdvertConfigAfterLogin() {
		if (this.__config.advertConfig) {
			return this.__config.advertConfig;
		}

		if (!fbisdk) {
			throw new Error("fbisdk 未初始化，无法获取功能支持配置");
		}

		if (!__adconfig_init_promise__) {
			__adconfig_init_promise__ = new Promise((resolve, reject) => {
				const __func__ = () => {
					fbisdk
						.adConfigAsync()
						.then((result) => {
							const {
								isRiskControl,
								riskReason
							} = result || {};
							console.log("✅ [Deploy] 功能支持配置获取成功", result);
							if (isRiskControl) {
								fbisdk.trackAsync("$Shield", {
									reason: riskReason
								});
							}
							resolve(result);
						})
						.catch((error) => {
							console.error("❌ [Deploy] 功能支持配置获取失败:", error);
							uniCompatible.showModal({
								title: "提示",
								content: "获取配置信息失败~",
								showCancel: true,
								confirmText: "重试",
								cancelText: "取消",
								confirmColor: "#FF4500",
								success: function(res) {
									if (res.confirm) {
										__func__();
									} else if (res.cancel) {
										reject(error);
									}
								},
							});

							const reason = error ? JSON.stringify(error) : "";
							fbisdk.trackAsync("$SdkError", {
								value: "adConfig-failure",
								reason
							});
						});
				};

				__func__();
			});
		}

		const config = await __adconfig_init_promise__;
		if (!this.__config.advertConfig) {
			this.__config.advertConfig = config;
			__adconfig_init_promise__ = null;
		}
		return this.__config.advertConfig;
	}

	/**
	 * @description
	 * 获取广告相关配置（功能支持配置）
	 */
	async getAdvertConfigAsync() {
		if (this.__config.advertConfig) {
			return this.__config.advertConfig;
		}

		await this.readyAsync();

		// readyAsync 内已拉取；若仍为空则补拉一次
		if (!this.__config.advertConfig) {
			await this._fetchAdvertConfigAfterLogin();
		}

		console.log('获取广告相关配置 getAdvertConfigAsync', this.__config.advertConfig)

		return this.__config.advertConfig;
	}

	/**
	 * @description
	 * 获取系统用户信息
	 */
	async getUserInfoAsync() {
		await this.readyAsync();
		return this.__config.userInfo;
	}

	/**
	 * 记录已添加好桌面
	 */
	recordAddedShortcut() {
		let key = `${this.getAppId()}-isAddShortcutUser`;
		uniCompatible.setStorageSync(key, true);
	}

	/**
	 * 输出所有配置信息
	 */
	printAllConfig() {
		let options = this.getLaunchOptions();

		let t = {
			ENV,
			APP_VERSION,
			microapp,
			launchOptions: options,
			ext_config,
			config: this.__config,
		};
		let json = JSON.stringify(t, null, 2);
		return json;
	}

	/**
	 * 初始化配置管理器
	 */
	async init() {
		try {
			await this.loadPlatformConfig();
			this.initialized = true;
			console.log("【Deploy】配置管理器初始化完成");
		} catch (error) {
			console.error("【Deploy】初始化失败:", error);
			throw error;
		}
	}

	/**
	 * 加载平台特定配置
	 */
	async loadPlatformConfig() {
		try {
			// 使用ext-config-handler统一处理配置获取
			const extConfigHandler = require("../../src/ext-config-handler.js");
			this.platformConfig = extConfigHandler.getExtConfig();
			console.log("✅ [Deploy] 平台配置加载成功:", this.platformConfig);
		} catch (error) {
			console.warn("【Deploy】平台配置加载失败，使用默认配置:", error);
			this.platformConfig = {
				platform: "unknown",
				supported: false,
			};
		}
	}

	/**
	 * 获取应用基础配置
	 */
	getAppConfig() {
		return {
			appId: ext_config.appId,
			appName: ext_config.appName,
			privacyPolicy: ext_config.privacyPolicy,
			userPolicy: ext_config.userPolicy,
			desc: ext_config.desc,
		};
	}

	/**
	 * 获取广告配置
	 */
	getAdConfig() {
		return ext_config.advertis || [];
	}

	/**
	 * 根据code获取特定广告位配置
	 */
	getAdSlotConfig(code) {
		const adConfig = this.getAdConfig();
		return adConfig.find((ad) => ad.code === code) || null;
	}

	/**
	 * 获取平台配置
	 */
	getPlatformConfig() {
		return this.platformConfig;
	}

	/**
	 * 检查是否已初始化
	 */
	isInitialized() {
		return this.initialized;
	}

	/**
	 * 获取完整配置信息
	 */
	getAllConfig() {
		return {
			app: this.getAppConfig(),
			ads: this.getAdConfig(),
			platform: this.getPlatformConfig(),
			initialized: this.isInitialized(),
		};
	}

	/**
	 * 更新配置（用于动态配置修改）
	 */
	updateConfig(newConfig) {
		if (newConfig.app) {
			Object.assign(ext_config, newConfig.app);
		}
		if (newConfig.ads) {
			ext_config.advertis = newConfig.ads;
		}
		if (newConfig.platform) {
			this.platformConfig = {
				...this.platformConfig,
				...newConfig.platform
			};
		}

		console.log("【Deploy】配置已更新");
	}

	/**
	 * 验证配置完整性
	 */
	validateConfig() {
		const issues = [];

		// 检查基础配置
		if (!ext_config.thirdAppId) issues.push("缺少thirdAppId");
		if (!ext_config.appId) issues.push("缺少appId");
		if (!ext_config.md5Key) issues.push("缺少md5Key");

		// 检查广告配置
		const adConfig = this.getAdConfig();
		if (!adConfig || adConfig.length === 0) {
			issues.push("缺少广告位配置");
		} else {
			adConfig.forEach((ad, index) => {
				if (!ad.adUnitId) issues.push(`广告位${index}缺少adUnitId`);
				if (!ad.code) issues.push(`广告位${index}缺少code`);
			});
		}

		return {
			valid: issues.length === 0,
			issues: issues,
		};
	}

	/**
	 * 禁用用户截屏和录屏
	 */
	disableUserScreenRecord() {
		try {
			if (
				typeof uniCompatible !== "undefined" &&
				uniCompatible.disableUserScreenRecord
			) {
				uniCompatible.disableUserScreenRecord({
					success: (res) => {
						console.log("✅ [Deploy] 成功禁用录屏", res);
					},
					fail: (err) => {
						console.error("❌ [Deploy] 禁用录屏失败", err);
					}
				});
			} else {
				console.warn("【Deploy】uniCompatible不可用");
			}
		} catch (error) {
			console.warn("【Deploy】禁用录屏失败:", error);
		}
	}
	// 风控监听（仅抖音端有效）
	async riskControlListen() {
		try {
			if (!this.__is_ready) {
				await this.readyAsync();
			}
		} catch (error) {
			console.warn("⚠️ [Deploy] 风控监听前初始化失败:", error);
			return;
		}

		if (!fbisdk || typeof fbisdk.riskControlListen !== "function") {
			console.warn("⚠️ [Deploy] fbisdk未初始化，无法开启风控监听");
			return;
		}
		return fbisdk.riskControlListen();
	}

	/**
	 * 获取存储状态信息（调试用）
	 */
	getStorageInfo() {
		const info = {
			globalState: this.getState(),
			localKeys: {
				balance: `${this.getAppId()}_balance`,
				vip: `${this.getAppId()}_isvip`,
				recentList: `${this.getAppId()}-recentList`,
				shortcut: `${this.getAppId()}-isAddShortcutUser`,
			},
			localValues: {},
		};

		// 读取各个本地存储的值
		Object.keys(info.localKeys).forEach((key) => {
			try {
				info.localValues[key] = uniCompatible.getStorageSync(
					info.localKeys[key],
				);
			} catch (error) {
				info.localValues[key] = `读取失败: ${error.message}`;
			}
		});

		return info;
	}
}

/**
 * 管理全局配置 所有配置出口
 */
let deploy = new Deploy();

// 将平台特定的广告模块附加到deploy实例上，以支持Deploy.fbiadCFwx的访问方式
deploy.fbiadCFwx = fbiadCFwx;
deploy.fbiadCFtt = fbiadCFtt;

Deploy.getInstance = function() {
	return deploy;
};


// 同时导出类和实例，保持兼容性
export {
	Deploy,
	fbiadCFwx,
	fbiadCFtt
};
export default deploy;