import comfortable from "./fbiadComfortable/fbiadCFIndex.js";

/*
	 原生模板广告加载器
*/
let NativeAdLoaderBase = null; 
let initPromise = null;

// 初始化原生模板广告基类
const initNativeAdLoaderBase = async () => {
	if (initPromise) {
		return initPromise;
	}
	
	initPromise = (async () => {
		try {
			NativeAdLoaderBase = await comfortable.NativeAdLoaderAsync();
			// 原生模板广告基类初始化成功
			return NativeAdLoaderBase;
		} catch (error) {
			// 获取原生模板广告基类失败
			throw error;
		}
	})();
	
	return initPromise;
};

/**
 * @description: 初始化一个原生模板广告，开发者需要将参数置换为自己小程序的广告id
 * 支持微信小程序原生模板广告的所有特性：
 * 1. 自动拉取广告数据并显示
 * 2. 支持定时刷新（adIntervals >= 30秒）
 * 3. 支持样式配置（left, top, width, fixed等）
 * 4. 支持显示/隐藏控制
 * 5. 支持事件监听（onLoad, onError, onClose, onHide, onResize等）
 */
class NativeAdLoader {
    constructor(params) {
        this.params = params;
        this.initialized = false;
        this.baseLoader = null;
        
        // 异步初始化基类
        this.initPromise = this.initBase();
    }
    
    async initBase() {
        try {
            if (!NativeAdLoaderBase) {
                await initNativeAdLoaderBase();
            }
            
            // 创建基类实例
            this.baseLoader = new NativeAdLoaderBase(this.params);
            this.initialized = true;
            
            return this.baseLoader;
        		} catch (error) {
			// 原生模板广告基类初始化失败
			throw error;
		}
    }
    
    async ensureInitialized() {
        if (!this.initialized) {
            await this.initPromise;
        }
        return this.baseLoader;
    }
    
    async load() {
        const loader = await this.ensureInitialized();
        return loader.load();
    }
    
    async show() {
        const loader = await this.ensureInitialized();
        return loader.show();
    }
    
    async hide() {
        const loader = await this.ensureInitialized();
        return loader.hide();
    }
    
    isShow() {
        if (!this.initialized) {
            return false;
        }
        return this.baseLoader.isShow();
    }
    
    async destroy() {
        const loader = await this.ensureInitialized();
        return loader.destroy();
    }
    
    isSame(params) {
        // 如果基类还没初始化，认为不相同，需要重新创建
        if (!this.initialized) {
            return false;
        }
        return this.baseLoader.isSame(params);
    }
    
    onLoad(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.onLoad === 'function') {
                loader.onLoad(callback);
            }
        });
    }
    
    onError(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.onError === 'function') {
                loader.onError(callback);
            }
        });
    }
    
    onClose(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.onClose === 'function') {
                loader.onClose(callback);
            }
        });
    }
    
    onHide(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.onHide === 'function') {
                loader.onHide(callback);
            }
        });
    }
    
    onResize(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.onResize === 'function') {
                loader.onResize(callback);
            }
        });
    }
    
    offLoad(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.offLoad === 'function') {
                loader.offLoad(callback);
            }
        });
    }
    
    offError(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.offError === 'function') {
                loader.offError(callback);
            }
        });
    }
    
    offClose(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.offClose === 'function') {
                loader.offClose(callback);
            }
        });
    }
    
    offHide(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.offHide === 'function') {
                loader.offHide(callback);
            }
        });
    }
    
    offResize(callback) {
        this.ensureInitialized().then(loader => {
            if (callback && typeof callback === 'function' && typeof loader.offResize === 'function') {
                loader.offResize(callback);
            }
        });
    }
}

export default NativeAdLoader;