// 配置获取：
// - 小游戏：readyAsync(config) / setConfig 注入
// - 小程序：平台 getExtConfigSync
// 不按环境分支判断，有注入配置则优先使用

// 存储传入的配置
let runtimeConfig = null;

/**
 * 设置运行时配置
 * @param {Object} config - 配置对象
 */
function setRuntimeConfig(config) {
  runtimeConfig = config;
}

/**
 * 获取运行时配置
 * @returns {Object} 配置对象
 */
function getRuntimeConfig() {
  return runtimeConfig || {};
}

// 微信环境（兼容无 getWindowInfo 的基础库）
const isWX = () =>
  typeof wx !== "undefined" &&
  typeof tt === "undefined" &&
  !!(
    wx.getWindowInfo ||
    wx.getSystemInfoSync ||
    wx.getSystemInfo ||
    wx.createRewardedVideoAd
  );
const isTT = () => typeof tt !== "undefined" && tt.getSystemInfo && "tt";
const ENV = isTT() || isWX();

function hasValidConfig(config) {
  return !!(config && typeof config === "object" && Object.keys(config).length > 0);
}

/**
 * Utils 舒适化模块
 * 提供通用的舒适化工具功能
 */
const utilsComfortable = {
  // 缓存配置数据
  _cachedExtConfig: null,
  _extConfigLoaded: false,

  // 初始化
  init: function (options) {
    this.options = options || {};
    return this;
  },

  /**
   * 设置运行时配置
   * @param {Object} config - 配置对象
   */
  setConfig: function (config) {
    setRuntimeConfig(config);
  },

  /**
   * 获取扩展配置
   * 优先 readyAsync(config) 注入的运行时配置，否则尝试平台 getExtConfigSync
   */
  getExtConfigSync: function () {
    // 抖音平台
    if (isTT()) {
      try {
        const config = getRuntimeConfig();
        if (hasValidConfig(config)) {
          return config;
        }

        if (typeof tt.getExtConfigSync === "function") {
          // 抖音可能把业务字段放在顶层，也可能放在 extConfig；合并后保留 requestHTTPS / trackHTTPS
          const e = tt.getExtConfigSync() || {};
          const nested =
            e.extConfig && typeof e.extConfig === "object" ? e.extConfig : {};
          const { extConfig: _ignored, ...top } = e;
          return { ...top, ...nested };
        }
        return {};
      } catch (error) {
        console.error("❌ [抖音平台] 扩展配置获取失败:", error);
        return {};
      }
    }

    // 微信平台
    if (isWX()) {
      try {
        const config = getRuntimeConfig();
        if (hasValidConfig(config)) {
          return config;
        }

        if (typeof wx.getExtConfigSync === "function") {
          let e = wx.getExtConfigSync();
          return e || {};
        }

        console.warn(
          "⚠️ [微信] 未找到 getExtConfigSync，且未传入运行时配置。请调用 readyAsync(config)",
        );
        return {};
      } catch (error) {
        console.error("❌ [微信平台] 扩展配置获取失败:", error);
        return {};
      }
    }

    // 其他环境
    try {
      const config = getRuntimeConfig();
      if (hasValidConfig(config)) {
        return config;
      }
      return {};
    } catch (error) {
      return {};
    }
  },

  /**
   * 获取小程序环境信息 - 平台兼容性
   */
  getEnvInfoSync: function () {
    if (isTT()) {
      try {
        let { microapp } = tt.getEnvInfoSync();
        let { mpVersion, envType, appId } = microapp;
        return { mpVersion, envType, appId };
      } catch (error) {
        console.error("❌ [抖音平台] 环境信息获取失败:", error);
        return null;
      }
    } else if (isWX()) {
      try {
        if (typeof wx.getAccountInfoSync === "function") {
          let { miniProgram } = wx.getAccountInfoSync();
          let { version, appId, envVersion } = miniProgram;
          return { mpVersion: version, envType: envVersion, appId };
        }
        // 无 getAccountInfoSync 时兜底
        const runtime = getRuntimeConfig();
        let sdkVersion = "1.0.0";
        try {
          if (typeof wx.getSystemInfoSync === "function") {
            sdkVersion = wx.getSystemInfoSync().SDKVersion || sdkVersion;
          }
        } catch (e) {}
        return {
          mpVersion: runtime.app_version || runtime.appVersion || sdkVersion,
          envType: "release",
          appId: runtime.appId || "",
        };
      } catch (error) {
        console.error("❌ [微信平台] 环境信息获取失败:", error);
        return null;
      }
    }

    console.warn("⚠️ [utilsCFIndex] 未匹配到任何平台分支，返回null");
    return null;
  },

  /**
   * 获取平台配置数据
   */
  getConfigData: function () {
    if (isTT()) {
      return { platform: "ocean" };
    } else if (isWX()) {
      return { platform: "tencent" };
    }

    console.warn("⚠️ [utilsCFIndex] 未匹配到任何平台分支，返回默认配置");
    return { platform: "unknown" };
  },

  // 本地存储
  storage: {
    set: function (key, value) {
      try {
        const stringValue = typeof value === "string" ? value : JSON.stringify(value);
        if (typeof localStorage !== "undefined") {
          localStorage.setItem(key, stringValue);
        } else if (typeof wx !== "undefined" && wx.setStorageSync) {
          wx.setStorageSync(key, stringValue);
        }
      } catch (e) {
        // 存储设置失败
      }
    },

    get: function (key, defaultValue = null) {
      try {
        if (typeof localStorage !== "undefined") {
          const value = localStorage.getItem(key);
          return value ? JSON.parse(value) : defaultValue;
        }
        if (typeof wx !== "undefined" && wx.getStorageSync) {
          const value = wx.getStorageSync(key);
          if (value === "" || value === undefined || value === null) {
            return defaultValue;
          }
          return typeof value === "string" ? JSON.parse(value) : value;
        }
        return defaultValue;
      } catch (e) {
        return defaultValue;
      }
    },

    remove: function (key) {
      try {
        if (typeof localStorage !== "undefined") {
          localStorage.removeItem(key);
        } else if (typeof wx !== "undefined" && wx.removeStorageSync) {
          wx.removeStorageSync(key);
        }
      } catch (e) {
        // 存储删除失败
      }
    },
  },

  // 工具方法
  utils: {
    generateUUID: function () {
      return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
        const r = (Math.random() * 16) | 0;
        const v = c === "x" ? r : (r & 0x3) | 0x8;
        return v.toString(16);
      });
    },

    formatTime: function (timestamp) {
      const date = new Date(timestamp);
      return date.toISOString();
    },

    debounce: function (func, wait) {
      let timeout;
      return function executedFunction(...args) {
        const later = () => {
          clearTimeout(timeout);
          func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
      };
    },

    throttle: function (func, limit) {
      let inThrottle;
      return function (...args) {
        if (!inThrottle) {
          func.apply(this, args);
          inThrottle = true;
          setTimeout(() => (inThrottle = false), limit);
        }
      };
    },
  },
};

export default utilsComfortable;
