import comfortable from "./fbiCoreComfortable/fbiCoreCFIndex.js";
import uniCompatible from "../../utils/utilsComfortable/uniCompatible.js";
import {
	enrichTrackEventPageUrl
} from "./fbiCorePageUrl.js";

// 获取API配置的函数（移除缓存，确保每次都能获取最新配置）
const getInterfaceApiAsync = async () => {
	try {
		// console.log('🔍 [fbiCoreHttp] 获取最新的API配置');
		const interfaceApi = await comfortable.getInterfaceApi();
		return interfaceApi;
	} catch (error) {
		console.error("获取API配置失败:", error);
		throw error;
	}
};

/**
 * 网络请求，返回promise
 */
let requestAsync = (method, url, data) => {
	// console.log('🚀 [fbiCoreHttp] requestAsync 开始');
	// console.log(`📋 [fbiCoreHttp] 请求方法: ${method}, URL: ${url}`);

	return new Promise((resolve, reject) => {
		try {
			method = (method + "").toUpperCase();
			const bodyMethods = ["POST", "PUT", "DELETE", "PATCH"];
			const queryMethods = ["GET", "OPTIONS", "HEAD"];
			if (!bodyMethods.includes(method) && !queryMethods.includes(method)) {
				method = "GET";
			}

			let options = {
				url: url,
				method: method,
				success: function(res) {
					// console.log('✅ [fbiCoreHttp] success回调被触发:', res);

					let responseData = res?.data;
					// 检查业务状态码
					if (responseData && (responseData.code === "300002" || responseData.code ===
							"300003")) {
						// token失效，清除缓存
						uniCompatible.removeStorageSync('AUTH_TOKEN_DATA');

						// 返回接口原始响应数据，而不是 Error 对象
						reject({
							code: responseData.code,
							errMsg: responseData.error ||
								responseData.msg ||
								`服务器错误: HTTP ${res.statusCode}`,
							statusCode: res.statusCode,
							response: responseData, // 原始接口返回数据
							headers: res.header,
						});
						return;
					}

					// console.log('✅ [fbiCoreHttp] 准备resolve响应数据:', responseData);
					//仅返回数据 不需要header信息
					resolve(responseData);
				},
				fail: function(err) {
					console.error(
						"❌ [fbiCoreHttp] fail回调被触发:",
						err.errMsg || err.message,
					);
					// 返回统一格式的错误对象
					reject({
						code: "NETWORK_ERROR",
						errMsg: err.errMsg || err.message || "网络请求失败",
						originalError: err,
					});
				},
			};

			// 修复：根据请求方法处理参数
			if (queryMethods.includes(method)) {
				// GET/OPTIONS/HEAD请求：参数作为查询字符串附加到URL
				if (data && typeof data === "object") {
					const queryString = formatToQueryParams(data);
					if (queryString) {
						url = url + (url.includes("?") ? "&" : "?") + queryString;
					}
				}
				options.url = url;
			} else {
				// POST/PUT/DELETE/PATCH请求：参数放在请求体中
				options.data = data;
				options.header = {
					"content-type": "application/json"
				};
			}

			// 注入 Authorization 头部
			try {
				let tokenDataStr = uniCompatible.getStorageSync('AUTH_TOKEN_DATA');
				let tokenData = null;
				if (tokenDataStr) {
					tokenData = typeof tokenDataStr === 'string' ? JSON.parse(tokenDataStr) : tokenDataStr;
				}
				if (tokenData && tokenData.accessToken) {
					options.header = options.header || {};
					options.header['Authorization'] = tokenData.accessToken;
				}
			} catch (e) {
				console.error('❌ [fbiCoreHttp] 注入Authorization头部失败:', e);
			}

			// console.log('📋 [fbiCoreHttp] 最终请求参数:', options);
			// console.log('📋 [fbiCoreHttp] 调用 uniCompatible.request()...');

			// 调用 uniCompatible.request，它会使用我们传入的success/fail回调
			uniCompatible.request(options);
		} catch (error) {
			console.error("❌ [fbiCoreHttp] requestAsync 异常:", error);
			reject(error);
		}
	});
};

// 清理对象中的undefined值
function cleanUndefinedValues(obj) {
	const cleaned = {};
	for (const [key, value] of Object.entries(obj)) {
		if (value === undefined || value === "undefined") {
			cleaned[key] = "";
		} else if (value === null || value === "null") {
			cleaned[key] = "";
		} else {
			cleaned[key] = value;
		}
	}
	return cleaned;
}

function formatToQueryParams(params) {
	// 先清理undefined值
	const cleanParams = cleanUndefinedValues(params);

	const queryParts = [];
	for (const [key, value] of Object.entries(cleanParams)) {
		const encodedKey = encodeURIComponent(key);
		const encodedValue = encodeURIComponent(value);
		queryParts.push(`${encodedKey}=${encodedValue}`);
	}
	return queryParts.join("&");
}

// 埋点事件发送队列
let trackQueue = [];
let trackTimer = null;
const BATCH_SIZE = 6;
const BATCH_TIMEOUT = 1000;

// 巨量归因回传：本次小程序启动生命周期内只请求一次
let startAccountCalled = false;

class Api {
	constructor(env) {
		this.env = env;
	}

	async requestAsync(method, url, data) {
		return requestAsync(method, url, data);
	}

	async userLoginAsync(data) {
		const interfaceApi = await getInterfaceApiAsync();
		const {
			loginApi
		} = interfaceApi;

		let {
			DOMAIN,
			USER_LOGIN
		} = loginApi;
		let url = `${DOMAIN}${USER_LOGIN}`;
		const method = "POST";

		try {
			console.log("userLoginAsync---url->", url);
			console.log("userLoginAsync---data->", data);
			let result = await requestAsync(method, url, data);
			return result;
		} catch (error) {
			console.error("❌ 登录会话请求失败:", error);
			throw error;
		}
	}

	async getAdConfigAsync(data) {
		const interfaceApi = await getInterfaceApiAsync();
		const {
			loginApi
		} = interfaceApi;
		const method = loginApi.AD_CONFIG == "sp/mini/app/conf/function" ? 'GET' : "POST";
		let url = `${loginApi.DOMAIN}${loginApi.AD_CONFIG}`;
		let adConfig = requestAsync(method, url, data);
		console.log("getAdConfigAsync--->",adConfig);
		return adConfig;
	}
	
	// 上报用户录屏-截屏
	async riskControlListenAsync(data) {
		if (typeof tt === "undefined") {
			return;
		}
		const interfaceApi = await getInterfaceApiAsync();
		const {
			loginApi
		} = interfaceApi;
		if (!loginApi.SCRRE_USERS) {
			console.warn("⚠️ [riskControlListenAsync] 未配置 SCRRE_USERS 接口");
			return;
		}
		const method = "GET";
		let url = `${loginApi.DOMAIN}${loginApi.SCRRE_USERS}`;
		return requestAsync(method, url, data);
	}

	/**
	 * 巨量引擎-小程序事件回传接口（仅抖音平台）
	 * @param {Object} data - 回传数据
	 */
	async startAccountAsync(data) {
		// 检查是否为抖音平台，使用 typeof 避免 ReferenceError
		if (typeof tt === "undefined") {
			return;
		}

		if (startAccountCalled) {
			return;
		}
		startAccountCalled = true;

		try {
			const interfaceApi = await getInterfaceApiAsync();
			const {
				loginApi
			} = interfaceApi;

			// 检查是否配置了 START_ACCOUNT 接口
			if (!loginApi.START_ACCOUNT) {
				return;
			}

			let url = `${loginApi.DOMAIN}${loginApi.START_ACCOUNT}`;
			return requestAsync("POST", url, data);
		} catch (error) {
			console.error("❌ [startAccountAsync] 发送失败:", error);
			// 静默失败，不影响主流程
		}
	}


	/**
	 * @description
	 * 事件埋点，放入队列进行合并上报
	 * 报错不对外
	 * @param {Object} data
	 */
	async trackAsync(data) {
		trackQueue.push(data);

		if (trackQueue.length >= BATCH_SIZE) {
			this.flushTrackQueue();
		} else if (!trackTimer) {
			trackTimer = setTimeout(() => {
				this.flushTrackQueue();
			}, BATCH_TIMEOUT);
		}
		return true;
	}

	async flushTrackQueue() {
		if (trackTimer) {
			clearTimeout(trackTimer);
			trackTimer = null;
		}
		if (trackQueue.length === 0) return;

		const eventsToSend = trackQueue.map((event) => enrichTrackEventPageUrl({
			...event
		}));
		trackQueue = [];

		try {
			const interfaceApi = await getInterfaceApiAsync();
			const {
				api
			} = interfaceApi;
			let url = `${api.DOMAIN}${api.TRACK_API}`;

			// 使用 POST 方式批量发送 JSON 数组
			await requestAsync("POST", url, eventsToSend);
			console.log(`✅ [fbiCoreHttp] 合并上报成功: 发送了 ${eventsToSend.length} 个事件`);
		} catch (e) {
			console.error("❌ [fbiCoreHttp] 合并上报失败:", e);
		}
	}
}

let http = {
	enviroment(env) {
		return new Api(env);
	},
};

export default http;