import comfortable from "./fbiCoreComfortable/fbiCoreCFIndex.js"
import uniCompatible from "../../utils/utilsComfortable/uniCompatible.js"

let __cache__
let __login_inflight__ = null
let key = 'AUTH_TOKEN_DATA'

/**
 * 服务端 expireAt 可能是秒或毫秒；统一成毫秒再和 Date.now() 比较
 */
function normalizeExpireAt(expireAt) {
	if (expireAt == null || expireAt === "") return null;
	const n = Number(expireAt);
	if (!Number.isFinite(n) || n <= 0) return null;
	// 小于 1e12 视为秒（约 2001 年之前的毫秒时间戳不可能是有效过期时间）
	return n < 1e12 ? n * 1000 : n;
}

try{
	__cache__ = uniCompatible.getStorageSync(key)
	
	if(__cache__ && Object.prototype.toString.call(__cache__) == '[object String]'){
		__cache__ = JSON.parse(__cache__)
	}

	// 验证缓存数据完整性：必须包含 userId 和 accessToken 字段，否则视为无效缓存
	if(__cache__ && (!__cache__.userId || !__cache__.accessToken)){
		console.warn('⚠️ [loginAsync] 本地登录缓存数据不完整（缺少 userId 或 accessToken），丢弃缓存');
		__cache__ = null;
		uniCompatible.removeStorageSync(key);
	}

	// 丢弃默认兼容模式写入的假登录（小游戏 isWX 误判时会产生）
	if (
		__cache__ &&
		(String(__cache__.accessToken || '').indexOf('default_token_') === 0 ||
			String(__cache__.userId || '').indexOf('default_userId_') === 0)
	) {
		console.warn('⚠️ [loginAsync] 检测到假登录缓存，丢弃并重新登录');
		__cache__ = null;
		uniCompatible.removeStorageSync(key);
	}

	if (__cache__ && __cache__.expireAt != null) {
		const normalized = normalizeExpireAt(__cache__.expireAt);
		if (normalized != null) {
			__cache__.expireAt = normalized;
		}
	}
	
}catch(error){
	console.error('load __login__cache__info__ error', error)
	__cache__ = null;
}

function clearLoginCache() {
	__cache__ = null;
	__login_inflight__ = null;
	try {
		uniCompatible.removeStorageSync(key);
	} catch (e) {}
}
	
function saveCacheForGuest(value){
	const next = { ...value };
	const normalized = normalizeExpireAt(next.expireAt);
	if (normalized != null) {
		next.expireAt = normalized;
	}
	__cache__ = next
	uniCompatible.setStorageSync(key, next)
}

function getValidCache(app_id) {
	if (!__cache__ || !__cache__.accessToken) {
		return null;
	}
	const cacheAppId = __cache__.appId;
	if (cacheAppId && app_id && String(cacheAppId) !== String(app_id)) {
		console.warn('⚠️ [loginAsync] 登录缓存 appId 不匹配，重新登录', {
			cacheAppId,
			app_id,
		});
		clearLoginCache();
		return null;
	}
	if (__cache__.expireAt) {
		const expireAt = normalizeExpireAt(__cache__.expireAt) || __cache__.expireAt;
		if (Date.now() >= expireAt) {
			console.log('⚠️ [loginAsync] 本地缓存的登录信息已过期，重新登录');
			return null;
		}
	}
	return __cache__;
}

// 登录（带进行中 Promise 去重，避免并发打两次 user/login）
const loginAsync = async (app_id, env, loginParams) => {
	console.log('🔍 [loginAsync] 登录参数:', {
		app_id,
		env,
		loginParams: loginParams ? Object.keys(loginParams) : null
	});

	const cached = getValidCache(app_id);
	if (cached) {
		console.log('✅ [loginAsync] 使用本地缓存的登录信息（跳过网络登录）');
		return cached;
	}

	if (__login_inflight__) {
		console.log('⏳ [loginAsync] 复用进行中的登录请求');
		return __login_inflight__;
	}

	__login_inflight__ = (async () => {
		try {
			console.log('📡 [loginAsync] 发起平台登录请求...');
			const result = await comfortable.loginAsync(app_id, env, loginParams);
			if (result && result.accessToken) {
				// 拒绝写入假登录
				if (
					String(result.accessToken).indexOf('default_token_') === 0 ||
					String(result.userId || '').indexOf('default_userId_') === 0
				) {
					throw new Error('平台未正确识别为微信，登录返回了默认兼容数据');
				}
				saveCacheForGuest(result);
			}
			return result;
		} catch (error) {
			console.error('❌ [loginAsync] 平台登录失败:', error);
			throw error;
		} finally {
			__login_inflight__ = null;
		}
	})();

	return __login_inflight__;
}

export default loginAsync
