// 微信小程序

/**
 * 微信小程序广告特殊要求说明：
 * 1. 微信平台要求在创建广告后立即设置onError函数
 * 2. 必须处理两种主要错误情况：
 *    - 调用正常，但没有合适的广告返回给用户 (errCode: 1004)
 *    - 错误的调用导致的异常返回 (其他errCode)
 * 3. 当errCode为1004时，建议不设置激励视频入口
 * 4. 详细的错误码说明请参考微信小程序开发者文档
 *
 * 微信平台广告显示特殊处理：
 * 5. 微信激励视频和插屏广告的show()调用容易失败
 * 6. 需要在show()失败时，先调用load()重新加载，然后再次尝试show()
 * 7. 这是微信平台的已知问题，需要特殊的重试机制
 */

/*
  插屏广告加载器
*/
class InterstitialAdLoader {
  constructor(params) {
    /**
     * @description: 初始化一个插屏广告，开发者需要将参数置换为自己小程序的广告id
     * 根据微信官方文档：https://developers.weixin.qq.com/miniprogram/dev/framework/open-ability/ad/interstitialAd-ad.html
     */
    this.params = params; // 保存原始参数用于错误日志
    this.isShowing = false; // 广告显示状态

    // 提取 autoOffTime（秒），不传给平台 API
    this.autoOffTime = (params.autoOffTime && Number.isFinite(+params.autoOffTime) && +params.autoOffTime > 0)
      ? +params.autoOffTime
      : 0;
    delete params.autoOffTime;

    // 记录注册的 onClose 回调，用于 autoOffTime 触发
    this._closeCallbacks = [];
    this._autoCloseTimer = null;

    params.adUnitId = params.adUnitId.toString();
    console.log("🎯 [InterstitialAdLoader] 参数:", params);

    this.ad = wx.createInterstitialAd(params);

    // 检查广告对象是否创建成功
    if (!this.ad) {
      console.error("❌ [InterstitialAdLoader] 广告对象创建失败: 返回值为空");
      throw new Error('wx.createInterstitialAd 返回 null 或 undefined');
    }

    console.log("✅ [InterstitialAdLoader] 广告对象创建成功");
    console.log("🔍 [InterstitialAdLoader] 广告对象类型:", typeof this.ad);

    // 微信平台要求立即设置错误处理函数，避免"您没有设置onError函数"警告
    try {
      if (this.ad && typeof this.ad.onError === 'function') {
        this.ad.onError((err) => {
          console.error("❌ [InterstitialAdLoader] 广告错误:", err);
        });
      } else {
        console.warn("⚠️ [InterstitialAdLoader] 广告对象缺少 onError 方法");
      }
    } catch (error) {
      console.warn("⚠️ [InterstitialAdLoader] 构造函数中设置onError失败:", error);
    }
  }

  /**
   * @description
   * 确保广告实例已初始化完成
   * 与其他广告加载器保持一致的接口
   */
  async ensureInitialized() {
    // 插屏广告在构造函数中已经完成初始化
    // 这里直接返回成功，保持接口一致性
    return Promise.resolve();
  }

  async load() {
    if (!this.ad) {
      throw new Error('插屏广告对象未初始化');
    }

    try {
      return await this.ad.load();
    } catch (error) {
      // 微信插屏广告对象可能已销毁（单例问题）
      if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
        console.log('⚠️ [InterstitialAdLoader.load] 广告对象已销毁，忽略加载');
        // 广告已销毁，静默处理，返回成功避免阻塞流程
        return Promise.resolve();
      }
      // 其他错误继续抛出
      throw error;
    }
  }

  async show() {
    if (!this.ad) {
      throw new Error('插屏广告对象未初始化');
    }

    // 微信插屏广告特殊处理：必须先确保加载完成再显示
    try {
      // 第一步：确保广告已加载 - 使用包装方法
      await this.load();

      // 第二步：显示广告
      const result = await this.ad.show();

      // 微信: show成功后启动 autoOffTime 定时器
      if (this.autoOffTime > 0) {
        this._clearAutoCloseTimer();
        console.log(`⏰ [WXInterstitialAdLoader] 启动自动关闭定时器，${this.autoOffTime}秒后触发`);
        this._autoCloseTimer = setTimeout(async () => {
          this._autoCloseTimer = null;
          console.log(`⏰ [WXInterstitialAdLoader] autoOffTime 到期，触发自动关闭`);
          const callbacks = [...this._closeCallbacks];
          await this.destroy();
          // 与平台 onClose 对齐，传入对象避免上游取 isEnded 报错
          callbacks.forEach(cb => {
            try { cb({ isEnded: true, from: "autoOffTime" }); } catch (e) { }
          });
        }, this.autoOffTime * 1000);
      }

      return result;

    } catch (error) {
      // 检查是否是广告对象已销毁错误
      if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
        console.error(`❌ [InterstitialAdLoader] 广告对象已销毁，无法显示`);
        throw new Error('插屏广告对象已销毁，请重新创建广告实例');
      }
      // 其他错误直接抛出
      throw error;
    }
  }

  /** 清除自动关闭定时器 */
  _clearAutoCloseTimer() {
    if (this._autoCloseTimer) {
      clearTimeout(this._autoCloseTimer);
      this._autoCloseTimer = null;
    }
  }

  async destroy() {
    this._clearAutoCloseTimer();
    this._closeCallbacks = [];
    if (this.ad) {
      try {
        if (typeof this.ad.destroy === 'function') {
          await this.ad.destroy();
        }
      } catch (e) {
        console.warn('⚠️ [WXInterstitialAdLoader.destroy] 销毁插屏广告实例出错:', e);
      }
      this.ad = null;
    }
  }

  onLoad(callback) {
    if (!this.ad) {
      console.error("❌ [InterstitialAdLoader.onLoad] 广告对象为空，无法绑定回调");
      return;
    }
    if (
      callback &&
      typeof callback == "function" &&
      typeof this.ad.onLoad == "function"
    ) {
      try {
        this.ad.onLoad(callback);
        console.log("✅ [InterstitialAdLoader] onLoad 回调绑定成功");
      } catch (error) {
        // 检查是否是广告对象已销毁错误
        if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
          console.log('⚠️ [InterstitialAdLoader.onLoad] 广告对象已销毁，跳过绑定');
          return;
        }
        console.error("❌ [InterstitialAdLoader] onLoad 回调绑定失败:", error);
        // 不抛出异常，让构造函数继续执行
        console.warn("⚠️ [InterstitialAdLoader] 继续执行，不中断构造函数");
      }
    } else {
      console.warn("⚠️ [InterstitialAdLoader] onLoad 回调绑定失败: 参数无效或方法不存在");
      console.warn("⚠️ [InterstitialAdLoader] callback:", callback);
      console.warn("⚠️ [InterstitialAdLoader] this.ad.onLoad:", this.ad.onLoad);
    }
  }
  onError(callback) {
    if (!this.ad) {
      console.error("❌ [InterstitialAdLoader.onError] 广告对象为空，无法绑定回调");
      return;
    }
    if (
      callback &&
      typeof callback == "function" &&
      typeof this.ad.onError == "function"
    ) {
      try {
        // 存储用户的错误回调，用于offError时移除
        this.userErrorCallback = callback;
        this.ad.onError(callback);
        console.log("✅ [InterstitialAdLoader] onError 回调绑定成功");
      } catch (error) {
        // 检查是否是广告对象已销毁错误
        if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
          console.log('⚠️ [InterstitialAdLoader.onError] 广告对象已销毁，跳过绑定');
          return;
        }
        console.error("❌ [InterstitialAdLoader] onError 回调绑定失败:", error);
        console.warn("⚠️ [InterstitialAdLoader] 继续执行，不中断构造函数");
      }
    }
  }

  onClose(callback) {
    if (callback && typeof callback == "function") {
      // 收集 onClose 回调供 autoOffTime 使用
      if (this._closeCallbacks && !this._closeCallbacks.includes(callback)) {
        this._closeCallbacks.push(callback);
      }
    }
    if (!this.ad) {
      console.error("❌ [InterstitialAdLoader.onClose] 广告对象为空，无法绑定回调");
      return;
    }
    if (
      callback &&
      typeof callback == "function" &&
      typeof this.ad.onClose == "function"
    ) {
      try {
        this.ad.onClose(callback);
        console.log("✅ [InterstitialAdLoader] onClose 回调绑定成功");
      } catch (error) {
        // 检查是否是广告对象已销毁错误
        if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
          console.log('⚠️ [InterstitialAdLoader.onClose] 广告对象已销毁，跳过绑定');
          return;
        }
        console.error("❌ [InterstitialAdLoader] onClose 回调绑定失败:", error);
        console.warn("⚠️ [InterstitialAdLoader] 继续执行，不中断构造函数");
      }
    }
  }

  offLoad(callback) {
    if (!this.ad) {
      return;
    }
    if (
      callback &&
      typeof callback == "function" &&
      typeof this.ad.offLoad == "function"
    ) {
      try {
        this.ad.offLoad(callback);
      } catch (error) {
        // 广告对象已销毁，忽略解绑错误
        if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
          console.log('⚠️ [InterstitialAdLoader.offLoad] 广告对象已销毁，跳过解绑');
        } else {
          console.warn('⚠️ [InterstitialAdLoader.offLoad] 解绑失败:', error);
        }
      }
    }
  }
  offError(callback) {
    if (!this.ad) {
      return;
    }
    if (
      callback &&
      typeof callback == "function" &&
      typeof this.ad.offError == "function"
    ) {
      try {
        this.ad.offError(callback);
      } catch (error) {
        // 广告对象已销毁，忽略解绑错误
        if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
          console.log('⚠️ [InterstitialAdLoader.offError] 广告对象已销毁，跳过解绑');
        } else {
          console.warn('⚠️ [InterstitialAdLoader.offError] 解绑失败:', error);
        }
      }
    }
    // 如果是移除用户设置的错误回调，清除引用
    if (callback === this.userErrorCallback) {
      this.userErrorCallback = null;
    }
  }
  offClose(callback) {
    // 从自动关闭回调列表中移除
    if (callback && this._closeCallbacks) {
      this._closeCallbacks = this._closeCallbacks.filter(cb => cb !== callback);
    }
    // 如果列表已空，取消定时器
    if (this._closeCallbacks && this._closeCallbacks.length === 0) {
      this._clearAutoCloseTimer();
    }
    if (!this.ad) {
      return;
    }
    if (
      callback &&
      typeof callback == "function" &&
      typeof this.ad.offClose == "function"
    ) {
      try {
        this.ad.offClose(callback);
      } catch (error) {
        // 广告对象已销毁，忽略解绑错误
        if (error && error.errMsg && error.errMsg.includes('has been destroyed')) {
          console.log('⚠️ [InterstitialAdLoader.offClose] 广告对象已销毁，跳过解绑');
        } else {
          console.warn('⚠️ [InterstitialAdLoader.offClose] 解绑失败:', error);
        }
      }
    }
  }
}

//根据key升序排列后取值作为key返回
function paramsConvertToKey(params) {
  return Object.values(sortByKey(params)).join("");
}

function sortByKey(obj) {
  const newKey = Object.keys(obj).sort();
  let newObj = {};
  for (let i = 0; i < newKey.length; i++) {
    newObj[newKey[i]] = obj[newKey[i]];
  }
  return newObj;
}

/*
   激励视频广告加载器 - 简化版本
   原则：
   1. 小程序每次展示用新对象：createRewardedVideoAd({ multiton: true })，关闭后 destroy
   2. 不传 multiton 时微信按 adUnitId 返回页面单例，destroy 后再 create 会拿到已销毁对象
   3. 检测到已销毁 / showing 卡住时强制 destroy + recreate
*/
class RewardedVideoAdLoader {
  constructor(params) {
    params.adUnitId = params.adUnitId.toString();
    this.params = params;

    // 小程序必须带上 multiton，否则 destroy 后拿不到新实例
    const wxParams = { adUnitId: params.adUnitId };
    if (params.multiton) {
      wxParams.multiton = true;
    }
    this.wxParams = wxParams;  // 保存参数
    this._useDH = false;
    this._dhCompleted = false;
    this._onLoadCbs = [];
    this._onErrorCbs = [];
    this._onCloseCbs = [];
    this.createAd();
  }

  _isPlatformAdDead() {
    return !this.ad || this.ad._destroyed === true;
  }

  _tryCreateDHAd() {
    try {
      // 同步探测：仅当 Deploy 已完成 DH 初始化时走官方 SDK
      // 小程序打包已 Ignore dhminisdk，require 为空模块
      // eslint-disable-next-line global-require
      const dhMod = require("../../dhminisdk/DHMiniSDKManager.js");
      const dhMiniSDKManager = dhMod && dhMod.default;
      if (!dhMiniSDKManager || !dhMiniSDKManager.isReady()) {
        return false;
      }
      const self = this;
      this.ad = dhMiniSDKManager.createRewardedVideoAd({
        adUnitId: this.wxParams.adUnitId,
        adPlatform: "weixin",
        adPosition: (this.params && this.params.adPosition) || "",
        onLoad: function (response) {
          self._onLoadCbs.forEach((cb) => {
            try {
              cb(response);
            } catch (e) {}
          });
        },
        onClose: function (response) {
          const isEnded = !!self._dhCompleted;
          self._dhCompleted = false;
          const payload = {
            isEnded,
            code: response && response.code,
            data: response && response.data,
          };
          self._onCloseCbs.forEach((cb) => {
            try {
              cb(payload);
            } catch (e) {}
          });
        },
        onComplete: function () {
          // 用户看完激励：标记后由 onClose 以 isEnded=true 透出给现有 AdLoader
          self._dhCompleted = true;
        },
        onError: function (error) {
          self._onErrorCbs.forEach((cb) => {
            try {
              cb(error);
            } catch (e) {}
          });
        },
      });
      if (!this.ad) {
        return false;
      }
      this._useDH = true;
      this.needsRecreate = false;
      console.log("✅ [激励视频] 使用 DHMiniSDK.createRewardedVideoAd");
      return true;
    } catch (error) {
      return false;
    }
  }

  createAd() {
    if (this._tryCreateDHAd()) {
      return;
    }

    this._useDH = false;
    this.ad = wx.createRewardedVideoAd(this.wxParams);

    if (!this.ad) {
      throw new Error('创建激励视频广告失败');
    }

    // 检测单例状态
    let needsCleanup = false;

    // 情况1：单例已销毁（可能是上次destroy导致的）
    if (this.ad._destroyed === true) {
      console.log('💥 [单例已销毁，需要重建]');
      needsCleanup = true;
    }

    // 情况2：检测单例是否认为有广告正在显示（页面切换场景）
    // 微信单例可能卡在"is showing"状态，特别是页面切换时
    // 通过尝试offLoad来检测（如果卡住会抛出错误）
    try {
      // 尝试解绑一个不存在的回调，如果单例正常会静默成功
      // 如果单例卡住会抛出 "while video-ad is showed" 错误
      this.ad.offLoad(() => { });
    } catch (error) {
      if (error && error.errMsg && error.errMsg.includes("while video-ad is showed")) {
        console.log('💥 [单例卡在showing状态，需要清理]');
        needsCleanup = true;
      }
    }

    this.needsRecreate = needsCleanup;

    // 平台侧只绑一组固定分发器；业务回调走数组，避免单例复用叠 onError/onClose
    this._bindPlatformDispatchers();
  }

  _ensureDispatchers() {
    if (!this._dispatchLoad) {
      this._dispatchLoad = (res) => {
        this._onLoadCbs.forEach((cb) => {
          try {
            cb(res);
          } catch (e) {}
        });
      };
    }
    if (!this._dispatchError) {
      this._dispatchError = (err) => {
        console.error("❌ [激励视频广告错误]", err);
        this._onErrorCbs.forEach((cb) => {
          try {
            cb(err);
          } catch (e) {}
        });
      };
    }
    if (!this._dispatchClose) {
      this._dispatchClose = (res) => {
        this._onCloseCbs.forEach((cb) => {
          try {
            cb(res);
          } catch (e) {}
        });
      };
    }
  }

  /** 先解绑再绑固定分发器，保证 wx 激励单例上每种事件只有 1 个监听 */
  _bindPlatformDispatchers() {
    if (!this.ad || this._useDH) {
      return;
    }
    this._ensureDispatchers();
    try {
      if (typeof this.ad.offLoad === "function") this.ad.offLoad(this._dispatchLoad);
    } catch (e) {}
    try {
      if (typeof this.ad.offError === "function") this.ad.offError(this._dispatchError);
    } catch (e) {}
    try {
      if (typeof this.ad.offClose === "function") this.ad.offClose(this._dispatchClose);
    } catch (e) {}
    try {
      if (typeof this.ad.onLoad === "function") this.ad.onLoad(this._dispatchLoad);
    } catch (e) {}
    try {
      if (typeof this.ad.onError === "function") this.ad.onError(this._dispatchError);
    } catch (e) {}
    try {
      if (typeof this.ad.onClose === "function") this.ad.onClose(this._dispatchClose);
    } catch (e) {}
  }

  /** 清空业务回调（复用单例前调用）；平台分发器保持不动 */
  clearListeners() {
    this._onLoadCbs = [];
    this._onErrorCbs = [];
    this._onCloseCbs = [];
  }

  async ensureInitialized() {
    // 如果检测到需要重建
    if (this.needsRecreate) {
      console.log('🔧 [检测到单例异常，尝试清理并重建]');
      try {
        await this.destroy();
        console.log('✅ [单例已清理]');
      } catch (error) {
        console.log('⚠️ [清理失败，忽略]', error && error.errMsg);
      }

      // 重新创建；若仍异常再尝试一次
      for (let i = 0; i < 2; i++) {
        this.createAd();
        if (!this.needsRecreate && this.ad) {
          break;
        }
        try {
          await this.destroy();
          await new Promise((resolve) => setTimeout(resolve, 100));
        } catch (e) {}
      }

      // 重建流程结束：对象不存在或仍是已销毁实例，都视为失败
      this.needsRecreate = this._isPlatformAdDead();
    }
    return Promise.resolve();
  }

  isSame(params) {
    return false; // 永远返回 false，强制重建
  }

  async load() {
    if (!this.ad) {
      throw new Error('广告对象未初始化');
    }

    if (this._useDH) {
      return new Promise((resolve) => {
        try {
          this.ad.load(function (loadRes) {
            resolve(loadRes);
          });
        } catch (error) {
          console.log('⚠️ [DH load失败，忽略]', error && error.message);
          resolve({ code: -1, message: (error && error.message) || "load failed" });
        }
      });
    }

    // 微信平台：简单调用，忽略所有错误
    // 单例异常已经在 ensureInitialized() 中处理
    try {
      await this.ad.load();
    } catch (error) {
      console.log('⚠️ [load失败，忽略]', error.errMsg);
    }
  }

  async show() {
    if (!this.ad) {
      throw new Error('广告对象未初始化');
    }

    if (this._useDH) {
      return new Promise((resolve, reject) => {
        try {
          this.ad.show({ adPosition: "" }, function (showRes) {
            if (showRes && showRes.code == 0) {
              resolve(showRes);
              return;
            }
            // 展示失败：尝试 load 后再 show 一次
            try {
              this.ad.load((loadRes) => {
                if (loadRes && loadRes.code == 0) {
                  this.ad.show({ adPosition: "" }, (retryRes) => {
                    if (retryRes && retryRes.code == 0) {
                      resolve(retryRes);
                    } else {
                      reject(
                        new Error(
                          (retryRes && retryRes.message) || "DH 激励广告展示失败",
                        ),
                      );
                    }
                  });
                } else {
                  reject(
                    new Error(
                      (showRes && showRes.message) ||
                        (loadRes && loadRes.message) ||
                        "DH 激励广告展示失败",
                    ),
                  );
                }
              });
            } catch (e) {
              reject(e);
            }
          }.bind(this));
        } catch (error) {
          reject(error);
        }
      });
    }

    // 微信平台：直接show，失败就重试一次
    try {
      return await this.ad.show();
    } catch (error) {
      console.log('⚠️ [首次show失败，重试]', error.errMsg);

      const errMsg = (error && error.errMsg) || "";
      // 仍在展示中：禁止 load 重试（微信会继续报 can't invoke load while showed）
      if (
        errMsg.includes("while video-ad is showed") ||
        errMsg.includes("while other video-ad is showed")
      ) {
        throw error;
      }
      // 单例卡住，或拿到已销毁实例：强制销毁后新建再展示
      if (errMsg.includes("has been destroyed")) {
        console.log('💥 [激励对象不可用，销毁后新建]', errMsg);
        try {
          await this.destroy();
          await new Promise(resolve => setTimeout(resolve, 300));
          this.createAd();
          if (this._isPlatformAdDead()) {
            throw new Error('广告对象重建失败');
          }
          await this.load();
          return await this.ad.show();
        } catch (e) {
          throw e && e.errMsg ? e : new Error('广告状态异常，请稍后重试');
        }
      }

      // 其他错误：load + show
      try {
        await this.ad.load();
        return await this.ad.show();
      } catch (retryError) {
        throw retryError;
      }
    }
  }

  async destroy() {
    if (!this.ad) {
      return;
    }
    try {
      if (typeof this.ad.destroy === 'function') {
        await this.ad.destroy();
      }
    } catch (error) {
      // 忽略已销毁等错误
      if (!(error && error.errMsg && error.errMsg.includes('has been destroyed'))) {
        console.warn('⚠️ [RewardedVideoAdLoader.destroy] 销毁失败:', error);
      }
    } finally {
      this.ad = null;
    }
  }

  _pushUnique(list, callback) {
    if (callback && typeof callback === "function" && list.indexOf(callback) === -1) {
      list.push(callback);
    }
  }

  _removeCb(list, callback) {
    const i = list.indexOf(callback);
    if (i > -1) list.splice(i, 1);
  }

  onLoad(callback) {
    this._pushUnique(this._onLoadCbs, callback);
  }

  onError(callback) {
    this._pushUnique(this._onErrorCbs, callback);
  }

  onClose(callback) {
    this._pushUnique(this._onCloseCbs, callback);
  }

  offLoad(callback) {
    this._removeCb(this._onLoadCbs, callback);
  }

  offError(callback) {
    this._removeCb(this._onErrorCbs, callback);
  }

  offClose(callback) {
    this._removeCb(this._onCloseCbs, callback);
  }
}


const getConfigData = () => {
  return {
    platform: "WX",
    payPlatform: 'wechat'
  };
};

/*
  原生模板广告加载器
  微信小程序原生模板广告说明：
  1. 微信小程序中原生模板广告通过 <ad-custom> 组件实现，不是通过 wx.createCustomAd API
  2. wx.createCustomAd API 主要用于小游戏，且需要基础库版本 2.11.1+
  3. 这里提供兼容性实现，模拟广告加载器的行为
  4. 实际的广告显示需要在页面中使用 <ad-custom> 组件或 fbi-native-ad 组件
*/
class NativeAdLoader {
  constructor(params) {
    /**
     * @description: 初始化一个原生模板广告管理器
     * 微信小程序中原生模板广告需要通过页面的 <ad-custom> 组件实现
     * 这里提供兼容性接口，保持与其他平台一致的调用方式
     */

    this.params = params;
    this.isLoaded = false;
    this.isVisible = false;
    this.isDestroyed = false;

    // 存储用户设置的回调函数
    this.callbacks = {
      onLoad: [],
      onError: [],
      onClose: [],
      onHide: [],
      onResize: [],
    };

    // 存储关联的组件实例
    this.componentInstance = null;
  }

  /**
   * @description
   * 比较配置文件，是否相同
   * @param {Object} params
   */
  isSame(params) {
    let myKey = paramsConvertToKey(this.params);
    let key = paramsConvertToKey(params);
    return myKey == key;
  }

  /**
   * @description
   * 确保广告实例已初始化完成
   * 与其他广告加载器保持一致的接口
   */
  async ensureInitialized() {
    // 微信原生模板广告在构造函数中已经完成初始化
    // 这里直接返回成功，保持接口一致性
    return Promise.resolve();
  }

  /**
   * @description
   * 检查广告是否正在显示
   * @returns {Boolean} 广告是否正在显示
   */
  isShow() {
    return this.isVisible && !this.isDestroyed;
  }

  async load() {
    // 模拟加载成功
    setTimeout(() => {
      this.isLoaded = true;
      this.triggerCallback("onLoad");
    }, 100);

    return Promise.resolve();
  }

  async show() {
    this.isVisible = true;

    // 如果有关联的组件实例，调用组件的显示方法
    if (
      this.componentInstance &&
      typeof this.componentInstance.showAd === "function"
    ) {
      this.componentInstance.showAd();
    }

    // 模拟显示成功
    return Promise.resolve();
  }

  async hide() {
    this.isVisible = false;

    // 如果有关联的组件实例，调用组件的隐藏方法
    if (
      this.componentInstance &&
      typeof this.componentInstance.hideAd === "function"
    ) {
      this.componentInstance.hideAd();
    }

    // 模拟隐藏成功
    return Promise.resolve();
  }

  async destroy() {
    this.isDestroyed = true;
    this.isVisible = false;
    this.isLoaded = false;

    // 清除所有回调
    this.callbacks = {
      onLoad: [],
      onError: [],
      onClose: [],
      onHide: [],
      onResize: [],
    };

    return Promise.resolve();
  }

  // 触发回调函数
  triggerCallback(eventName, ...args) {
    if (this.callbacks[eventName]) {
      this.callbacks[eventName].forEach((callback) => {
        try {
          callback(...args);
        } catch (error) {
          // 忽略回调执行错误
        }
      });
    }
  }

  /**
   * 关联组件实例
   * @param {Object} componentInstance 组件实例
   */
  bindComponent(componentInstance) {
    this.componentInstance = componentInstance;
  }

  /**
   * 解除组件关联
   */
  unbindComponent() {
    this.componentInstance = null;
  }

  /**
   * 通过代码位显示广告（由ad调用）
   * @param {String} adCode 广告代码位
   * @param {Object} callbacks 回调函数
   */
  static showByCode(adCode, callbacks = {}) {
    try {
      const app = getApp();
      if (!app.ad || !app.ad.nativeAdComponents) {
        const errorMsg = `原生模板广告组件未初始化！
				
请确保：
1. 在页面中引入并使用 native-ad 组件
2. 在页面模板中添加：<native-ad code="${adCode}"></native-ad>
3. 或者添加默认组件：<native-ad code="default_native"></native-ad>

示例代码：
<template>
  <view>
    <native-ad code="${adCode}"></native-ad>
  </view>
</template>

<script>
import NativeAd from '@/sdk/fbiad/components/native-ad/native-ad.vue'
export default {
  components: { NativeAd }
}
</script>`;

        if (callbacks.onError) {
          callbacks.onError({
            errMsg: "未找到对应的原生模板广告组件",
            detail: "请在页面中添加 <native-ad> 组件",
            code: adCode,
            solution: `请在页面模板中添加：<native-ad code="${adCode}"></native-ad>`,
          });
        }
        return;
      }

      // 查找对应的组件实例
      let component = app.ad.nativeAdComponents.get(adCode);

      // 如果没找到对应的组件，尝试使用默认组件
      if (!component && adCode !== "default_native") {
        component = app.ad.nativeAdComponents.get("default_native");
      }

      if (!component) {
        const errorMsg = `原生模板广告组件 "${adCode}" 未找到！

请确保：
1. 在当前页面中添加对应的组件：<native-ad code="${adCode}"></native-ad>
2. 或者添加默认组件：<native-ad code="default_native"></native-ad>
3. 确保组件已正确引入和注册

当前已注册的组件：${app.ad.nativeAdComponents
            ? Array.from(app.ad.nativeAdComponents.keys()).join(", ")
            : "无"
          }

示例代码：
<template>
  <view>
    <native-ad code="${adCode}"></native-ad>
  </view>
</template>

<script>
import NativeAd from '@/sdk/fbiad/components/native-ad/native-ad.vue'
export default {
  components: { NativeAd }
}
</script>`;

        if (callbacks.onError) {
          callbacks.onError({
            errMsg: `未找到 ${adCode} 组件实例`,
            detail: "请在页面中添加对应的 <native-ad> 组件",
            code: adCode,
            registeredComponents: app.ad.nativeAdComponents
              ? Array.from(app.ad.nativeAdComponents.keys())
              : [],
            solution: `请在页面模板中添加：<native-ad code="${adCode}"></native-ad>`,
          });
        }
        return;
      }

      // 绑定回调函数到组件实例
      if (callbacks.onLoad) {
        // 移除之前的监听
        if (component.loadCallbacks) {
          component.loadCallbacks = component.loadCallbacks.filter(
            (cb) => cb !== callbacks.onLoad
          );
        } else {
          component.loadCallbacks = [];
        }
        component.loadCallbacks.push(callbacks.onLoad);

        // 重新绑定事件
        component.$off("load");
        component.$on("load", (e) => {
          component.loadCallbacks.forEach((cb) => {
            try {
              cb(e);
            } catch (error) {
              // 忽略回调错误
            }
          });
        });
      }
      if (callbacks.onError) {
        if (component.errorCallbacks) {
          component.errorCallbacks = component.errorCallbacks.filter(
            (cb) => cb !== callbacks.onError
          );
        } else {
          component.errorCallbacks = [];
        }
        component.errorCallbacks.push(callbacks.onError);

        component.$off("error");
        component.$on("error", (e) => {
          component.errorCallbacks.forEach((cb) => {
            try {
              cb(e);
            } catch (error) {
              // 忽略回调错误
            }
          });
        });
      }
      if (callbacks.onClose) {
        if (component.closeCallbacks) {
          component.closeCallbacks = component.closeCallbacks.filter(
            (cb) => cb !== callbacks.onClose
          );
        } else {
          component.closeCallbacks = [];
        }
        component.closeCallbacks.push(callbacks.onClose);

        component.$off("close");
        component.$on("close", (e) => {
          component.closeCallbacks.forEach((cb) => {
            try {
              cb(e);
            } catch (error) {
              // 忽略回调错误
            }
          });
        });
      }

      // 初始化并显示广告
      component.initAd(adCode);
    } catch (error) {
      if (callbacks.onError) {
        callbacks.onError({
          errMsg: "原生模板广告显示失败",
          error,
        });
      }
    }
  }

  /**
   * 通过代码位隐藏广告（由ad调用）
   * @param {String} adCode 广告代码位
   */
  static hideByCode(adCode) {
    try {
      const app = getApp();
      if (!app.ad || !app.ad.nativeAdComponents) {
        const errorMsg = `原生模板广告组件未初始化！

请确保：
1. 在页面中引入并使用 native-ad 组件
2. 在页面模板中添加：<native-ad code="${adCode}"></native-ad>
3. 或者添加默认组件：<native-ad code="default_native"></native-ad>`;

        return;
      }

      // 查找对应的组件实例
      let component = app.ad.nativeAdComponents.get(adCode);

      // 如果没找到对应的组件，尝试使用默认组件
      if (!component && adCode !== "default_native") {
        component = app.ad.nativeAdComponents.get("default_native");
      }

      if (!component) {
        const errorMsg = `原生模板广告组件 "${adCode}" 未找到！

请确保：
1. 在当前页面中添加对应的组件：<native-ad code="${adCode}"></native-ad>
2. 或者添加默认组件：<native-ad code="default_native"></native-ad>

当前已注册的组件：${app.ad.nativeAdComponents
            ? Array.from(app.ad.nativeAdComponents.keys()).join(", ")
            : "无"
          }`;

        return;
      }

      // 隐藏广告
      component.hideAdMethod();
    } catch (error) {
      // 忽略隐藏失败错误
    }
  }

  onLoad(callback) {
    if (callback && typeof callback == "function") {
      this.callbacks.onLoad.push(callback);
    }
  }
  onError(callback) {
    if (callback && typeof callback == "function") {
      this.callbacks.onError.push(callback);
    }
  }

  onClose(callback) {
    if (callback && typeof callback == "function") {
      this.callbacks.onClose.push(callback);
    }
  }

  onHide(callback) {
    if (callback && typeof callback == "function") {
      this.callbacks.onHide.push(callback);
    }
  }

  onResize(callback) {
    if (callback && typeof callback == "function") {
      this.callbacks.onResize.push(callback);
    }
  }

  offLoad(callback) {
    if (callback && typeof callback == "function") {
      const index = this.callbacks.onLoad.indexOf(callback);
      if (index > -1) {
        this.callbacks.onLoad.splice(index, 1);
      }
    }
  }
  offError(callback) {
    if (callback && typeof callback == "function") {
      const index = this.callbacks.onError.indexOf(callback);
      if (index > -1) {
        this.callbacks.onError.splice(index, 1);
      }
    }
  }
  offClose(callback) {
    if (callback && typeof callback == "function") {
      const index = this.callbacks.onClose.indexOf(callback);
      if (index > -1) {
        this.callbacks.onClose.splice(index, 1);
      }
    }
  }

  offHide(callback) {
    if (callback && typeof callback == "function") {
      const index = this.callbacks.onHide.indexOf(callback);
      if (index > -1) {
        this.callbacks.onHide.splice(index, 1);
      }
    }
  }

  offResize(callback) {
    if (callback && typeof callback == "function") {
      const index = this.callbacks.onResize.indexOf(callback);
      if (index > -1) {
        this.callbacks.onResize.splice(index, 1);
      }
    }
  }
}

/**
 * 小游戏原生模板广告 - wx.createCustomAd
 * type=6, code=default_game_native
 * type=7（格子/矩阵模板）与本类共用同一官方 API，见 GridAdLoader
 * 基础库 >= 2.11.1
 */
function toNumber(value, fallback) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function normalizeCustomAdStyle(style = {}) {
  return {
    left: toNumber(style.left, 0),
    top: toNumber(style.top, 0),
    width: toNumber(style.width, 300),
    // fixed 仅小程序生效；小游戏传了也会被忽略
    fixed: style.fixed !== undefined ? !!style.fixed : true,
  };
}

function normalizeGridAdStyle(style = {}) {
  // 与 CustomAd.style 对齐：left / top / width / fixed（不再使用 height）
  return {
    left: toNumber(style.left, 0),
    top: toNumber(style.top, 0),
    width: toNumber(style.width, 300),
    fixed: style.fixed !== undefined ? !!style.fixed : true,
  };
}

class CustomAdLoader {
  constructor(params = {}) {
    if (!params.adUnitId) {
      throw new Error("CustomAdLoader: adUnitId 必填");
    }
    if (typeof wx === "undefined" || typeof wx.createCustomAd !== "function") {
      throw new Error("当前环境不支持 wx.createCustomAd（需基础库 >= 2.11.1）");
    }

    this.params = params;
    this.adUnitId = String(params.adUnitId);
    this.adIntervals = Math.max(toNumber(params.adIntervals, 30), 30);
    this.style = normalizeCustomAdStyle(params.style);
    this.isDestroyed = false;
    this._visible = false;

    this.callbacks = {
      onLoad: [],
      onError: [],
      onClose: [],
      onHide: [],
      onResize: [],
    };

    this.ad = wx.createCustomAd({
      adUnitId: this.adUnitId,
      adIntervals: this.adIntervals,
      style: this.style,
    });

    this._bindPlatformEvents();
  }

  _bindPlatformEvents() {
    if (!this.ad) return;

    this._onLoad = (...args) => {
      this.callbacks.onLoad.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };
    this._onError = (...args) => {
      let payload = args[0];
      if (Array.isArray(payload)) {
        payload = payload[0] || payload;
      }
      this.callbacks.onError.forEach((cb) => {
        try { cb(payload); } catch (e) {}
      });
    };
    this._onClose = (...args) => {
      this._visible = false;
      // 用户关闭后微信会销毁 CustomAd，标记失效，禁止复用
      this._invalidateAfterClose();
      this.callbacks.onClose.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };
    this._onHide = (...args) => {
      this._visible = false;
      this._invalidateAfterClose();
      this.callbacks.onHide.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };
    this._onResize = (...args) => {
      this.callbacks.onResize.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };

    if (typeof this.ad.onLoad === "function") this.ad.onLoad(this._onLoad);
    if (typeof this.ad.onError === "function") this.ad.onError(this._onError);
    if (typeof this.ad.onClose === "function") this.ad.onClose(this._onClose);
    if (typeof this.ad.onHide === "function") this.ad.onHide(this._onHide);
    if (typeof this.ad.onResize === "function") this.ad.onResize(this._onResize);
  }

  isSame(params = {}) {
    return String(params.adUnitId || "") === this.adUnitId;
  }

  /** 平台关闭后实例不可再用 */
  isUsable() {
    return !this.isDestroyed && !!this.ad;
  }

  _invalidateAfterClose() {
    if (this.isDestroyed) return;
    this.isDestroyed = true;
    // 平台侧已销毁，只清引用，避免再调 destroy 报错
    this.ad = null;
  }

  async ensureInitialized() {
    return Promise.resolve();
  }

  isShow() {
    if (this.isDestroyed || !this.ad) return false;
    if (typeof this.ad.isShow === "function") {
      try {
        return !!this.ad.isShow();
      } catch (e) {
        return this._visible;
      }
    }
    return this._visible;
  }

  async load() {
    // CustomAd 无独立 load，创建后即可 show
    return Promise.resolve();
  }

  async show() {
    if (this.isDestroyed || !this.ad) {
      throw new Error("CustomAd 已销毁，请重新创建");
    }
    await this.ad.show();
    this._visible = true;
  }

  async hide() {
    if (this.isDestroyed || !this.ad) {
      return;
    }
    if (typeof this.ad.hide === "function") {
      await this.ad.hide();
    }
    this._visible = false;
  }

  async destroy() {
    if (this.isDestroyed && !this.ad) return;
    this.isDestroyed = true;
    try {
      if (this.ad) {
        if (typeof this.ad.offLoad === "function" && this._onLoad) this.ad.offLoad(this._onLoad);
        if (typeof this.ad.offError === "function" && this._onError) this.ad.offError(this._onError);
        if (typeof this.ad.offClose === "function" && this._onClose) this.ad.offClose(this._onClose);
        if (typeof this.ad.offHide === "function" && this._onHide) this.ad.offHide(this._onHide);
        if (typeof this.ad.offResize === "function" && this._onResize) this.ad.offResize(this._onResize);
        if (typeof this.ad.destroy === "function") this.ad.destroy();
      }
    } catch (e) {
      // 平台可能已销毁，忽略
    }
    this.ad = null;
    this._visible = false;
  }

  onLoad(cb) { if (typeof cb === "function") this.callbacks.onLoad.push(cb); }
  onError(cb) { if (typeof cb === "function") this.callbacks.onError.push(cb); }
  onClose(cb) { if (typeof cb === "function") this.callbacks.onClose.push(cb); }
  onHide(cb) { if (typeof cb === "function") this.callbacks.onHide.push(cb); }
  onResize(cb) { if (typeof cb === "function") this.callbacks.onResize.push(cb); }

  offLoad(cb) {
    const i = this.callbacks.onLoad.indexOf(cb);
    if (i > -1) this.callbacks.onLoad.splice(i, 1);
  }
  offError(cb) {
    const i = this.callbacks.onError.indexOf(cb);
    if (i > -1) this.callbacks.onError.splice(i, 1);
  }
  offClose(cb) {
    const i = this.callbacks.onClose.indexOf(cb);
    if (i > -1) this.callbacks.onClose.splice(i, 1);
  }
  offHide(cb) {
    const i = this.callbacks.onHide.indexOf(cb);
    if (i > -1) this.callbacks.onHide.splice(i, 1);
  }
  offResize(cb) {
    const i = this.callbacks.onResize.indexOf(cb);
    if (i > -1) this.callbacks.onResize.splice(i, 1);
  }
}

/**
 * 小游戏格子广告（矩阵格子模板）- 与原生模板共用 wx.createCustomAd
 * type=7, code=default_grid
 * 基础库 >= 2.11.1（createGridAd 已停止维护，统一走 CustomAd）
 * 关闭/隐藏后实例不可复用，interval 重拉须重建
 */
class GridAdLoader {
  constructor(params = {}) {
    if (!params.adUnitId) {
      throw new Error("GridAdLoader: adUnitId 必填");
    }
    if (typeof wx === "undefined" || typeof wx.createCustomAd !== "function") {
      throw new Error("当前环境不支持 wx.createCustomAd（需基础库 >= 2.11.1）");
    }

    this.params = params;
    this.adUnitId = String(params.adUnitId);
    this.adIntervals = Math.max(toNumber(params.adIntervals, 30), 30);
    this.style = normalizeGridAdStyle(params.style);
    this.isDestroyed = false;
    this._visible = false;

    this.callbacks = {
      onLoad: [],
      onError: [],
      onClose: [],
      onHide: [],
      onResize: [],
    };

    // 与 type=6 共用官方 API；模板形态由广告位（adUnitId）决定
    this.ad = wx.createCustomAd({
      adUnitId: this.adUnitId,
      adIntervals: this.adIntervals,
      style: this.style,
    });

    this._bindPlatformEvents();
  }

  _bindPlatformEvents() {
    if (!this.ad) return;

    this._onLoad = (...args) => {
      this.callbacks.onLoad.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };
    this._onError = (...args) => {
      let payload = args[0];
      if (Array.isArray(payload)) {
        payload = payload[0] || payload;
      }
      this.callbacks.onError.forEach((cb) => {
        try { cb(payload); } catch (e) {}
      });
    };
    this._onClose = (...args) => {
      this._visible = false;
      this._invalidateAfterClose();
      this.callbacks.onClose.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };
    this._onHide = (...args) => {
      this._visible = false;
      this._invalidateAfterClose();
      this.callbacks.onHide.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };
    this._onResize = (...args) => {
      this.callbacks.onResize.forEach((cb) => {
        try { cb(...args); } catch (e) {}
      });
    };

    if (typeof this.ad.onLoad === "function") this.ad.onLoad(this._onLoad);
    if (typeof this.ad.onError === "function") this.ad.onError(this._onError);
    if (typeof this.ad.onClose === "function") this.ad.onClose(this._onClose);
    if (typeof this.ad.onHide === "function") this.ad.onHide(this._onHide);
    if (typeof this.ad.onResize === "function") this.ad.onResize(this._onResize);
  }

  isSame(params = {}) {
    return String(params.adUnitId || "") === this.adUnitId;
  }

  isUsable() {
    return !this.isDestroyed && !!this.ad;
  }

  _invalidateAfterClose() {
    if (this.isDestroyed) return;
    this.isDestroyed = true;
    this.ad = null;
  }

  async ensureInitialized() {
    return Promise.resolve();
  }

  isShow() {
    if (this.isDestroyed || !this.ad) return false;
    if (typeof this.ad.isShow === "function") {
      try {
        return !!this.ad.isShow();
      } catch (e) {
        return this._visible;
      }
    }
    return this._visible;
  }

  async load() {
    return Promise.resolve();
  }

  async show() {
    if (this.isDestroyed || !this.ad) {
      throw new Error("GridAd(CustomAd) 已销毁，请重新创建");
    }
    await this.ad.show();
    this._visible = true;
  }

  async hide() {
    if (this.isDestroyed || !this.ad) {
      return;
    }
    if (typeof this.ad.hide === "function") {
      await this.ad.hide();
    }
    this._visible = false;
  }

  async destroy() {
    if (this.isDestroyed && !this.ad) return;
    this.isDestroyed = true;
    try {
      if (this.ad) {
        if (typeof this.ad.offLoad === "function" && this._onLoad) this.ad.offLoad(this._onLoad);
        if (typeof this.ad.offError === "function" && this._onError) this.ad.offError(this._onError);
        if (typeof this.ad.offClose === "function" && this._onClose) this.ad.offClose(this._onClose);
        if (typeof this.ad.offHide === "function" && this._onHide) this.ad.offHide(this._onHide);
        if (typeof this.ad.offResize === "function" && this._onResize) this.ad.offResize(this._onResize);
        if (typeof this.ad.destroy === "function") this.ad.destroy();
      }
    } catch (e) {
      // 平台可能已销毁，忽略
    }
    this.ad = null;
    this._visible = false;
  }

  onLoad(cb) { if (typeof cb === "function") this.callbacks.onLoad.push(cb); }
  onError(cb) { if (typeof cb === "function") this.callbacks.onError.push(cb); }
  onClose(cb) { if (typeof cb === "function") this.callbacks.onClose.push(cb); }
  onHide(cb) { if (typeof cb === "function") this.callbacks.onHide.push(cb); }
  onResize(cb) { if (typeof cb === "function") this.callbacks.onResize.push(cb); }

  offLoad(cb) {
    const i = this.callbacks.onLoad.indexOf(cb);
    if (i > -1) this.callbacks.onLoad.splice(i, 1);
  }
  offError(cb) {
    const i = this.callbacks.onError.indexOf(cb);
    if (i > -1) this.callbacks.onError.splice(i, 1);
  }
  offClose(cb) {
    const i = this.callbacks.onClose.indexOf(cb);
    if (i > -1) this.callbacks.onClose.splice(i, 1);
  }
  offHide(cb) {
    const i = this.callbacks.onHide.indexOf(cb);
    if (i > -1) this.callbacks.onHide.splice(i, 1);
  }
  offResize(cb) {
    const i = this.callbacks.onResize.indexOf(cb);
    if (i > -1) this.callbacks.onResize.splice(i, 1);
  }
}

export default {
  InterstitialAdLoader,
  RewardedVideoAdLoader,
  NativeAdLoader,
  CustomAdLoader,
  GridAdLoader,
  getConfigData,
};
