import comfortable from "./fbiadComfortable/fbiadCFIndex.js";

let CustomAdLoaderBase = null;

const initCustomAdLoaderBase = async () => {
  CustomAdLoaderBase = await comfortable.CustomAdLoaderAsync();
  return CustomAdLoaderBase;
};

/**
 * 小游戏原生模板广告包装（wx.createCustomAd）
 */
class CustomAdLoader {
  constructor(params) {
    this.params = params;
    this.initialized = false;
    this.baseLoader = null;
    this.initPromise = this.initBase();
  }

  async initBase() {
    if (!CustomAdLoaderBase) {
      await initCustomAdLoaderBase();
    }
    if (!CustomAdLoaderBase) {
      throw new Error("CustomAdLoader 当前平台不可用");
    }
    this.baseLoader = new CustomAdLoaderBase(this.params);
    this.initialized = true;
    return this.baseLoader;
  }

  async ensureInitialized() {
    // 关闭后平台已销毁实例，必须重建，不可复用
    if (this.baseLoader && typeof this.isUsable === "function" && !this.isUsable()) {
      try {
        if (typeof this.baseLoader.destroy === "function") {
          await this.baseLoader.destroy();
        }
      } catch (e) {}
      this.baseLoader = null;
      this.initialized = false;
    }
    if (!this.initialized || !this.baseLoader) {
      this.initPromise = this.initBase();
      await this.initPromise;
    }
    return this.baseLoader;
  }

  isSame(params) {
    return String(this.params?.adUnitId || "") === String(params?.adUnitId || "");
  }

  isUsable() {
    return !!(
      this.baseLoader &&
      (typeof this.baseLoader.isUsable === "function"
        ? this.baseLoader.isUsable()
        : !this.baseLoader.isDestroyed)
    );
  }

  async load() {
    const loader = await this.ensureInitialized();
    return loader.load();
  }

  async show() {
    const loader = await this.ensureInitialized();
    return loader.show();
  }

  async hide() {
    const loader = await this.ensureInitialized();
    return loader.hide();
  }

  isShow() {
    return this.baseLoader ? this.baseLoader.isShow() : false;
  }

  async destroy() {
    if (this.baseLoader && typeof this.baseLoader.destroy === "function") {
      await this.baseLoader.destroy();
    }
    this.baseLoader = null;
    this.initialized = false;
  }

  onLoad(cb) {
    if (this.baseLoader) this.baseLoader.onLoad(cb);
  }
  onError(cb) {
    if (this.baseLoader) this.baseLoader.onError(cb);
  }
  onClose(cb) {
    if (this.baseLoader) this.baseLoader.onClose(cb);
  }
  onHide(cb) {
    if (this.baseLoader) this.baseLoader.onHide(cb);
  }
  onResize(cb) {
    if (this.baseLoader) this.baseLoader.onResize(cb);
  }
  offLoad(cb) {
    if (this.baseLoader) this.baseLoader.offLoad(cb);
  }
  offError(cb) {
    if (this.baseLoader) this.baseLoader.offError(cb);
  }
  offClose(cb) {
    if (this.baseLoader) this.baseLoader.offClose(cb);
  }
  offHide(cb) {
    if (this.baseLoader) this.baseLoader.offHide(cb);
  }
  offResize(cb) {
    if (this.baseLoader) this.baseLoader.offResize(cb);
  }
}

export default CustomAdLoader;
