/** DataNexus 道具枚举，与 mini-game-workspace/shared 保持一致。 */
const IAA_ITEM = Object.freeze({
    UNDO: 15,
    SHUFFLE: 20,
    HINT: 27,
    OTHER: 46
});

function getDataNexusFacade() {
    return deploy.getDataNexus();
}

function callDataNexus(method, ...args) {
    const facade = getDataNexusFacade();
    if (!facade || typeof facade[method] !== 'function') {
        return { code: 100, message: `datanexus method unavailable: ${method}` };
    }
    return facade[method](...args);
}

/**
 * 腾讯营销 IAA 业务 API。
 * 广告通用事件由 AD 内部自动处理；页面、教程、关卡、道具和点位曝光由业务调用。
 */
const DataNexus = Object.freeze({
    IAA_ITEM,
    isReady: () => callDataNexus('isReady'),
    isConfigured: () => callDataNexus('isConfigured'),
    track: (actionType, actionParam) => callDataNexus('track', actionType, actionParam),
    flush: () => callDataNexus('flush'),
    reportLoadFinish: () => callDataNexus('reportLoadFinish'),
    reportHomepageView: () => callDataNexus('reportHomepageView'),
    reportTutorialStart: () => callDataNexus('reportTutorialStart'),
    reportTutorialFinish: () => callDataNexus('reportTutorialFinish'),
    reportAdPlacementShow: (code) => callDataNexus('reportAdPlacementShow', code),
    reportAdClick: (code) => callDataNexus('reportAdClick', code),
    reportAdVideoFinish: (code) => callDataNexus('reportAdVideoFinish', code),
    reportAdImpression: (type) => callDataNexus('reportAdImpression', type),
    reportItemUsed: (itemType, num) => callDataNexus('reportItemUsed', itemType, num),
    levelEnter: (levelId, extra) => callDataNexus('levelEnter', levelId, extra),
    levelPass: () => callDataNexus('levelPass'),
    levelLose: () => callDataNexus('levelLose'),
    levelExit: () => callDataNexus('levelExit'),

    // 与 shared/sdk 导出名一致，便于业务项目平移调用。
    reportIaaLoadFinish: () => callDataNexus('reportLoadFinish'),
    reportIaaHomepageView: () => callDataNexus('reportHomepageView'),
    reportIaaTutorialStart: () => callDataNexus('reportTutorialStart'),
    reportIaaTutorialFinish: () => callDataNexus('reportTutorialFinish'),
    reportIaaAdPlacementShow: (code) => callDataNexus('reportAdPlacementShow', code),
    reportIaaAdClick: (code) => callDataNexus('reportAdClick', code),
    reportIaaAdVideoFinish: (code) => callDataNexus('reportAdVideoFinish', code),
    reportIaaAdImpression: (type) => callDataNexus('reportAdImpression', type),
    reportIaaItemUsed: (itemType, num) => callDataNexus('reportItemUsed', itemType, num),
    reportIaaLevelEnter: (levelId, extra) => callDataNexus('levelEnter', levelId, extra),
    reportIaaLevelPass: () => callDataNexus('levelPass'),
    reportIaaLevelLose: () => callDataNexus('levelLose'),
    reportIaaLevelExit: () => callDataNexus('levelExit')
});

// 与 shared/sdk/index 的具名导出保持一致，业务代码可原样迁移。
