// 创建全局SDK实例
class UnifiedSDK {
    constructor() {
        this.deploy = deploy;
        this.track = track;
        this.ad = ad;
        this.globalAdManager = globalAdManager;  // 添加全局广告管理器
        this.adManager = null;
        this.initialized = false;
        this.currentEnv = currentEnv;
    }

    /**
     * 延迟获取ext配置，避免时序问题
     */
    get extConfig() {
        try {
            return getExtConfig();
        } catch (error) {
            console.warn('⚠️ [UnifiedSDK.extConfig] 配置获取失败:', error);
            return {};
        }
    }

    /**
     * 初始化SDK
     * @param {Object} options 初始化选项
     */
    async init(options = {}) {
        const startTime = Date.now();

        if (this.initialized) {
            console.warn('⚠️ [SDK初始化] SDK已经初始化，跳过重复初始化');
            return this;
        }

        try {
            // 步骤1: 验证环境和配置
            const currentConfig = this.extConfig;
            if (currentConfig && currentConfig.appId) {
                // 配置有效
            } else {
                console.warn(`⚠️ [SDK初始化] 未检测到appId，可能需要先调用deploy.readyAsync(options)`);
            }
            
            // 步骤2: 初始化配置管理器
            const runtimeConfig = (options && Object.keys(options).length > 0) ? options : null;
            await this.deploy.readyAsync(runtimeConfig);
            
            // 步骤3: 初始化广告管理器
            if (!this.deploy.fbisdk) {
                console.warn(`⚠️ [SDK初始化] Deploy.fbisdk为空，这可能影响广告功能`);
            }
            this.adManager = new fbiadSDK(this.deploy.fbisdk);
            
            // 步骤4: 启动应用生命周期
            this.adManager.appLaunch();
            
            // 步骤5: 完成初始化
            this.initialized = true;
            
            return this;
        } catch (error) {
            const endTime = Date.now();
            const duration = endTime - startTime;
            console.error(`❌ [SDK初始化] 初始化失败! 耗时: ${duration}ms`);
            console.error(`💥 [SDK初始化] 错误详情:`, error);
            console.error(`🔍 [SDK初始化] 错误堆栈:`, error.stack);
            throw error;
        }
    }

    /**
     * 获取SDK
     */
    getFbiSDK() {
        return fbiSDK;
    }

    /**
     * 获取配置管理器
     */
    getDeploy() {
        return this.deploy;
    }

    /**
     * 获取广告管理器
     */
    getAdManager() {
        return this.adManager;
    }

    /**
     * 获取埋点管理器
     */
    getTrack() {
        return this.track;
    }

    /**
     * 获取广告位管理器
     */
    getAD() {
        return this.ad;
    }

    /**
     * 获取扩展配置
     */
    getExtConfig() {
        return this.extConfig;
    }

    /**
     * 获取当前环境
     */
    getCurrentEnv() {
        return this.currentEnv;
    }

    /**
     * 显示激励视频广告
     */
    showRewardVideo(code, params, callbacks) {
        if (!this.adManager) {
            console.error('AdManager not initialized');
            return;
        }
        this.adManager.showReward(code, params, callbacks);
    }

    /**
     * 显示插屏广告
     */
    showInterstitial(code, params, callbacks) {
        if (!this.adManager) {
            console.error('AdManager not initialized');
            return;
        }
        this.adManager.showInterstitial(code, params, callbacks);
    }


    /**
     * 显示原生广告
     */
    showNative(code, params, callbacks) {
        if (!this.adManager) {
            console.error('AdManager not initialized');
            return;
        }
        this.adManager.showNative(code, params, callbacks);
    }

    /**
     * 事件埋点
     */
    async trackEvent(eventName, properties) {
        if (this.deploy.fbisdk) {
            return this.deploy.fbisdk.trackAsync(eventName, properties);
        }
    }

    /**
     * 应用显示生命周期
     */
    onAppShow() {
        if (this.adManager) {
            this.adManager.appShow();
        }
    }

    /**
     * 应用隐藏生命周期
     */
    onAppHide() {
        if (this.adManager) {
            this.adManager.appHide();
        }
    }
}

// 创建全局SDK实例
