import FBISDKCore from "./fbiCore/fbiCoreIndex.js";

let core;

/**
 * @description
 * SDK入口初始化
 */
const initFBISDK = (
  appId,
  appName,
  appVersion,
  env,
  runtimeConfig,
) => {

  // 安全检查
  if (typeof FBISDKCore !== "function") {
    console.error(
      "FBISDKCore is not a constructor:",
      typeof FBISDKCore,
      FBISDKCore,
    );
    throw new Error("FBISDKCore is not properly imported");
  }

  // 调用核心初始化
  const sdkInstance = new FBISDKCore(
    appId,
    appName,
    appVersion,
    env,
    runtimeConfig,
  );

  return (core = sdkInstance);
};

export default initFBISDK;
