import uniCompatible from "../../utils/utilsComfortable/uniCompatible.js";

let pageUrlCache = null;

/** 小游戏无页面栈，$url / $url_path 固定值 */
const MINIGAME_PAGE = "gamePage";

function isMinigameRuntime() {
	try {
		if (
			typeof process !== "undefined" &&
			process.env &&
			process.env.BUILD_TARGET === "minigame"
		) {
			return true;
		}
	} catch (e) {}
	try {
		// 懒加载，避免与 Deploy → fbiCore 循环依赖
		// eslint-disable-next-line global-require
		const Deploy = require("../../utils/Deploy.js").default;
		if (Deploy && typeof Deploy.isMinigame === "function") {
			return !!Deploy.isMinigame();
		}
	} catch (e) {}
	return false;
}

function minigamePageUrl() {
	return {
		urlPath: MINIGAME_PAGE,
		urlQuery: "",
		urlFull: MINIGAME_PAGE,
	};
}

function normalizePath(path) {
	if (!path) return "";
	return String(path).replace(/^\//, "");
}

function serializeQuery(query) {
	if (!query || typeof query !== "object") return "";
	return Object.keys(query)
		.filter((key) => query[key] !== undefined && query[key] !== null && query[key] !== "")
		.map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(String(query[key]))}`)
		.join("&");
}

function buildUrlFromPathAndQuery(path, query) {
	const urlPath = normalizePath(path);
	if (!urlPath) {
		return { urlPath: "", urlQuery: "", urlFull: "" };
	}
	const urlQuery = serializeQuery(query);
	const urlFull = urlQuery ? `${urlPath}?${urlQuery}` : urlPath;
	return { urlPath, urlQuery, urlFull };
}

function parseFullPath(fullPath) {
	const normalized = normalizePath(fullPath);
	if (!normalized) {
		return { urlPath: "", urlQuery: "", urlFull: "" };
	}
	const qIndex = normalized.indexOf("?");
	if (qIndex === -1) {
		return { urlPath: normalized, urlQuery: "", urlFull: normalized };
	}
	const urlPath = normalized.slice(0, qIndex);
	const urlQuery = normalized.slice(qIndex + 1);
	return {
		urlPath,
		urlQuery,
		urlFull: urlQuery ? `${urlPath}?${urlQuery}` : urlPath,
	};
}

function isValidPageUrl(urlInfo) {
	return !!(urlInfo && urlInfo.urlPath);
}

function getEnterOptionsSync() {
	try {
		if (typeof uni !== "undefined" && uni.getEnterOptionsSync) {
			return uni.getEnterOptionsSync();
		}
		if (typeof wx !== "undefined" && wx.getEnterOptionsSync) {
			return wx.getEnterOptionsSync();
		}
		if (typeof tt !== "undefined" && tt.getEnterOptionsSync) {
			return tt.getEnterOptionsSync();
		}
	} catch (e) {}
	return null;
}

function resolveFromCurrentPages() {
	if (typeof getCurrentPages !== "function") {
		return null;
	}
	const pages = getCurrentPages();
	if (!pages || pages.length === 0) {
		return null;
	}
	const page = pages[pages.length - 1];
	if (!page) {
		return null;
	}

	if (page.$page && page.$page.fullPath) {
		const parsed = parseFullPath(page.$page.fullPath);
		if (isValidPageUrl(parsed)) {
			return parsed;
		}
	}

	const route = page.route || (page.$page && page.$page.route) || "";
	const options = page.options || (page.$page && page.$page.options) || {};
	const built = buildUrlFromPathAndQuery(route, options);
	if (isValidPageUrl(built)) {
		return built;
	}

	return null;
}

function resolveFromOptionsSync(getter) {
	try {
		const options = getter();
		if (!options || !options.path) {
			return null;
		}
		return buildUrlFromPathAndQuery(options.path, options.query || {});
	} catch (e) {
		return null;
	}
}

/**
 * 从多个来源解析当前页面 URL，并缓存最后一次有效结果。
 * 优先 getCurrentPages 当前页，再回退合并后的 launchOptions，最后 enterOptions。
 */
export function resolvePageUrl() {
	if (isMinigameRuntime()) {
		pageUrlCache = minigamePageUrl();
		return pageUrlCache;
	}

	const sources = [
		resolveFromCurrentPages,
		// Deploy.setLaunchOptions 合并后的启动参数（特殊页平台原生常为空）
		() => resolveFromOptionsSync(() => uniCompatible.getLaunchOptionsSync()),
		() => resolveFromOptionsSync(getEnterOptionsSync),
	];

	for (const getUrl of sources) {
		const resolved = getUrl();
		if (isValidPageUrl(resolved)) {
			pageUrlCache = resolved;
			return resolved;
		}
	}

	if (pageUrlCache) {
		return pageUrlCache;
	}

	return { urlPath: "", urlQuery: "", urlFull: "" };
}

/**
 * 兼容小程序环境：不依赖 URLSearchParams
 */
function parseQueryString(queryString) {
	const obj = {};
	if (!queryString || typeof queryString !== "string") {
		return obj;
	}
	String(queryString)
		.split("&")
		.forEach((pair) => {
			if (!pair) return;
			const eqIndex = pair.indexOf("=");
			const rawKey = eqIndex === -1 ? pair : pair.slice(0, eqIndex);
			const rawValue = eqIndex === -1 ? "" : pair.slice(eqIndex + 1);
			if (!rawKey) return;
			try {
				obj[decodeURIComponent(rawKey)] = decodeURIComponent(rawValue);
			} catch (e) {
				obj[rawKey] = rawValue;
			}
		});
	return obj;
}

export function applyPageUrlToProperties(properties, urlInfo) {
	const props = properties || {};

	// 小游戏无页面概念：$url / $url_path 固定为 gamePage
	if (isMinigameRuntime()) {
		const fixed = minigamePageUrl();
		props.$url = fixed.urlFull;
		props.$url_path = fixed.urlPath;
		props.$url_query = fixed.urlQuery;
		pageUrlCache = fixed;
		return props;
	}

	// 始终以调用时当前页面为准；仅在当前页不可用时使用入参/兜底解析
	const resolved =
		(isValidPageUrl(urlInfo) ? urlInfo : null) ||
		resolveFromCurrentPages() ||
		resolvePageUrl();

	props.$url = resolved.urlFull || "";
	props.$url_path = resolved.urlPath || "";
	props.$url_query = resolved.urlQuery || "";

	if (props.$url_path) {
		pageUrlCache = {
			urlPath: props.$url_path,
			urlQuery: props.$url_query,
			urlFull: props.$url,
		};
	}

	if (props.$url_query) {
		props.analysis = {
			...(props.analysis || {}),
			...parseQueryString(props.$url_query),
		};
	}

	return props;
}

/**
 * 批量上报前补全事件中的页面 URL 字段，避免入队时页面栈尚未就绪导致丢失。
 */
export function enrichTrackEventPageUrl(event) {
	if (!event || typeof event !== "object") {
		return event;
	}
	event.properties = applyPageUrlToProperties(event.properties);
	return event;
}
