/**
 * ext配置处理器
 * 统一处理小程序模式下的配置获取
 */

// 运行时配置存储
let runtimeConfig = null;
// 是否通过 readyAsync(config) 注入（小游戏）
let injectedFromReadyAsync = false;

/**
 * 设置运行时配置
 * @param {Object} config 运行时配置
 */
export function setRuntimeConfig(config) {
    runtimeConfig = config;
    if (config && typeof config === 'object' && Object.keys(config).length > 0) {
        injectedFromReadyAsync = true;
    }
}

/**
 * 获取运行时配置
 * @returns {Object|null} 运行时配置
 */
export function getRuntimeConfig() {
    return runtimeConfig;
}

/**
 * 获取ext配置的统一方法
 * @returns {Object} ext配置对象
 */
export function getExtConfig() {
    try {
        // 方式0：优先使用通过 setRuntimeConfig 注入的运行时配置
        // 这是 Deploy.readyAsync(config) 传入配置的主要路径，必须最高优先级
        if (runtimeConfig && typeof runtimeConfig === 'object' && Object.keys(runtimeConfig).length > 0) {
            return runtimeConfig;
        }

        let extConfig = {};
        
        // 方式1：通过微信getExtConfigSync获取
        if (typeof wx !== 'undefined' && wx.getExtConfigSync) {
            try {
                extConfig = wx.getExtConfigSync() || {};
            } catch (error) {
                console.warn('⚠️ wx.getExtConfigSync获取失败:', error);
            }
        }
        
        // 方式2：通过抖音getExtConfigSync获取（顶层与 extConfig 合并，保留 requestHTTPS / trackHTTPS）
        if (Object.keys(extConfig).length === 0 && typeof tt !== 'undefined' && tt.getExtConfigSync) {
            try {
                const e = tt.getExtConfigSync() || {};
                const nested =
                    e.extConfig && typeof e.extConfig === 'object' ? e.extConfig : {};
                const { extConfig: _ignored, ...top } = e;
                extConfig = { ...top, ...nested };
                console.log('【ext-config-handler】 tt.getExtConfigSync--->', extConfig);
            } catch (error) {
                console.warn('⚠️ tt.getExtConfigSync获取失败:', error);
            }
        }
        
        // 如果仍然没有配置，返回默认配置
        if (!extConfig || Object.keys(extConfig).length === 0) {
            console.warn('⚠️ 未能获取到ext配置，使用默认配置');
            extConfig = {
                appId: '',
                channel: '',
                environment: 'production'
            };
        }
        
        return extConfig;
        
    } catch (error) {
        console.error('❌ 获取ext配置失败:', error);
        return {
            appId: '',
            channel: '',
            environment: 'production'
        };
    }
}


/**
 * 获取当前运行环境
 * @returns {string} 当前环境类型
 */
export function getCurrentEnv() {
    try {
        // 微信
        if (typeof wx !== 'undefined' && (wx.getSystemInfo || wx.getSystemInfoSync || wx.getWindowInfo || wx.login || wx.createRewardedVideoAd)) {
            return 'wechat';
        }
        
        // 抖音
        if (typeof tt !== 'undefined' && tt.getSystemInfo) {
            return 'douyin';
        }
        
        return 'unknown';
    } catch (error) {
        console.warn('⚠️ 检测环境时出错:', error);
        return 'unknown';
    }
}

/**
 * 是否小游戏：以 readyAsync(config) 是否传入配置为准
 */
export function isMinigame() {
    return !!injectedFromReadyAsync;
}

/**
 * 检查是否为微信/抖音等小程序类环境
 */
export function isMiniprogram() {
    const env = getCurrentEnv();
    return env === 'wechat' || env === 'douyin';
}

/**
 * 返回已通过 readyAsync(config) / setRuntimeConfig 注入的配置
 */
export function getExtConfigSync() {
    if (runtimeConfig && typeof runtimeConfig === 'object' && Object.keys(runtimeConfig).length > 0) {
        return runtimeConfig;
    }
    console.warn('⚠️ 未注入运行时配置，请通过 readyAsync(config) / setRuntimeConfig 传入');
    return {};
}