import comfortable from "./fbiadComfortable/fbiadCFIndex.js";

let all_codes = {}


/**
 * 插屏广告基类，延迟初始化
 */
let InterstitialAdLoaderBase = null;
let initPromise = null;

/**
 * 异步初始化插屏广告基类
 */
const initInterstitialAdLoaderBase = async () => {
	if (initPromise) {
		return initPromise;
	}
	
	initPromise = (async () => {
		try {
			InterstitialAdLoaderBase = await comfortable.InterstitialAdLoaderAsync();
			return InterstitialAdLoaderBase;
		} catch (error) {
			throw error;
		}
	})();
	
	return initPromise;
};

/**
 * @description: 初始化一个插屏广告，开发者需要将参数置换为自己小程序的广告id
 */
class InterstitialAdLoader {
    constructor(params) {
        this.params = params;
        this.initialized = false;
        this.baseLoader = null;
        
        // 异步初始化基类
        this.initPromise = this.initBase();
    }
    
    async initBase() {
        try {
            if (!InterstitialAdLoaderBase) {
                await initInterstitialAdLoaderBase();
            }
            
            // 创建基类实例
            this.baseLoader = new InterstitialAdLoaderBase(this.params);
            this.initialized = true;
            
            return this.baseLoader;
        } catch (error) {
			throw error;
		}
    }
    
    async ensureInitialized() {
        if (!this.initialized) {
            await this.initPromise;
        }
        return this.baseLoader;
    }
    
    async load() {
        const loader = await this.ensureInitialized();
        if (!loader) {
            throw new Error('插屏广告对象未初始化或已被销毁');
        }
        return loader.load();
    }
    
    async show() {
        const loader = await this.ensureInitialized();
        if (!loader) {
            const error = new Error('插屏广告初始化失败，loader为空');
            console.error('❌ [InterstitialAdLoader.show]', error);
            throw error;
        }
        
        // 额外检查 loader 的有效性
        if (!loader.show || typeof loader.show !== 'function') {
            const error = new Error('插屏广告对象缺少 show 方法');
            console.error('❌ [InterstitialAdLoader.show] loader 对象无效:', loader);
            throw error;
        }
        
        return loader.show();
    }
    
    async destroy() {
        this.initialized = false;
        if (this.baseLoader && typeof this.baseLoader.destroy === 'function') {
            try {
                await this.baseLoader.destroy();
            } catch (error) {
                console.warn('⚠️ [InterstitialAdLoader.destroy] 销毁 baseLoader 出错:', error);
            }
        }
        this.baseLoader = null;
    }
    
    onLoad(callback) {
        this.ensureInitialized().then(loader => {
            if (loader && callback && typeof callback === 'function' && typeof loader.onLoad === 'function') {
                loader.onLoad(callback);
            }
        });
    }
    
    onError(callback) {
        this.ensureInitialized().then(loader => {
            if (loader && callback && typeof callback === 'function' && typeof loader.onError === 'function') {
                loader.onError(callback);
            }
        });
    }
    
    onClose(callback) {
        this.ensureInitialized().then(loader => {
            if (loader && callback && typeof callback === 'function' && typeof loader.onClose === 'function') {
                loader.onClose(callback);
            }
        });
    }
    
    offLoad(callback) {
        this.ensureInitialized().then(loader => {
            if (loader && callback && typeof callback === 'function' && typeof loader.offLoad === 'function') {
                loader.offLoad(callback);
            }
        });
    }
    
    offError(callback) {
        this.ensureInitialized().then(loader => {
            if (loader && callback && typeof callback === 'function' && typeof loader.offError === 'function') {
                loader.offError(callback);
            }
        });
    }
    
    offClose(callback) {
        this.ensureInitialized().then(loader => {
            if (loader && callback && typeof callback === 'function' && typeof loader.offClose === 'function') {
                loader.offClose(callback);
            }
        });
    }
}

export default InterstitialAdLoader;