/**
 * 腾讯营销 DataNexus 小游戏 SDK 封装（对齐 mini-game-workspace/shared）
 * 启用条件：readyAsync 同时传入 wxGameCode + wxGameSecretKey
 *  - wxGameCode      → user_action_set_id
 *  - wxGameSecretKey → secret_key
 *  - appId           → appid
 *  - 登录后 userId   → openid / user_unique_id
 *
 * 仅微信小游戏生效；抖音 / 缺凭证时跳过，不挡主流程。
 */
import { SDK } from "./vendor/index.js";
import {
  attachLevelEndParams,
  buildLevelEnterParams,
  impressionTypeOf,
  placementNameOf,
  readDefaultLevelInfo,
} from "./iaa.js";

const SECRET_KEY_LEN = 32;
const BACKFLOW_DAYS = 30;
const STATE_KEY = "DN_IAA_USER_STATE";

function isWeChatMinigame() {
  try {
    return (
      typeof wx !== "undefined" &&
      typeof tt === "undefined" &&
      typeof wx.getSystemInfoSync === "function"
    );
  } catch (e) {
    return false;
  }
}

function isDevtools() {
  try {
    if (typeof wx === "undefined" || !wx.getSystemInfoSync) return false;
    return wx.getSystemInfoSync().platform === "devtools";
  } catch (e) {
    return false;
  }
}

function storageGet(key) {
  try {
    if (typeof wx !== "undefined" && wx.getStorageSync) {
      return wx.getStorageSync(key);
    }
  } catch (e) {}
  return null;
}

function storageSet(key, val) {
  try {
    if (typeof wx !== "undefined" && wx.setStorageSync) {
      wx.setStorageSync(key, val);
    }
  } catch (e) {}
}

function getCurrentDate() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function daysSinceYmd(ymd) {
  if (!ymd) return -1;
  try {
    const datePart = String(ymd).split(" ")[0];
    const t = new Date(`${datePart}T00:00:00`).getTime();
    if (!Number.isFinite(t)) return -1;
    const now = new Date();
    const today = new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate(),
    ).getTime();
    return Math.floor((today - t) / 86400000);
  } catch (e) {
    return -1;
  }
}

function readState() {
  const raw = storageGet(STATE_KEY);
  if (!raw) return { userId: "", registered: false, lastReactiveYmd: "" };
  if (typeof raw === "object") {
    return {
      userId: String(raw.userId || ""),
      registered: raw.registered === true,
      lastReactiveYmd: String(raw.lastReactiveYmd || ""),
    };
  }
  try {
    const parsed = JSON.parse(raw);
    return {
      userId: String((parsed && parsed.userId) || ""),
      registered: !!(parsed && parsed.registered),
      lastReactiveYmd: String((parsed && parsed.lastReactiveYmd) || ""),
    };
  } catch (e) {
    return { userId: "", registered: false, lastReactiveYmd: "" };
  }
}

function writeState(state) {
  storageSet(STATE_KEY, {
    userId: state.userId || "",
    registered: state.registered === true,
    lastReactiveYmd: state.lastReactiveYmd || "",
  });
}

function logTrackFail(method, result) {
  if (!result || result.code === 0) return;
  console.warn(`[DataNexus] ${method} failed`, result);
}

function hasCredentials(code, secret) {
  const userActionSetId = Number(code);
  const secretKey = String(secret || "").trim();
  return userActionSetId > 0 && secretKey.length === SECRET_KEY_LEN;
}

class DataNexusManager {
  constructor() {
    this._inited = false;
    this._skipped = false;
    this._sdk = null;
    this._openid = "";
    this._pending = [];
    this._debug = false;
    this._config = null;
    this._shareBound = false;
    this._hideBound = false;
    this._level = null;
  }

  /**
   * 是否配置了启用凭证（不代表已初始化成功）
   */
  isConfigured() {
    const c = this._config || {};
    return hasCredentials(c.wxGameCode, c.wxGameSecretKey);
  }

  isReady() {
    return this._inited && !!this._sdk;
  }

  /**
   * 注入 readyAsync 配置；有凭证则标记待初始化（需登录后 bindUser）
   */
  configure(runtime = {}) {
    this._config = {
      wxGameCode: runtime.wxGameCode,
      wxGameSecretKey: runtime.wxGameSecretKey,
      appId: runtime.appId,
      debug: runtime.debug === true,
    };
    if (!isWeChatMinigame()) {
      this._skipped = true;
      console.log("ℹ️ [DataNexus] 非微信小游戏，跳过");
      return false;
    }
    if (!this.isConfigured()) {
      console.log(
        "ℹ️ [DataNexus] 未同时配置 wxGameCode + wxGameSecretKey，跳过腾讯营销 SDK",
      );
      return false;
    }
    console.log("✅ [DataNexus] 已配置凭证，登录后将初始化");
    return true;
  }

  /**
   * 登录完成后绑定用户并初始化 SDK
   * @param {{ userId?: string, createdDt?: string }} authData
   */
  bindUser(authData) {
    if (this._skipped) return;
    if (!authData || authData.userId == null || authData.userId === "") return;
    const userId = String(authData.userId).trim();
    if (!userId) return;

    if (!this.isReady()) this._init(userId);
    if (!this.isReady()) return;

    if (this._openid !== userId) {
      const result = this._sdk.setOpenId(userId);
      logTrackFail("setOpenId", result);
      if (!result || result.code === 0) this._openid = userId;
    }
    if (typeof this._sdk.setUserUniqueId === "function") {
      this._sdk.setUserUniqueId(userId);
    }

    this._reportIdentityEvents(userId, authData.createdDt);
  }

  _init(openid) {
    if (this._inited) return this._sdk;
    if (this._skipped) return null;
    if (!isWeChatMinigame()) {
      this._skipped = true;
      return null;
    }

    const config = this._config || {};
    const userActionSetId = Number(config.wxGameCode);
    const secretKey = String(config.wxGameSecretKey || "").trim();
    const appid = String(config.appId || "").trim();

    if (!hasCredentials(config.wxGameCode, config.wxGameSecretKey) || !appid) {
      console.warn(
        "[DataNexus] skip init: missing wxGameCode / wxGameSecretKey / appId",
      );
      return null;
    }
    if (!openid) return null;

    try {
      this._debug = config.debug === true || isDevtools();
      SDK.setDebug(this._debug);
      // 限制 DN 并发，避免与业务请求一起顶满微信 5 路上限
      if (typeof SDK.setRequestConcurrency === "function") {
        SDK.setRequestConcurrency(2);
      }
      this._sdk = new SDK({
        user_action_set_id: userActionSetId,
        secret_key: secretKey,
        appid,
        openid,
        user_unique_id: openid,
        auto_track: true,
      });
      this._openid = openid;
    } catch (e) {
      this._skipped = true;
      console.warn("[DataNexus] init threw", e);
      return null;
    }

    const initResult =
      this._sdk && typeof this._sdk.getInitResult === "function"
        ? this._sdk.getInitResult()
        : { inited: true, initErrMsg: "" };

    if (!initResult || !initResult.inited) {
      this._skipped = true;
      this._sdk = null;
      console.warn(
        "[DataNexus] init failed",
        initResult && initResult.initErrMsg,
      );
      return null;
    }

    this._inited = true;
    this._bindShareAndFavorite();
    this._bindHideLevelExit();
    this._flushPending();
    console.log(
      "[DataNexus] inited",
      appid,
      userActionSetId,
      `debug=${this._debug}`,
    );
    return this._sdk;
  }

  _reportIdentityEvents(userId, createdDt) {
    const days = daysSinceYmd(createdDt);
    if (days < 0) return;

    let state = readState();
    if (state.userId !== userId) {
      state = { userId, registered: false, lastReactiveYmd: "" };
    }

    if (days === 0) {
      if (!state.registered) {
        logTrackFail("onRegister", this._sdk.onRegister());
        state.registered = true;
        writeState(state);
      }
      return;
    }

    if (days < BACKFLOW_DAYS) return;

    const sinceReactive = state.lastReactiveYmd
      ? daysSinceYmd(state.lastReactiveYmd)
      : BACKFLOW_DAYS;
    if (sinceReactive >= 0 && sinceReactive < BACKFLOW_DAYS) return;

    logTrackFail(
      "RE_ACTIVE",
      this._sdk.track("RE_ACTIVE", { backFlowDay: BACKFLOW_DAYS }),
    );
    state.lastReactiveYmd = getCurrentDate();
    writeState(state);
  }

  track(actionType, actionParam) {
    if (!this.isReady()) {
      if (this._skipped) return { code: 100, message: "datanexus skipped" };
      if (!this.isConfigured()) {
        return { code: 100, message: "datanexus not configured" };
      }
      this._pending.push([actionType, actionParam || {}]);
      return { code: 0, message: "queued" };
    }
    const result = this._sdk.track(actionType, actionParam);
    logTrackFail("track", result);
    return result;
  }

  _flushPending() {
    const list = this._pending;
    this._pending = [];
    list.forEach((item) => this.track(item[0], item[1]));
  }

  _bindShareAndFavorite() {
    if (this._shareBound || typeof wx === "undefined") return;
    this._shareBound = true;
    try {
      if (typeof wx.showShareMenu === "function") {
        wx.showShareMenu({
          withShareTicket: true,
          menus: ["shareAppMessage", "shareTimeline"],
        });
      }
      if (typeof wx.onShareAppMessage === "function") {
        wx.onShareAppMessage(() => {
          this.track("SHARE", { target: "APP_MESSAGE" });
          return {};
        });
      }
      if (typeof wx.onShareTimeline === "function") {
        wx.onShareTimeline(() => {
          this.track("SHARE", { target: "TIME_LINE" });
          return {};
        });
      }
      if (typeof wx.onAddToFavorites === "function") {
        wx.onAddToFavorites(() => {
          this.track("ADD_TO_WISHLIST", { type: "default" });
          return {};
        });
      }
    } catch (e) {
      console.warn("[DataNexus] bind share/favorite failed", e);
    }
  }

  _bindHideLevelExit() {
    if (
      this._hideBound ||
      typeof wx === "undefined" ||
      typeof wx.onHide !== "function"
    ) {
      return;
    }
    this._hideBound = true;
    wx.onHide(() => {
      this.levelExit();
    });
  }

  reportLoadFinish() {
    return this.track("LOAD_FINISH", {});
  }

  reportHomepageView() {
    return this.track("HOMEPAGE_VIEW", {});
  }

  reportTutorialStart() {
    return this.track("TUTORIAL_START", {});
  }

  reportTutorialFinish() {
    if (!this.isReady()) return this.track("TUTORIAL_FINISH", {});
    const result = this._sdk.onTutorialFinish();
    logTrackFail("onTutorialFinish", result);
    return result;
  }

  reportAdPlacementShow(code) {
    return this.track("AD_PLACEMENT_SHOW", {
      ad_placement_name: placementNameOf(code),
    });
  }

  reportAdClick(code) {
    return this.track("AD_CLICK", {
      ad_placement_name: placementNameOf(code),
    });
  }

  reportAdVideoFinish(code) {
    if (this._level) this._level.adCnt += 1;
    return this.track("AD_VIDEO_FINISH", {
      ad_placement_name: placementNameOf(code),
    });
  }

  reportAdImpression(adTypeKey) {
    return this.track("AD_IMPRESSION", {
      ad_type: impressionTypeOf(adTypeKey),
    });
  }

  reportItemUsed(itemType, num) {
    if (!this._level) return;
    const type = Number(itemType) || 46;
    const count = Number(num) || 1;
    this._level.items[type] = (this._level.items[type] || 0) + count;
  }

  levelEnter(levelId, extra) {
    this.levelExit();
    const info = readDefaultLevelInfo(levelId, extra);
    this._level = {
      startedAt: Date.now(),
      adCnt: 0,
      items: {},
      info,
    };
    const params = buildLevelEnterParams(info);
    const result = this.track("LEVEL_ENTER", params);
    if (this._debug) console.log("[DataNexus] LEVEL_ENTER", params, result);
    return result;
  }

  _endLevel(actionType) {
    if (!this._level) {
      const result = { code: 0, message: "no level" };
      if (this._debug) {
        console.warn(`[DataNexus] ${actionType} skipped`, result);
      }
      return result;
    }
    const session = this._level;
    this._level = null;
    const params = attachLevelEndParams(
      buildLevelEnterParams(session.info),
      session,
    );
    const result = this.track(actionType, params);
    if (this._debug) {
      console.log(`[DataNexus] ${actionType}`, params, result);
    }
    return result;
  }

  levelPass() {
    return this._endLevel("LEVEL_PASS");
  }

  levelLose() {
    return this._endLevel("LEVEL_LOSE");
  }

  levelExit() {
    return this._endLevel("LEVEL_EXIT");
  }

  flush() {
    if (!this.isReady()) return;
    try {
      this._sdk.flush();
    } catch (e) {
      console.warn("[DataNexus] flush failed", e);
    }
  }

  /** 对外 facade，对齐 shared 的 GameGlobal.$dn 能力子集 */
  getFacade() {
    return {
      isReady: this.isReady.bind(this),
      isConfigured: this.isConfigured.bind(this),
      track: this.track.bind(this),
      flush: this.flush.bind(this),
      reportLoadFinish: this.reportLoadFinish.bind(this),
      reportHomepageView: this.reportHomepageView.bind(this),
      reportTutorialStart: this.reportTutorialStart.bind(this),
      reportTutorialFinish: this.reportTutorialFinish.bind(this),
      reportAdPlacementShow: this.reportAdPlacementShow.bind(this),
      reportAdClick: this.reportAdClick.bind(this),
      reportAdVideoFinish: this.reportAdVideoFinish.bind(this),
      reportAdImpression: this.reportAdImpression.bind(this),
      reportItemUsed: this.reportItemUsed.bind(this),
      levelEnter: this.levelEnter.bind(this),
      levelPass: this.levelPass.bind(this),
      levelLose: this.levelLose.bind(this),
      levelExit: this.levelExit.bind(this),
    };
  }
}

const dataNexusManager = new DataNexusManager();

export const reportIaaLoadFinish =
  dataNexusManager.reportLoadFinish.bind(dataNexusManager);
export const reportIaaHomepageView =
  dataNexusManager.reportHomepageView.bind(dataNexusManager);
export const reportIaaTutorialStart =
  dataNexusManager.reportTutorialStart.bind(dataNexusManager);
export const reportIaaTutorialFinish =
  dataNexusManager.reportTutorialFinish.bind(dataNexusManager);
export const reportIaaAdPlacementShow =
  dataNexusManager.reportAdPlacementShow.bind(dataNexusManager);
export const reportIaaAdClick =
  dataNexusManager.reportAdClick.bind(dataNexusManager);
export const reportIaaAdVideoFinish =
  dataNexusManager.reportAdVideoFinish.bind(dataNexusManager);
export const reportIaaAdImpression =
  dataNexusManager.reportAdImpression.bind(dataNexusManager);
export const reportIaaItemUsed =
  dataNexusManager.reportItemUsed.bind(dataNexusManager);
export const reportIaaLevelEnter =
  dataNexusManager.levelEnter.bind(dataNexusManager);
export const reportIaaLevelPass =
  dataNexusManager.levelPass.bind(dataNexusManager);
export const reportIaaLevelLose =
  dataNexusManager.levelLose.bind(dataNexusManager);
export const reportIaaLevelExit =
  dataNexusManager.levelExit.bind(dataNexusManager);

export default dataNexusManager;
export { hasCredentials };
export { IAA_ITEM } from "./iaa.js";
