/**
 * 全局广告管理器
 * 用于在 uniapp 中管理原生模板广告组件的注册和状态
 * 支持多实例模式：同一个 code 可以注册多个组件实例（用于信息流广告场景）
 */
class GlobalAdManager {
  constructor() {
    // 单实例模式存储：Map<componentKey, component>
    // componentKey = pagePath@code
    this.nativeAdComponents = new Map();
    
    // 多实例模式存储：Map<code, Map<instanceId, component>>
    // 用于信息流广告场景，同一个 code 可以有多个实例
    this.multiInstanceComponents = new Map();
    
    this.ad = null;
    this.isInitialized = false;
  }

  /**
   * 检查组件是否有效（未销毁且DOM存在）
   * @param {Object} component 组件实例
   * @returns {Boolean}
   */
  isValidComponent(component) {
    if (!component) return false;
    
    // 检查组件是否已销毁
    if (component.isDestroyed === true || component.isComponentDestroyed?.() === true) {
      return false;
    }
    
    // 检查Vue组件实例是否有效
    if (component.$el && component.$el.parentNode === null) {
      return false;
    }
    
    // 移除页面栈检查，因为这会导致页面切换时组件被误删
    // 只要组件没有被明确销毁，就认为是有效的
    return true;
  }

  /**
   * 清理无效的组件
   */
  cleanupInvalidComponents() {
    let cleanedCount = 0;
    
    // 清理单实例模式的无效组件
    const toRemove = [];
    this.nativeAdComponents.forEach((component, code) => {
      if (!this.isValidComponent(component)) {
        // console.log(`[GlobalAdManager] 发现无效组件，准备清理: ${code}`);
        toRemove.push(code);
      }
    });
    
    toRemove.forEach(code => {
      this.nativeAdComponents.delete(code);
      // console.log(`[GlobalAdManager] 已清理无效组件: ${code}`);
    });
    cleanedCount += toRemove.length;
    
    // 清理多实例模式的无效组件
    const codesToRemove = [];
    this.multiInstanceComponents.forEach((instanceMap, code) => {
      const invalidInstanceIds = [];
      instanceMap.forEach((component, instanceId) => {
        if (!this.isValidComponent(component)) {
          invalidInstanceIds.push(instanceId);
        }
      });
      
      invalidInstanceIds.forEach(instanceId => {
        instanceMap.delete(instanceId);
        cleanedCount++;
        // console.log(`[GlobalAdManager] 已清理无效的多实例组件: ${code}@${instanceId}`);
      });
      
      // 如果该 code 下没有实例了，标记清理
      if (instanceMap.size === 0) {
        codesToRemove.push(code);
      }
    });
    
    codesToRemove.forEach(code => {
      this.multiInstanceComponents.delete(code);
    });
    
    return cleanedCount;
  }

  /**
   * 等待组件注册（带超时）
   * @param {String} code 广告代码
   * @param {Number} timeout 超时时间（毫秒）
   * @param {Number} interval 检查间隔（毫秒）
   * @returns {Promise<Object|null>}
   */
  async waitForComponent(code, timeout = 1000, interval = 50) {
    const startTime = Date.now();
    
    while (Date.now() - startTime < timeout) {
      // 先清理无效组件
      this.cleanupInvalidComponents();
      
      // 检查目标组件是否已注册（会自动从多实例存储中查找）
      const component = this.getNativeAdComponent(code);
      if (component) {
        console.log(`[GlobalAdManager] 找到组件 ${code}，等待时间: ${Date.now() - startTime}ms`);
        return component;
      }
      
      // 等待一段时间后重试
      await new Promise(resolve => setTimeout(resolve, interval));
    }
    
    console.warn(`[GlobalAdManager] 等待组件 ${code} 超时 (${timeout}ms)`);
    console.log(`[GlobalAdManager] 当前多实例存储: ${Array.from(this.multiInstanceComponents.keys()).join(', ')}`);
    return null;
  }

  /**
   * 初始化全局管理器
   * @param {Object} ad 广告位管理器实例
   */
  init(ad) {
    this.ad = ad;
    this.isInitialized = true;
  }

  /**
   * 生成组件的唯一键（页面路径 + 广告代码）
   * @param {String} code 广告代码
   * @param {Object} component 组件实例
   * @returns {String} 唯一键
   */
  generateComponentKey(code, component) {
    try {
      // 尝试获取页面路径
      let pagePath = '';
      if (component && component.$parent && component.$parent.route) {
        pagePath = component.$parent.route;
      } else {
        // 如果无法获取组件的页面路径，尝试从页面栈获取当前页面
        const pages = getCurrentPages();
        if (pages && pages.length > 0) {
          const currentPage = pages[pages.length - 1];
          pagePath = currentPage.route || '';
        }
      }
      
      // 生成复合键：页面路径@广告代码
      return `${pagePath}@${code}`;
    } catch (error) {
      console.warn('[GlobalAdManager] 生成组件键时出错，使用简单键:', error);
      return code; // 回退到简单的广告代码作为键
    }
  }

  /**
   * 注册原生模板广告组件
   * @param {String} code 广告代码
   * @param {Object} component 组件实例
   */
  registerNativeAdComponent(code, component) {
    // 注册前先清理无效组件
    this.cleanupInvalidComponents();
    
    // 检查是否为多实例模式
    const isMultiInstance = component && component.instanceId;
    
    if (isMultiInstance) {
      // 多实例模式注册
      this.registerMultiInstanceComponent(code, component.instanceId, component);
      return;
    }
    
    // 单实例模式（原有逻辑）
    // 生成唯一键
    const componentKey = this.generateComponentKey(code, component);
    
    // 如果已存在同键组件，检查是否有效
    if (this.nativeAdComponents.has(componentKey)) {
      const existingComponent = this.nativeAdComponents.get(componentKey);
      if (this.isValidComponent(existingComponent)) {
        console.warn(`[GlobalAdManager] 组件 ${componentKey} 已存在且有效，跳过注册`);
        return;
      } else {
        console.log(`[GlobalAdManager] 发现无效的同键组件 ${componentKey}，将被新组件替换`);
      }
    }
    
    this.nativeAdComponents.set(componentKey, component);
    console.log(`[GlobalAdManager] 组件注册成功: ${componentKey}`);
  }

  /**
   * 多实例模式：注册组件
   * @param {String} code 广告代码
   * @param {String} instanceId 实例ID
   * @param {Object} component 组件实例
   */
  registerMultiInstanceComponent(code, instanceId, component) {
    if (!this.multiInstanceComponents.has(code)) {
      this.multiInstanceComponents.set(code, new Map());
    }
    
    const instanceMap = this.multiInstanceComponents.get(code);
    
    // 检查是否已存在且有效
    if (instanceMap.has(instanceId)) {
      const existingComponent = instanceMap.get(instanceId);
      if (this.isValidComponent(existingComponent)) {
        console.warn(`[GlobalAdManager] 多实例组件 ${code}@${instanceId} 已存在且有效，跳过注册`);
        return;
      }
    }
    
    instanceMap.set(instanceId, component);
    console.log(`[GlobalAdManager] 多实例组件注册成功: ${code}@${instanceId}，当前实例数: ${instanceMap.size}`);
  }

  /**
   * 注销原生模板广告组件
   * @param {String} code 广告代码
   * @param {Object} component 组件实例（可选，用于生成精确的键）
   */
  unregisterNativeAdComponent(code, component = null) {
    // 检查是否为多实例模式
    if (component && component.instanceId) {
      this.unregisterMultiInstanceComponent(code, component.instanceId);
      return;
    }
    
    if (component) {
      // 如果提供了组件实例，生成精确的键进行注销
      const componentKey = this.generateComponentKey(code, component);
      if (this.nativeAdComponents.has(componentKey)) {
        this.nativeAdComponents.delete(componentKey);
        console.log(`[GlobalAdManager] 组件注销成功: ${componentKey}`);
      }
    } else {
      // 兼容模式：查找所有匹配的键并注销
      const keysToDelete = [];
      for (const [key] of this.nativeAdComponents) {
        if (key.endsWith(`@${code}`) || key === code) {
          keysToDelete.push(key);
        }
      }
      keysToDelete.forEach(key => {
        this.nativeAdComponents.delete(key);
        console.log(`[GlobalAdManager] 组件注销成功（兼容模式）: ${key}`);
      });
    }
  }

  /**
   * 多实例模式：注销组件
   * @param {String} code 广告代码
   * @param {String} instanceId 实例ID
   */
  unregisterMultiInstanceComponent(code, instanceId) {
    if (!this.multiInstanceComponents.has(code)) {
      return;
    }
    
    const instanceMap = this.multiInstanceComponents.get(code);
    if (instanceMap.has(instanceId)) {
      instanceMap.delete(instanceId);
      console.log(`[GlobalAdManager] 多实例组件注销成功: ${code}@${instanceId}，剩余实例数: ${instanceMap.size}`);
      
      // 如果该 code 下没有实例了，清理空的 Map
      if (instanceMap.size === 0) {
        this.multiInstanceComponents.delete(code);
        console.log(`[GlobalAdManager] code ${code} 下无剩余实例，已清理`);
      }
    }
  }

  /**
   * 获取原生模板广告组件（带有效性检查）
   * 现在所有组件都自动生成 instanceId，优先从多实例存储中查找
   * @param {String} code 广告代码
   * @param {Object} component 组件实例（可选，用于生成精确的键）
   * @returns {Object|null} 组件实例
   */
  getNativeAdComponent(code, component = null) {
    // 多实例模式：如果提供了 instanceId，从多实例存储中获取
    if (component && component.instanceId) {
      return this.getMultiInstanceComponent(code, component.instanceId);
    }

    // 优先从多实例存储中获取第一个有效的组件
    // 这是为了兼容新的自动 instanceId 机制
    if (this.multiInstanceComponents.has(code)) {
      const instanceMap = this.multiInstanceComponents.get(code);
      for (const [instanceId, comp] of instanceMap) {
        if (this.isValidComponent(comp)) {
          console.log(`[GlobalAdManager] 从多实例存储中获取组件: ${code}@${instanceId}`);
          return comp;
        }
      }
    }

    // 回退到单实例模式（兼容旧逻辑）
    let targetComponent = null;
    let targetKey = null;

    if (component) {
      // 如果提供了组件实例，生成精确的键
      const componentKey = this.generateComponentKey(code, component);
      targetComponent = this.nativeAdComponents.get(componentKey);
      targetKey = componentKey;
    } else {
      // 兼容模式：查找匹配的组件
      // 优先查找当前页面的组件
      try {
        const pages = getCurrentPages();
        if (pages && pages.length > 0) {
          const currentPage = pages[pages.length - 1];
          const currentPageKey = `${currentPage.route || ''}@${code}`;
          if (this.nativeAdComponents.has(currentPageKey)) {
            targetComponent = this.nativeAdComponents.get(currentPageKey);
            targetKey = currentPageKey;
          }
        }
      } catch (error) {
        console.warn('[GlobalAdManager] 获取当前页面信息时出错:', error);
      }

      // 如果没找到当前页面的组件，不要查找其他页面的组件
      if (!targetComponent) {
        console.warn(`[GlobalAdManager] 未找到组件: ${code}`);
        console.log('[GlobalAdManager] 当前已注册的组件 (单实例):', Array.from(this.nativeAdComponents.keys()));
        console.log('[GlobalAdManager] 当前已注册的组件 (多实例):', Array.from(this.multiInstanceComponents.keys()));
      }
    }

    if (!targetComponent) return null;
    
    // 检查组件有效性
    if (!this.isValidComponent(targetComponent)) {
      console.log(`[GlobalAdManager] 检测到无效组件 ${targetKey}，自动清理`);
      this.nativeAdComponents.delete(targetKey);
      return null;
    }
    
    return targetComponent;
  }

  /**
   * 多实例模式：获取指定实例的组件
   * @param {String} code 广告代码
   * @param {String} instanceId 实例ID
   * @returns {Object|null} 组件实例
   */
  getMultiInstanceComponent(code, instanceId) {
    if (!this.multiInstanceComponents.has(code)) {
      return null;
    }
    
    const instanceMap = this.multiInstanceComponents.get(code);
    const component = instanceMap.get(instanceId);
    
    if (!component) return null;
    
    // 检查组件有效性
    if (!this.isValidComponent(component)) {
      console.log(`[GlobalAdManager] 检测到无效的多实例组件 ${code}@${instanceId}，自动清理`);
      instanceMap.delete(instanceId);
      return null;
    }
    
    return component;
  }

  /**
   * 多实例模式：获取某个 code 下所有有效的组件实例
   * @param {String} code 广告代码
   * @returns {Array<Object>} 组件实例数组
   */
  getAllMultiInstanceComponents(code) {
    if (!this.multiInstanceComponents.has(code)) {
      return [];
    }
    
    const instanceMap = this.multiInstanceComponents.get(code);
    const validComponents = [];
    const invalidInstanceIds = [];
    
    instanceMap.forEach((component, instanceId) => {
      if (this.isValidComponent(component)) {
        validComponents.push(component);
      } else {
        invalidInstanceIds.push(instanceId);
      }
    });
    
    // 清理无效的实例
    invalidInstanceIds.forEach(instanceId => {
      instanceMap.delete(instanceId);
      console.log(`[GlobalAdManager] 清理无效的多实例组件: ${code}@${instanceId}`);
    });
    
    return validComponents;
  }

  /**
   * 多实例模式：获取某个 code 下的实例数量
   * @param {String} code 广告代码
   * @returns {Number} 实例数量
   */
  getMultiInstanceCount(code) {
    if (!this.multiInstanceComponents.has(code)) {
      return 0;
    }
    return this.multiInstanceComponents.get(code).size;
  }

  /**
   * 检查是否有可用的组件系统
   * @returns {Boolean}
   */
  hasComponentSystem() {
    this.cleanupInvalidComponents();
    // 检查单实例或多实例模式是否有组件
    const hasSingleInstance = this.nativeAdComponents.size > 0;
    const hasMultiInstance = this.multiInstanceComponents.size > 0;
    return this.isInitialized && this.ad && (hasSingleInstance || hasMultiInstance);
  }

  /**
   * 通过广告代码显示原生模板广告
   * 多实例模式下，会初始化所有尚未初始化的组件
   * @param {String} adCode 广告代码
   * @param {Object} callbacks 回调函数
   * @param {String} instanceId 可选，多实例模式下指定实例ID
   */
  async showNativeAdByCode(adCode, callbacks, instanceId = null) {
    if (!this.hasComponentSystem()) {
      throw new Error('组件系统未就绪');
    }

    // 多实例模式：通过 instanceId 获取特定实例
    if (instanceId) {
      const component = this.getMultiInstanceComponent(adCode, instanceId);
      if (!component) {
        const errorMsg = `未找到多实例广告组件: ${adCode}@${instanceId}`;
        if (callbacks && callbacks.onError) {
          callbacks.onError(new Error(errorMsg));
        }
        throw new Error(errorMsg);
      }
      return await this._initAndShowComponent(component, adCode, callbacks);
    }
    
    // 检查是否有多实例组件
    if (this.multiInstanceComponents.has(adCode)) {
      // 多实例模式：初始化所有尚未初始化的组件
      return await this._showAllUninitializedComponents(adCode, callbacks);
    }
    
    // 单实例模式（原有逻辑）
    let component = this.getNativeAdComponent(adCode);
    
    // 如果没有找到，等待组件注册
    if (!component) {
      component = await this.waitForComponent(adCode);
    }
    
    // 如果还是没找到，尝试使用当前页面的默认组件
    if (!component && adCode !== 'default_native') {
      console.log(`[GlobalAdManager] 尝试使用当前页面的默认组件 default_native`);
      try {
        const pages = getCurrentPages();
        if (pages && pages.length > 0) {
          const currentPage = pages[pages.length - 1];
          const defaultComponentKey = `${currentPage.route || ''}@default_native`;
          component = this.nativeAdComponents.get(defaultComponentKey);
          if (component && this.isValidComponent(component)) {
            console.log(`[GlobalAdManager] 找到当前页面的默认组件: ${defaultComponentKey}`);
          } else {
            component = null;
          }
        }
      } catch (error) {
        console.warn('[GlobalAdManager] 查找默认组件时出错:', error);
      }
    }

    if (!component) {
      const errorMsg = `未找到广告组件: ${adCode}`;
      if (callbacks && callbacks.onError) {
        callbacks.onError(new Error(errorMsg));
      }
      throw new Error(errorMsg);
    }

    return await this._initAndShowComponent(component, adCode, callbacks);
  }

  /**
   * 多实例模式：初始化所有尚未初始化的组件
   * @param {String} adCode 广告代码
   * @param {Object} callbacks 回调函数
   */
  async _showAllUninitializedComponents(adCode, callbacks) {
    const instanceMap = this.multiInstanceComponents.get(adCode);
    if (!instanceMap || instanceMap.size === 0) {
      console.warn(`[GlobalAdManager] 未找到任何多实例组件: ${adCode}`);
      return [];
    }
    
    // 收集所有尚未初始化的有效组件
    const uninitializedComponents = [];
    const invalidInstanceIds = [];
    
    instanceMap.forEach((component, instanceId) => {
      if (!this.isValidComponent(component)) {
        invalidInstanceIds.push(instanceId);
        return;
      }
      
      // 检查组件是否已初始化
      if (!component.isInitialized && !component.isInitializing) {
        uninitializedComponents.push({ component, instanceId });
      }
    });
    
    // 清理无效实例
    invalidInstanceIds.forEach(id => instanceMap.delete(id));
    
    if (uninitializedComponents.length === 0) {
      console.log(`[GlobalAdManager] ${adCode} 没有需要初始化的新组件`);
      return [];
    }
    
    console.log(`[GlobalAdManager] 开始初始化 ${uninitializedComponents.length} 个新组件: ${adCode}`);
    
    // 初始化所有未初始化的组件
    const results = [];
    for (const { component, instanceId } of uninitializedComponents) {
      try {
        console.log(`[GlobalAdManager] 初始化组件: ${adCode}@${instanceId}`);
        await this._initAndShowComponent(component, adCode, callbacks);
        results.push(component);
      } catch (error) {
        console.warn(`[GlobalAdManager] 组件 ${adCode}@${instanceId} 初始化失败:`, error);
      }
    }
    
    console.log(`[GlobalAdManager] 多实例初始化完成，成功: ${results.length}/${uninitializedComponents.length}`);
    return results;
  }

  /**
   * 初始化并显示单个组件
   * @param {Object} component 组件实例
   * @param {String} adCode 广告代码
   * @param {Object} callbacks 回调函数
   */
  async _initAndShowComponent(component, adCode, callbacks) {
    // 检查组件有效性
    if (!this.isValidComponent(component)) {
      const error = new Error(`组件 ${adCode} 已失效`);
      if (callbacks && callbacks.onError) {
        callbacks.onError(error);
      }
      throw error;
    }

    // 初始化组件
    if (typeof component.initAd === 'function') {
      await component.initAd(adCode);
    }

    // 获取最终回调
    let finalCallbacks = callbacks;
    
    // 检查是否有预注册的事件处理器
    if (this.ad && typeof this.ad.getPreRegisteredCallbacks === 'function') {
      const preRegisteredCallbacks = this.ad.getPreRegisteredCallbacks(adCode);
      
      if (preRegisteredCallbacks) {
        finalCallbacks = {
          onShow: preRegisteredCallbacks.onShow || (callbacks && callbacks.onShow),
          onError: preRegisteredCallbacks.onError || (callbacks && callbacks.onError),
          onClose: preRegisteredCallbacks.onClose || (callbacks && callbacks.onClose),
          onHide: preRegisteredCallbacks.onHide || (callbacks && callbacks.onHide)
        };
      }
    }

    // 绑定事件
    if (finalCallbacks) {
      if (typeof component.$off === 'function') {
        component.$off('error');
        component.$off('show');
        component.$off('close');
        component.$off('hide');
      }

      if (finalCallbacks.onError && typeof component.$once === 'function') {
        component.$once('error', finalCallbacks.onError);
      }
      if (finalCallbacks.onShow && typeof component.$once === 'function') {
        component.$once('show', finalCallbacks.onShow);
      }
      if (finalCallbacks.onClose && typeof component.$once === 'function') {
        component.$once('close', finalCallbacks.onClose);
      }
      if (finalCallbacks.onHide && typeof component.$once === 'function') {
        component.$once('hide', finalCallbacks.onHide);
      }
    }

    // 等待并显示广告
    await new Promise(resolve => setTimeout(resolve, 50));
    
    if (typeof component.showAdMethod === 'function') {
      component.showAdMethod();
    }

    return component;
  }

  /**
   * 多实例模式：显示所有使用指定 code 的广告实例
   * 用于信息流广告场景，一次性初始化并显示所有实例
   * @param {String} adCode 广告代码
   * @param {Object} callbacks 回调函数
   * @returns {Array<Object>} 所有初始化成功的组件实例
   */
  async showAllMultiInstanceAds(adCode, callbacks) {
    const components = this.getAllMultiInstanceComponents(adCode);
    
    if (components.length === 0) {
      console.warn(`[GlobalAdManager] 未找到任何多实例组件: ${adCode}`);
      return [];
    }
    
    console.log(`[GlobalAdManager] 开始初始化 ${components.length} 个多实例广告: ${adCode}`);
    
    const results = [];
    for (const component of components) {
      try {
        // 初始化组件
        if (typeof component.initAd === 'function') {
          await component.initAd(adCode);
        }
        
        // 绑定回调
        if (callbacks) {
          if (callbacks.onError && typeof component.$once === 'function') {
            component.$once('error', callbacks.onError);
          }
          if (callbacks.onShow && typeof component.$once === 'function') {
            component.$once('show', callbacks.onShow);
          }
          if (callbacks.onClose && typeof component.$once === 'function') {
            component.$once('close', callbacks.onClose);
          }
        }
        
        // 显示广告
        if (typeof component.showAdMethod === 'function') {
          component.showAdMethod();
        }
        
        results.push(component);
      } catch (error) {
        console.warn(`[GlobalAdManager] 多实例广告初始化失败:`, error);
      }
    }
    
    console.log(`[GlobalAdManager] 多实例广告初始化完成，成功: ${results.length}/${components.length}`);
    return results;
  }
}

// 创建全局单例
const globalAdManager = new GlobalAdManager();

// 在不同环境中暴露全局管理器
if (typeof global !== 'undefined') {
  global.globalAdManager = globalAdManager;
}
if (typeof window !== 'undefined') {
  window.globalAdManager = globalAdManager;
}
if (typeof uni !== 'undefined') {
  uni.globalAdManager = globalAdManager;
}

export default globalAdManager; 