/**
 * FBIAD 舒适化模块
 * 提供广告相关的舒适化功能
 */

// 静态导入平台特定模块
import fbiadCFtt from './fbiadCFtt.js';
import fbiadCFwx from './fbiadCFwx.js';

// 微信环境（兼容无 getWindowInfo 的基础库）
const isWX = () =>
	typeof wx !== "undefined" &&
	typeof tt === "undefined" &&
	!!(
		wx.getWindowInfo ||
		wx.getSystemInfoSync ||
		wx.getSystemInfo ||
		wx.login ||
		wx.createRewardedVideoAd
	) && "wx";
const isTT = () => typeof tt !== "undefined" && tt.getSystemInfo && "tt";

const ENV = isTT() || isWX();

// 根据环境动态引入模块，避免跨平台后加载模块报错
let __comfortable__ = async () => {
	if (isTT()) {
		return fbiadCFtt;
	} else if (isWX()) {
		return fbiadCFwx;
	}

	console.warn('⚠️ [fbiadComfortable] 当前平台不在直接支持列表中，使用默认兼容模式');
	return {
		InterstitialAdLoader: null,
		RewardedVideoAdLoader: null,
		NativeAdLoader: null,
		CustomAdLoader: null,
		GridAdLoader: null,
	};
};

const fbiadComfortable = {
	// 初始化方法
	init: function (options) {
		console.log('✅ [FBIAD] Comfortable初始化完成');
		this.options = options || {};
		return this;
	},

	// 获取平台配置数据
	getConfigData: function () {
		if (isTT()) {
			return { platform: "DY" };
		} else if (isWX()) {
			return { platform: "WX" };
		}

		console.warn("⚠️ [fbiadComfortable] 未匹配到任何平台分支，返回空对象");
		return {};
	},


	// 兼容调用，保持函数签名一致，全部使用异步函数
	InterstitialAdLoaderAsync: async (params) => {
		try {
			let cf = await __comfortable__();
			let InterstitialAdLoaderInfo = cf.InterstitialAdLoader;
			return InterstitialAdLoaderInfo;
		} catch (error) {
			console.warn('⚠️ [fbiadComfortable] InterstitialAdLoader获取失败，使用默认实现:', error.message);
			return null;
		}
	},

	RewardedVideoAdLoaderAsync: async () => {
		try {
			let cf = await __comfortable__();
			let RewardedVideoAdLoaderInfo = cf.RewardedVideoAdLoader;
			return RewardedVideoAdLoaderInfo;
		} catch (error) {
			console.warn('⚠️ [fbiadComfortable] RewardedVideoAdLoader获取失败，使用默认实现:', error.message);
			return null;
		}
	},

	NativeAdLoaderAsync: async () => {
		try {
			let cf = await __comfortable__();
			let NativeAdLoaderInfo = cf.NativeAdLoader;
			return NativeAdLoaderInfo;
		} catch (error) {
			console.warn('⚠️ [fbiadComfortable] NativeAdLoader获取失败，使用默认实现:', error.message);
			return null;
		}
	},

	CustomAdLoaderAsync: async () => {
		try {
			let cf = await __comfortable__();
			return cf.CustomAdLoader || null;
		} catch (error) {
			console.warn('⚠️ [fbiadComfortable] CustomAdLoader获取失败:', error.message);
			return null;
		}
	},

	GridAdLoaderAsync: async () => {
		try {
			let cf = await __comfortable__();
			return cf.GridAdLoader || null;
		} catch (error) {
			console.warn('⚠️ [fbiadComfortable] GridAdLoader获取失败:', error.message);
			return null;
		}
	},


	// 创建广告实例
	createAd: function (type, config) {
		return {
			show: () => { }, // 显示广告
			hide: () => { }, // 隐藏广告
			destroy: () => { } // 销毁广告
		};
	},

	// 显示奖励视频广告
	showRewardedVideo: function (config) {
		return Promise.resolve({ success: true });
	},

	// 显示插屏广告
	showInterstitial: function (config) {
		return Promise.resolve({ success: true });
	},


	// 显示原生广告
	showNative: function (config) {
		return Promise.resolve({ success: true });
	}
};

export default fbiadComfortable;