// 静态导入平台特定模块
import fbiCoreCFtt from './fbiCoreCFtt.js';
import fbiCoreCFwx from './fbiCoreCFwx.js';

// 微信环境（兼容无 getWindowInfo 的基础库）
const isWX = () =>
	typeof wx !== 'undefined' &&
	typeof tt === 'undefined' &&
	!!(
		wx.getWindowInfo ||
		wx.getSystemInfoSync ||
		wx.getSystemInfo ||
		wx.login ||
		wx.createRewardedVideoAd
	) && 'wx'
const isTT = () => typeof tt !== 'undefined' && tt.getSystemInfo && 'tt'

// 默认的兼容实现，用于不支持的平台
const createDefaultCompatible = () => {
	console.warn('⚠️ [FBI SDK] 当前平台未直接支持，使用默认兼容模式');

	// 定义原始API配置（不替换域名）
	const originalDefaultInterfaceApi = {
		api: {
			DOMAIN: 'https://md.898mk.cn/',
			TRACK_API: 'mini/track/captures'
		},
		loginApi: {
			DOMAIN: "https://apile.898mk.cn/",
			USER_LOGIN: "sp/mini/basic/user/login",
			AD_CONFIG: "sp/mini/basic/sysConf/info",
			START_ACCOUNT: "sp/mini/basic/ad/start/account",
			SCRRE_USERS: "sp/mini/basic/deliveryConf/screenRecordingUsers"
		}
	};

	return {

		deviceAsync: async () => {
			console.log('🔧 [默认兼容] 使用默认设备信息');
			return {
				'$model': 'Unknown',
				'$manufacturer': 'Unknown',
				'$brand': 'Unknown',
				'$screen_width': 375,
				'$screen_height': 667,
				'$os': 'Unknown-SDK',
				'$os_version': 'Unknown-1.0.0',
				'$network_type': 'unknown',
				'$language': 'zh_CN'
			};
		},

		requestAsync: async (option) => {
			console.log('🔧 [默认兼容] 网络请求:', option.url);

			// 尝试使用平台原生API
			if (typeof wx !== 'undefined' && wx.request) {
				console.log('🌐 [默认兼容] 使用wx.request');
				return new Promise((resolve, reject) => {
					wx.request({
						...option,
						success: (res) => resolve(res.data || res),
						fail: reject
					});
				});
			} else if (typeof tt !== 'undefined' && tt.request) {
				console.log('🌐 [默认兼容] 使用tt.request');
				return new Promise((resolve, reject) => {
					tt.request({
						...option,
						success: (res) => resolve(res.data || res),
						fail: reject
					});
				});
			} else if (typeof window !== 'undefined' && window.fetch) {
				console.log('🌐 [默认兼容] 使用fetch');
				return window.fetch(option.url, {
					method: option.method || 'GET',
					headers: option.header || option.headers || {},
					body: option.data ? JSON.stringify(option.data) : undefined
				}).then(response => response.json());
			}

			// 最后才使用模拟响应
			console.warn('⚠️ [默认兼容] 无可用网络API，使用模拟响应');
			return new Promise((resolve) => {
				setTimeout(() => {
					resolve({
						success: true,
						message: '默认兼容模式模拟响应',
						data: {},
						model: {}
					});
				}, 100);
			});
		},

		getStorageAsync: async (key) => {
			console.log('🔧 [默认兼容] 模拟获取存储:', key);
			// 返回空值，避免依赖本地存储
			return null;
		},

		setStorageAsync: async (key, value) => {
			console.log('🔧 [默认兼容] 模拟设置存储:', key, '=', value);
			// 什么都不做，避免存储依赖
			return true;
		},

		loginAsync: async (app_id, env, loginParams) => {
			console.log('🔧 [默认兼容] 模拟登录流程');

			// 返回一个模拟的登录信息
			return {
				accessToken: 'default_token_' + Date.now(),
				userId: 'default_userId_' + Math.random().toString(36).substr(2, 16),
				appId: app_id,
				createdDt: new Date(),
				isLogin: 0
			};
		}
	};
};

//根据环境动态引入模块，避免跨平台后加载模块报错
let __comfortable__ = async () => {
	if (isTT()) {
		return fbiCoreCFtt
	} else if (isWX()) {
		return fbiCoreCFwx
	}

	// 不再抛出错误，而是返回默认兼容实现
	console.warn('⚠️ [FBI SDK] 当前平台不在直接支持列表中，启用默认兼容模式');
	return createDefaultCompatible();
}

/**
 * 兼容调用，保持函数签名一致，全部使用异步函数
 */
let comfortable = {
	/**
	 * 获取sdk接口配置
	 */
	getInterfaceApi: async () => {
		let cf = await __comfortable__()
		let interfaceApiInfo = cf.getInterfaceApi();
		return interfaceApiInfo
	},
	/**
	 * 获取设备信息
	 */
	deviceAsync: async () => {
		let cf = await __comfortable__()
		let deviceInfo = await cf.deviceAsync()

		return {
			...deviceInfo
		}
	},
	/**
	 * 网络请求
	 */
	requestAsync: async (option) => {
		let cf = await __comfortable__()
		return cf.requestAsync(option)
	},
	/**
	 * 本地存储 获取
	 */
	getStorageAsync: async (key) => {
		let cf = await __comfortable__()
		return await cf.getStorageAsync(key)
	},
	/**
	 * 本地存储 保存
	 */
	setStorageAsync: async (key, value) => {
		let cf = await __comfortable__()
		return await cf.setStorageAsync(key, value)
	},
	/**
	 * 登录
	 */
	loginAsync: async (app_id, env, loginParams) => {
		let cf = await __comfortable__()

		return await cf.loginAsync(app_id, env, loginParams)
	},
	/**
	 * 获取平台标识
	 * @returns {Promise<string>} wechat | douyin
	 */
	getPlatform: async () => {
		let cf = await __comfortable__()
		return cf.PLATFORM || 'WX'
	},
	
	// 上报用户录屏-截屏
	riskControlListenAsync: async (env, loginParams) => {
		let cf = await __comfortable__()
		if (typeof cf.riskControlListenAsync !== "function") {
			return Promise.resolve("当前平台不支持风控监听");
		}
		return await cf.riskControlListenAsync(env, loginParams)
	}
}

export default comfortable