	/**
	 * @description
	 * 获取插屏广告对象
	 * @param {Object} option 插屏广告选项
	 * @param {Object} callbacks 回调函数
	 */
	async showInterstitial(option, callbacks){
		let key = option.adUnitId;
		
		// 检查冷却期，防止过于频繁的重试
		const now = Date.now();
		const lastShowTime = lastShowTimes.get(key) || 0;
		const cooldownPeriod = 2000; // 2秒冷却期
		
		if (now - lastShowTime < cooldownPeriod) {
			console.warn(`⏰ [AdLoader.showInterstitial] 广告位 "${key}" 正在冷却期，跳过此次调用`);
			if (callbacks && callbacks.onError) {
				callbacks.onError({ errMsg: '广告调用过于频繁，请稍后再试', errCode: -1 });
			}
			return;
		}
		
		// 记录本次调用时间
		lastShowTimes.set(key, now);
		
		// 每次都销毁之前的 InterstitialAdLoader 实例（如果存在）
		if(loaders.has(key)){
			try {
				const existingLoader = loaders.get(key);
				if (existingLoader && typeof existingLoader.destroy === 'function') {
					await existingLoader.destroy();
				}
				loaders.delete(key);
			} catch (error) {
				console.warn(`⚠️ [AdLoader.showInterstitial] 销毁现有实例时出错:`, error);
			}
		}
		
		// 每次都创建新的 InterstitialAdLoader 实例
		const loader = new InterstitialAdLoader({ adUnitId: option.adUnitId, autoOffTime: option.autoOffTime });
		loaders.set(key, loader);
		
		// 确保 loader 初始化完成
		try {
			if (loader.ensureInitialized && typeof loader.ensureInitialized === 'function') {
				await loader.ensureInitialized();
			}
		} catch (error) {
			console.error(`❌ [AdLoader.showInterstitial] loader 初始化失败:`, error);
			if (callbacks && callbacks.onError) {
				callbacks.onError(error);
			}
			return;
		}
		
		// 验证 loader 是否有效
		if (!loader) {
			console.error('❌ [AdLoader.showInterstitial] loader 为空，无法创建Ad实例');
			if (callbacks && callbacks.onError) {
				callbacks.onError(new Error('插屏广告对象初始化失败'));
			}
			return;
		}
		
		// 简化回调处理，直接传递原始错误信息
		const enhancedCallbacks = {
			...callbacks,
			onError: function(error) {
				if (callbacks && callbacks.onError) {
					callbacks.onError(error);
				}
			}
		};
		
		let ad;
		try {
			ad = new Ad(loader, enhancedCallbacks);
		} catch (error) {
			console.error('❌ [AdLoader.showInterstitial] 创建Ad实例失败:', error);
			if (enhancedCallbacks.onError) {
				enhancedCallbacks.onError(error);
			}
			return;
		}
		
		try {
			ad.show();
		} catch (error) {
			console.error(`❌ [AdLoader.showInterstitial] show() 调用失败:`, error);
			if (enhancedCallbacks.onError) {
				enhancedCallbacks.onError(error);
			}
		}
	}

	/**
	 * 小游戏原生模板广告 wx.createCustomAd（type=6）
	 * 按 code 缓存实例；关闭后 interval 秒重新拉起（关闭后平台实例已销毁，必须重建）
	 */
	async showCustom(option, callbacks) {
		const key = customAdCacheKey(option);
		if (!key) {
			if (callbacks?.onError) callbacks.onError(new Error("CustomAd 缺少 code"));
			return;
		}
		if (!option.adUnitId) {
			if (callbacks?.onError) callbacks.onError(new Error("CustomAd 缺少 adUnitId"));
			return;
		}

		// 新一次展示前清掉旧的重拉定时器
		clearReshowTimer(customReshowTimers, key);

		const wrappedCallbacks = wrapCloseReshowCallbacks(
			callbacks,
			() => disposeCustomCache(key),
			() =>
				scheduleIntervalReshow(customReshowTimers, key, option.interval, () =>
					this.showCustom(option, callbacks),
				),
		);

		try {
			let loader = customLoaders.get(key);
			// 关闭后平台已销毁，或参数变更：必须重建
			if (loader && (!loader.isUsable?.() || !loader.isSame?.(option))) {
				try { await loader.destroy(); } catch (e) {}
				customLoaders.delete(key);
				loader = null;
			}
			if (!loader) {
				loader = new CustomAdLoader({
					adUnitId: option.adUnitId,
					adIntervals: option.adIntervals,
					style: option.style,
				});
				customLoaders.set(key, loader);
				await loader.ensureInitialized();
			}

			const prev = customAdWrappers.get(key);
			if (prev && !prev.isDestroy) {
				prev.adLoader = null;
				try { prev.destroy(); } catch (e) {}
			}

			const ad = new NativeAd(loader, wrappedCallbacks);
			customAdWrappers.set(key, ad);
			await ad.show();
			return ad;
		} catch (error) {
			// NativeAd.show reject 可能是数组 [err]
			const err = Array.isArray(error) ? error[0] : error;
			const msg = String(err?.errMsg || err?.message || error || "");
			if (msg.includes("destroyed") || msg.includes("已销毁")) {
				console.warn("⚠️ [AdLoader.showCustom] 检测到已销毁实例，重建后重试");
				await disposeCustomCache(key);
				try {
					const loader = new CustomAdLoader({
						adUnitId: option.adUnitId,
						adIntervals: option.adIntervals,
						style: option.style,
					});
					customLoaders.set(key, loader);
					await loader.ensureInitialized();
					const ad = new NativeAd(loader, wrappedCallbacks);
					customAdWrappers.set(key, ad);
					await ad.show();
					return ad;
				} catch (retryError) {
					const retryErr = Array.isArray(retryError) ? retryError[0] : retryError;
					console.error("❌ [AdLoader.showCustom] 重建后仍失败:", retryErr);
					if (callbacks?.onError) callbacks.onError(retryErr);
					return;
				}
			}
			console.error("❌ [AdLoader.showCustom] 失败:", err);
			if (callbacks?.onError) callbacks.onError(err);
		}
	}

	async hideCustom(option) {
		const key = customAdCacheKey(option);
		// 主动 hide 取消 interval 重拉
		clearReshowTimer(customReshowTimers, key);
		const wrapper = customAdWrappers.get(key);
		if (wrapper && typeof wrapper.hide === "function") {
			return wrapper.hide();
		}
		const loader = customLoaders.get(key);
		if (loader) return loader.hide();
	}

