import http from '../fbiCoreHttp.js'
import uniCompatible from '../../../utils/utilsComfortable/uniCompatible.js'
import utilsComfortable from '../../../utils/utilsComfortable/utilsCFIndex.js'

// 平台标识
const PLATFORM = "DY";

const api = {
	DOMAIN: 'https://md.898mk.cn/',
	// DOMAIN: "https://test.ipandata.com/",
	TRACK_API: 'mini/track/captures',
}

const loginApi = {
	DOMAIN: "https://apile.898mk.cn/",
	// DOMAIN: "https://test.ipandata.com/",
	USER_LOGIN: "sp/mini/basic/user/login",
	AD_CONFIG: "sp/mini/basic/sysConf/info",
	START_ACCOUNT: "sp/mini/basic/ad/start/account",
	SCRRE_USERS: "sp/mini/basic/deliveryConf/screenRecordingUsers"
}

function normalizeHttpsDomain(url) {
	if (!url || typeof url !== "string") return "";
	let domain = url.trim();
	if (!domain) return "";
	if (!/^https?:\/\//i.test(domain)) {
		domain = `https://${domain}`;
	}
	if (!domain.endsWith("/")) {
		domain += "/";
	}
	return domain;
}

function getRuntimeHttpsConfig() {
	try {
		if (typeof utilsComfortable.getExtConfigSync === "function") {
			return utilsComfortable.getExtConfigSync() || {};
		}
	} catch (e) {}
	return {};
}

// 动态获取接口API配置：
// readyAsync(config) 或 getExtConfigSync 传入 requestHTTPS / trackHTTPS 时覆盖域名
function getInterfaceApi() {
	const config = getRuntimeHttpsConfig();
	// trackHTTPS → api.DOMAIN（第 9 行，默认 md.*，埋点）
	// requestHTTPS → loginApi.DOMAIN（第 15 行，默认 apile.*，登录/配置等业务请求）
	const trackDomain = normalizeHttpsDomain(config.trackHTTPS);
	const requestDomain = normalizeHttpsDomain(config.requestHTTPS);

	if (trackDomain) {
		api.DOMAIN = trackDomain;
	}
	if (requestDomain) {
		loginApi.DOMAIN = requestDomain;
	}

	const nextApi = { ...api };
	const nextLoginApi = { ...loginApi };

	if (trackDomain || requestDomain) {
		console.log("🔍 [抖音平台] 使用 ext 配置覆盖域名", {
			trackHTTPS: nextApi.DOMAIN,
			requestHTTPS: nextLoginApi.DOMAIN,
		});
	} else {
		console.log("🔍 [抖音平台] 动态获取接口API配置");
	}

	return {
		api: nextApi,
		loginApi: nextLoginApi,
	};
}

function formatSystem(e) {
	var t = e.toLowerCase();
	return "ios" === t ? "iOS" : "android" === t ? "Android" : e;
}

const deviceAsync = (distinct_id, app_id) => {
	return new Promise((resolve, reject) => {
		tt.getSystemInfo({
			success: (res) => {
				try {

					const e = {
						//设备型号formatSystem
						'$model': res.model,
						//设备制造商
						'$manufacturer': res.brand ? res.brand : '',
						//设备品牌
						'$brand': res.brand ? res.brand.toUpperCase() : '',
						'$screen_width': res.screenWidth,
						'$screen_height': res.screenHeight,
						//操作系统类型-宿主类型：Android
						'$os': `${formatSystem(res.platform)}`,
						//操作系统版本-宿主版本
						'$os_version': `${res.system}-${res.version}`,
						'$network_type': res.networkType,
						'language': res.language
					};
					resolve(e)

				} catch (error) {
					reject(error)
				}
			},
			fail: (error) => {
				reject(error)
			}
		})
	})
}


const requestAsync = (option) => {
	return new Promise((resolve, reject) => {
		tt.request({
			...option,
			success: function(res) {
				// 修复：确保返回有效的响应数据
				let responseData = res.data;
				if (responseData.status != 0) {
					let serverError = new Error(`服务器错误: HTTP ${res.statusCode}`);
					let stack = JSON.stringify(option);
					serverError.name = 'ServerError';
					serverError.statusCode = res.statusCode;
					serverError.stack = stack;
					serverError.message = responseData.error || responseData.msg;
					serverError.headers = res.header;

					reject(serverError);
					return;
				}
				resolve(responseData);
			},
			fail: function(error) {
				console.error("网络请求失败:", error);
				reject(error)
			}
		})
	})
}

const getStorageAsync = async (key) => {
	return tt.getStorageSync(key)
}

const setStorageAsync = async (key, value) => {
	tt.setStorageSync(key, value)
}

// 登录【抖音端】
const loginAsync = async (app_id, env, loginParams) => {
	return new Promise((resolve, reject) => {
		tt.login({
			success: async resLogin => {
				try {
					let {
						oaId,
						idfa
					} = loginParams;
					let {
						code
					} = resLogin;
					let deviceId = oaId || idfa || '';
					
					

					let data = {
						appId: app_id,
						loginAccount: code,
						loginType: PLATFORM,
						deviceId
					}

					let result = await http.enviroment(env).userLoginAsync(data)
					console.log("userLoginAsync tt --->", result)
					let model = result.data
					//明确返回信息
					let dataModel = {
						accessToken: model.accessToken,
						appId: model.appId,
						createdDt: model.createdDt,
						expireAt: model.expireAt,
						userId: model.userId,
						// 兼容可能存在的额外字段
						openId: model.openid || '',
						unionId: model.unionid || '',
						session_key: model.session_key || ''
					}

					resolve(dataModel)

				} catch (error) {
					reject(error)
				}
			},
			fail: reject
		});
	})
}


// 防止 riskControlListen 被重复调用导致多次绑定监听
let riskControlListening = false;

/**
 * GET 上报只保留可序列化的扁平字段，避免嵌套对象变成 [object Object]
 */
const sanitizeRiskParams = (params = {}) => {
	const result = {};
	Object.keys(params).forEach((key) => {
		const value = params[key];
		if (value === undefined || value === null || value === "") {
			return;
		}
		const valueType = typeof value;
		if (valueType === "string" || valueType === "number" || valueType === "boolean") {
			result[key] = value;
			return;
		}
		// refererInfo 等已是字符串 JSON 时上面已覆盖；对象/数组直接跳过
	});
	return result;
};

const reportRiskControlEvent = async (env, params, eventType) => {
	try {
		await http.enviroment(env).riskControlListenAsync({
			...sanitizeRiskParams(params),
			eventType,
		});
		console.log(`[riskControlListen] ${eventType} 上报成功`);
	} catch (error) {
		console.warn(`[riskControlListen] ${eventType} 上报失败:`, error);
	}
};

const riskControlListenAsync = async (env, loginParams = {}) => {
	if (typeof tt === "undefined") {
		return Promise.resolve("非抖音平台，跳过风控监听");
	}

	if (riskControlListening) {
		return Promise.resolve("风控监听已注册，跳过重复绑定");
	}

	let ops = {};
	try {
		// 优先全局锁定的启动参数（含 Deploy.setLaunchOptions）
		ops = uniCompatible.getLaunchOptionsSync() || {};
	} catch (error) {
		console.warn("[riskControlListen] 获取启动参数失败:", error);
	}

	const resolved = uniCompatible.getResolvedLaunchOptions() || {};
	const params = sanitizeRiskParams({
		...loginParams,
		...resolved,
		scene: loginParams.scene != null && loginParams.scene !== ""
			? loginParams.scene
			: (resolved.scene != null && resolved.scene !== ""
				? resolved.scene
				: (ops.scene != null && ops.scene !== ""
					? ops.scene
					: (ops.query && ops.query.scene) || loginParams.scene)),
	});

	try {
		if (typeof tt.onUserCaptureScreen === "function") {
			tt.onUserCaptureScreen((res) => {
				console.log("当前截屏事件", res);
				reportRiskControlEvent(env, params, "captureScreen");
			});
		}

		if (typeof tt.onUserScreenRecord === "function") {
			tt.onUserScreenRecord((res) => {
				console.log("当前录屏事件", res);
				reportRiskControlEvent(env, params, "screenRecord");
			});
		}

		riskControlListening = true;
		return "风控监听注册成功";
	} catch (error) {
		throw new Error("风控监听失败: " + error);
	}
};

export default {
	deviceAsync,
	requestAsync,
	getStorageAsync,
	setStorageAsync,
	loginAsync,
	getInterfaceApi,
	riskControlListenAsync,
	PLATFORM,

}