import { adLoader } from "./AdLoader.js";
import comfortable from "./fbiadComfortable/fbiadCFIndex.js";
import globalAdManager from "./GlobalManager.js";
import deploy from "../utils/Deploy.js";
import {
  createTaskAdTracker,
} from "./adTrackHelpers.js";

/**
 * 小程序启动后30秒内才能展示插屏广告
 */
const AFTER_LAUNCH_TIME = 0;

/**
 * 距离上次展示广告0秒后，才能展示插屏广告，以上个广告关闭事件触发开始
 */
const NEXT_SHOW_TIME = 0;


/**
 * 最近一次广告展示时间 用于计算插屏show间隔
 */
let latest_show_time = +new Date();

/**
 * 是否已经展示过插屏广告
 */
let interstitial_has_showed = false;

/**
 * 当前是否正在展示广告
 */
let be_showing = false;

/** 小游戏：不互斥激励/插屏（be_showing）
 * - 小游戏包：BUILD_TARGET=minigame（打包时注入）
 * - 或 readyAsync(config) 后 Deploy.isMinigame()
 */
function isMinigameRuntime() {
  try {
    if (
      typeof process !== "undefined" &&
      process.env &&
      process.env.BUILD_TARGET === "minigame"
    ) {
      return true;
    }
    return !!(
      deploy &&
      typeof deploy.isMinigame === "function" &&
      deploy.isMinigame()
    );
  } catch (e) {
    return false;
  }
}

/**
 * 微信 CustomAd/Grid 失败时常 reject 为 [{errMsg, errCode, ...}]，需摊平后再读字段
 */
function normalizeAdError(error) {
  let err = error;
  if (Array.isArray(err)) {
    err = err[0];
  }
  // NativeAd.show catch 可能 throw 成 [rejectArg]
  if (Array.isArray(err)) {
    err = err[0];
  }
  if (err == null) {
    return { errCode: 0, errMsg: String(error ?? ""), message: "" };
  }
  if (typeof err === "string" || typeof err === "number") {
    return { errCode: 0, errMsg: String(err), message: String(err) };
  }
  if (err instanceof Error) {
    return {
      errCode: err.errCode ?? err.errorCode ?? 0,
      errMsg: err.errMsg || err.message || "",
      message: err.message || err.errMsg || "",
      errDetail: err.errDetail,
      errNo: err.errNo,
      errorCode: err.errorCode,
    };
  }
  return {
    errCode: err.errCode ?? err.errorCode ?? err.errNo ?? 0,
    errMsg: err.errMsg || err.message || err.errDetail || "",
    message: err.message || err.errMsg || "",
    errDetail: err.errDetail,
    errNo: err.errNo,
    errorCode: err.errorCode,
  };
}

function formatAdErrorReason(error) {
  const e = normalizeAdError(error);
  const left = e.errNo ?? e.errCode ?? "";
  const mid = e.errorCode ?? e.errCode ?? "";
  const msg = e.errMsg || e.errDetail || "";
  const message = e.message || e.errDetail || "";
  return `${left}|${mid}:${msg}|${message}`;
}

/**
 * 定时广告任务列表
 */
let timingAdTasks = [];
/**
 * 紧急广告任务列表
 */
let urgentADTask = [];
/**
 * 前台会话起点（appShow 重置，供 $MPHide 时长）
 */
let startTime = 0;
/**
 * 进小程序起点（只锁一次，供广告 triggerTiming；勿在切前后台重置）
 */
let adEnterTime = Date.now();
let adEnterTimeLocked = false;

function ensureAdEnterTime(now = Date.now()) {
  if (!adEnterTime || adEnterTime <= 0) {
    adEnterTime = now;
  }
  return adEnterTime;
}

function lockAdEnterTime(now = Date.now()) {
  if (!adEnterTimeLocked) {
    adEnterTime = now;
    adEnterTimeLocked = true;
  }
  return adEnterTime;
}


/**
 * 获取各家平台信息
 */
const getConfigData = () => {
  return comfortable.getConfigData();
};

/**
 * 定时检查弹广告
 */
let time = undefined;

let triggerTask = function () {
  // console.log("🔄 [triggerTask] 定时任务执行器启动");
  // console.log(`📊 [triggerTask] 当前任务队列: urgentADTask=${urgentADTask.length}, timingAdTasks=${timingAdTasks.length}`);
  // console.log(`🎮 [triggerTask] 全局状态: be_showing=${be_showing}, interstitial_has_showed=${interstitial_has_showed}`);

  // 🔧 修复：在每次触发时检查全局状态是否过期，防止卡死
  let now = +new Date();
  if (be_showing && now - latest_show_time > 120 * 1000) {
    // console.log("🔧 [triggerTask] 检测到be_showing状态超时2分钟，强制重置");
    be_showing = false;
  }

  //清除之前任务
  time && clearTimeout(time);

  //遍历任务执行
  let allTasks = [...urgentADTask, ...timingAdTasks];
  // console.log(`🔍 [triggerTask] 开始遍历 ${allTasks.length} 个任务`);

  for (let i = 0; i < allTasks.length; i++) {
    let task = allTasks[i];
    try {
      // console.log(`🎯 [triggerTask] 检查任务 ${i+1}: code="${task.code}", type="${task.type}"`);
      let executed = task.execute();
      // console.log(`📋 [triggerTask] 任务 ${i+1} 执行结果: ${executed ? '成功执行' : '跳过'}`);

      if (executed) {
        // console.log(`✅ [triggerTask] 任务 ${i+1} 成功执行，停止遍历其他任务`);
        break;
      }
    } catch (error) {
      // console.log(`❌ [triggerTask] 任务 ${i+1} 执行出错:`, error);
      // 忽略任务执行错误
    }
  }

  //重新定时 初始为10s
  let delay = NEXT_SHOW_TIME * 1000;
  // console.log("⏰ [triggerTask] 计算下次执行延迟...");

  // 检查是否有任务需要执行
  let allTasksForDelay = [...urgentADTask, ...timingAdTasks];
  if (allTasksForDelay.length === 0) {
    // console.log("🛑 [triggerTask] 没有任务需要执行，停止定时器");
    return; // 没有任务时直接返回，不设置定时器
  }

  for (let task of allTasksForDelay) {
    let v = task.getDelay();
    // console.log(`📅 [triggerTask] 任务 "${task.code}" 延迟: ${(v/1000).toFixed(1)}秒`);
    delay = Math.min(delay, v);
  }

  //必须大于0
  delay = Math.max(delay, 0);

  //如果广告正在展示 还原为60s，回调事件中会重置（小游戏不互斥，不拉长调度）
  if (be_showing && !isMinigameRuntime()) {
    // console.log("⚠️ [triggerTask] 有广告正在展示，延迟设为60秒");
    delay = Math.max(delay, NEXT_SHOW_TIME * 1000);
  }

  // console.log(`⏰ [triggerTask] 下次执行延迟: ${(delay/1000).toFixed(1)}秒`);
  time = setTimeout(triggerTask, delay);
  // console.log("✅ [triggerTask] 定时器已设置");
};

let pauseTask = function () {
  time && clearTimeout(time);
};

/**
 *  定时广告任务句柄
 */
class TaskHandler {
  constructor(fbisdk, type, option) {
    // console.log(`🎯 [TaskHandler] 构造函数开始 - type: "${type}", code: "${option.code}"`);

    this.fbisdk = fbisdk;
    this.type = type;
    this.option = option;
    this.code = option.code;
    this.params = option.params;
    this.oc = option.callbacks;
    this.times = 0;
    this.error_times = 0;
    this.all_error_times = 0;
    this.is_running = false;
    this.is_first = true;
    this.lastTimestamp = +new Date();
    this.ad_loading_time = 0;
    this.ad_show_time = 0;
    this.hasTriggeredShow = false; // 添加防重复触发标记，特别针对原生模板广告
    this.hasTriggeredClose = false; // $WatchVideo 防重

    const that = this;
    this._adTracker = createTaskAdTracker({
      code: this.code,
      handlerType: this.type,
      params: this.params,
      option: this.option,
      getStartTime: () => ensureAdEnterTime(),
      getPlatform: () => getConfigData().platform,
      trackAsync: (event, props) => {
        if (that.fbisdk && typeof that.fbisdk.trackAsync === "function") {
          that.fbisdk.trackAsync(event, props);
        }
      },
    });

    // console.log(`📅 [TaskHandler] 初始化时间戳: ${new Date(this.lastTimestamp).toLocaleTimeString()}`);
    // console.log(`🔧 [TaskHandler] 任务配置: delay=${option.delay}秒, interval=${option.interval}秒, times=${option.times}`);

    // console.log(`🔄 [TaskHandler] 准备读取历史次数...`);
    //从存储中读取之前的次数
    try {
      // console.log(`🔍 [TaskHandler] 调用 getTimesFromStorage()...`);
      const oldValue = this.getTimesFromStorage();
      // console.log(`📊 [TaskHandler] getTimesFromStorage() 返回:`, oldValue);
      this.today_times = oldValue.today_times;
      this.thisyear_times = oldValue.thisyear_times;
      // console.log(`✅ [TaskHandler] 历史次数设置完成: 今日=${this.today_times}, 今年=${this.thisyear_times}`);
    } catch (error) {
      // console.log(`❌ [TaskHandler] getTimesFromStorage() 出错:`, error);
      // 设置默认值
      this.today_times = 0;
      this.thisyear_times = 0;
      // console.log(`🔧 [TaskHandler] 使用默认历史次数: 今日=0, 今年=0`);
    }

    // console.log(`🔄 [TaskHandler] 准备构建回调函数...`);
    // console.log(`🔍 [TaskHandler] that 引用设置完成`);

    // console.log(`✅ [TaskHandler] 构造函数主体完成 - code: "${option.code}"`);

    // console.log(`🔄 [TaskHandler] 开始构建回调装饰器...`);
    //回调装饰 对状态进行控制
    //内部this指向原回调参数
    try {
      // console.log(`🔧 [TaskHandler] 构建 callbacks 对象...`);
      this.callbacks = {
        onLoad: function (...args) {
          try {
            that._adTracker && that._adTracker.onLoadSuccess();
            that.oc && that.oc.onLoad && that.oc.onLoad.call(that.oc);
          } catch (error) {
            // 忽略回调错误
          }
        },
        onShow: function (...args) {
          let shouldCallCallback = true;

          try {
            // 原生模板 / CustomAd / GridAd 防重复触发检查
            if (that.type === "native" || that.type === "custom" || that.type === "grid") {
              if (that.hasTriggeredShow) {
                shouldCallCallback = false;
                return;
              }
              that.hasTriggeredShow = true;
            }

            if (that.type == "interstitial") {
              interstitial_has_showed = true;
            }
            that.error_times = 0;
            that.is_first = false;
            that.ad_show_time = +new Date();

            //增加广告展示次数（业务限次用）
            that.increaseTimesToStorage.call(that);

            // 埋点：$AdShow success（含补齐 request/show loading）
            that._adTracker && that._adTracker.onShowSuccess();
          } catch (error) {
            // 忽略埋点错误
          } finally {
            if (shouldCallCallback) {
              try {
                that.oc && that.oc.onShow && that.oc.onShow.call(that.oc);
              } catch (error) {
                // 忽略回调错误
              }
            }
          }
        },
        onError: function (error) {
          try {
            be_showing = false;
            that.is_running = false;

            if (that.type === "native" || that.type === "custom" || that.type === "grid") {
              that.hasTriggeredShow = false;
            }

            that.error_times += 1;
            that.all_error_times += 1;

            let current = +new Date();
            that.increaseTimesToStorage.call(that);

            if (that.error_times >= 5) {
              that.error_times = 0;
              that.lastTimestamp = current;
            } else {
              that.lastTimestamp =
                current - that.option.interval * 1000 + 5 * 1000;

              if (that.is_first) {
                that.lastTimestamp =
                  current - that.option.delay * 1000 + 5 * 1000;
              }
            }

            triggerTask();

            // 埋点：按阶段收口 $AdRequest / $AdShow failure
            that._adTracker && that._adTracker.onError(error);
          } catch (my_error) {
            // 忽略埋点错误
          } finally {
            try {
              if (that.option.once || that.error_times == 0) {
                that.oc &&
                  that.oc.onError &&
                  that.oc.onError.call(that.oc, error);
              }
            } catch (error) {
              // 忽略回调错误
            }
          }
        },
        onClose: function (state) {
          try {
            if (that.type !== "native" && that.type !== "custom" && that.type !== "grid") {
              be_showing = false;
            }
            that.is_running = false;

            if (that.type === "native" || that.type === "custom" || that.type === "grid") {
              that.hasTriggeredShow = false;
            }

            let current = +new Date();
            that.lastTimestamp = current;
            latest_show_time = current;
            triggerTask();

            // 埋点：$WatchVideo（仅激励/插屏）；信息流/格子不打
            if (
              !that.hasTriggeredClose &&
              (that.type === "reward" || that.type === "interstitial")
            ) {
              that.hasTriggeredClose = true;
              const stateObj =
                state && typeof state === "object" ? state : {};
              const isFinish =
                that.type === "reward" ? !!stateObj.isEnded : true;
              that._adTracker && that._adTracker.close(isFinish);
            }
          } catch (error) {
            console.warn("⚠️ [TaskHandler.onClose] 处理失败:", error);
          } finally {
            try {
              that.oc &&
                that.oc.onClose &&
                that.oc.onClose.call(that.oc, state);
            } catch (error) {
              // 忽略回调错误
            }
          }
        },
        // CustomAd / 原生 / 格子：关闭可能走 onHide；不打 $WatchVideo
        onHide: function (...args) {
          try {
            if (
              that.type === "custom" ||
              that.type === "native" ||
              that.type === "grid"
            ) {
              that.is_running = false;
              that.hasTriggeredShow = false;
              const current = +new Date();
              that.lastTimestamp = current;
              latest_show_time = current;
              triggerTask();
            }
          } catch (error) {
            console.warn("⚠️ [TaskHandler.onHide] 处理失败:", error);
          } finally {
            try {
              that.oc &&
                that.oc.onHide &&
                that.oc.onHide.call(that.oc, ...args);
            } catch (e) {}
          }
        },
      };
      // console.log(`✅ [TaskHandler] callbacks 对象构建完成`);
    } catch (error) {
      // console.log(`❌ [TaskHandler] 构建回调装饰器时出错:`, error);
      throw error;
    }

    // console.log(`🎉 [TaskHandler] 构造函数完全完成 - code: "${option.code}"`);
  }

  /**
   * 增加执行次数
   */
  increaseTimesToStorage() {
    // console.log(`📊 [TaskHandler.increaseTimesToStorage] 增加展示次数 - code: "${this.code}"`);
    this.times += 1;
    try {
      //只加载一次的广告不用存储次数
      if (this.option.once) {
        // console.log(`📋 [TaskHandler.increaseTimesToStorage] 一次性任务，跳过存储`);
        return;
      }

      let appId =
        this.fbisdk && typeof this.fbisdk.getAppId === "function"
          ? this.fbisdk.getAppId()
          : "unknown";
      let key = `${appId}_${this.code}_timesrecord`;
      // console.log(`🔑 [TaskHandler.increaseTimesToStorage] storage key: "${key}"`);

      //重新拿一次 防止过程中跨天
      // console.log(`🔍 [TaskHandler.increaseTimesToStorage] 重新获取当前次数...`);
      const oldValue = this.getTimesFromStorage();
      // console.log(`📊 [TaskHandler.increaseTimesToStorage] 当前次数:`, oldValue);

      let newValue = {
        date: +new Date(),
        today_times: oldValue.today_times + 1,
        thisyear_times: oldValue.thisyear_times + 1,
      };
      // console.log(`📊 [TaskHandler.increaseTimesToStorage] 新次数:`, newValue);

      // 尝试不同的存储API
      // console.log(`🔍 [TaskHandler.increaseTimesToStorage] 保存到存储...`);
      if (typeof uni !== "undefined" && uni.setStorageSync) {
        // console.log(`💾 [TaskHandler.increaseTimesToStorage] 使用 uni.setStorageSync`);
        uni.setStorageSync(key, newValue);
      }

      //刷新当前值
      this.today_times = newValue.today_times;
      this.thisyear_times = newValue.thisyear_times;
      // console.log(`✅ [TaskHandler.increaseTimesToStorage] 次数更新完成: 今日=${this.today_times}, 今年=${this.thisyear_times}`);
    } catch (error) {
      // console.log(`❌ [TaskHandler.increaseTimesToStorage] 存储失败:`, error);
      // 忽略存储错误
    }
  }

  /**
   * 取出当前code之前的广告展示次数情况
   */
  getTimesFromStorage() {
    // console.log(`🔍 [TaskHandler.getTimesFromStorage] 开始获取历史次数 - code: "${this.code}"`);

    if (this.option.once) {
      // console.log(`📋 [TaskHandler.getTimesFromStorage] 一次性任务，返回0次数`);
      return {
        today_times: 0,
        thisyear_times: 0,
      };
    }

    try {
      // console.log(`🔧 [TaskHandler.getTimesFromStorage] 获取 appId...`);
      let appId =
        this.fbisdk && typeof this.fbisdk.getAppId === "function"
          ? this.fbisdk.getAppId()
          : "unknown";
      // console.log(`📊 [TaskHandler.getTimesFromStorage] appId: "${appId}"`);

      let key = `${appId}_${this.code}_timesrecord`;
      // console.log(`🔑 [TaskHandler.getTimesFromStorage] storage key: "${key}"`);

      if (typeof uni === "undefined") {
        return { today_times: 0, thisyear_times: 0 };
      }

      // console.log(`🔍 [TaskHandler.getTimesFromStorage] 调用 uni.getStorageSync("${key}")...`);
      let value = uni.getStorageSync(key);
      // console.log(`📊 [TaskHandler.getTimesFromStorage] uni storage 返回:`, value);

      return this.parseStorageValue(value);
    } catch (error) {
      // console.log(`❌ [TaskHandler.getTimesFromStorage] 获取存储失败:`, error);
      // console.log(`🔧 [TaskHandler.getTimesFromStorage] 返回默认值`);
      return {
        today_times: 0,
        thisyear_times: 0,
      };
    }
  }

  parseStorageValue(value) {
    // console.log(`🔍 [TaskHandler.parseStorageValue] 解析存储值:`, value);

    if (
      !value ||
      !Number.isFinite(value.date) ||
      !Number.isFinite(value.thisyear_times) ||
      !Number.isFinite(value.today_times)
    ) {
      // console.log(`📋 [TaskHandler.parseStorageValue] 存储值无效，返回默认值`);
      return {
        today_times: 0,
        thisyear_times: 0,
      };
    }

    // console.log(`🔍 [TaskHandler.parseStorageValue] 检查日期有效性...`);
    const today = new Date();
    const date = new Date(value.date);
    // console.log(`📅 [TaskHandler.parseStorageValue] 今天: ${today.toDateString()}, 存储日期: ${date.toDateString()}`);

    if (today.getFullYear() != date.getFullYear()) {
      // console.log(`📅 [TaskHandler.parseStorageValue] 跨年重置次数`);
      value.today_times = 0;
      value.thisyear_times = 0;
    } else if (
      today.getMonth() != date.getMonth() ||
      today.getDate() != date.getDate()
    ) {
      // console.log(`📅 [TaskHandler.parseStorageValue] 跨天重置今日次数`);
      value.today_times = 0;
    }

    // console.log(`✅ [TaskHandler.parseStorageValue] 最终次数: 今日=${value.today_times}, 今年=${value.thisyear_times}`);
    return value;
  }

  /**
   * 指定任务，成功执行了任务，返回true
   * @return {boolean}
   */
  execute() {
    // console.log(`🎯 [TaskHandler.execute] 开始执行 - code: "${this.code}", type: "${this.type}"`);

    // 先检查定时任务的次数限制，一次性任务稍后处理
    if (!this.option.once) {
      //定时任务 已达到数量限制，及时移除自身
      let needCancel = this.times >= this.option.times;
      // console.log(`📊 [TaskHandler.execute] 次数检查: ${this.times}/${this.option.times} (${needCancel ? '超限' : '正常'})`);

      //日次数限制
      needCancel =
        needCancel ||
        (Number.isFinite(this.option.day_times) &&
          this.today_times >= this.option.day_times);
      if (Number.isFinite(this.option.day_times)) {
        // console.log(`📊 [TaskHandler.execute] 日次数检查: ${this.today_times}/${this.option.day_times} (${this.today_times >= this.option.day_times ? '超限' : '正常'})`);
      }

      //年次数限制
      needCancel =
        needCancel ||
        (Number.isFinite(this.option.year_times) &&
          this.thisyear_times >= this.option.year_times);
      if (Number.isFinite(this.option.year_times)) {
        // console.log(`📊 [TaskHandler.execute] 年次数检查: ${this.thisyear_times}/${this.option.year_times} (${this.thisyear_times >= this.option.year_times ? '超限' : '正常'})`);
      }

      if (needCancel) {
        // console.log("❌ [TaskHandler.execute] 达到次数限制，从定时队列移除");
        timingAdTasks = timingAdTasks.filter((item) => item !== this);
        return false;
      }
    }

    //判断执行时机是否满足
    let delay = this.getDelay();
    // console.log(`⏰ [TaskHandler.execute] 延迟检查: ${(delay/1000).toFixed(1)}秒 (${delay > 0 ? '未到时间' : '可执行'})`);
    if (delay > 0) {
      if (!this.option.once) {
        return false;
      }
    }

    //当前任务正在执行
    // console.log(`🔄 [TaskHandler.execute] 运行状态检查: is_running=${this.is_running}`);
    if (this.is_running) {
      // console.log("⚠️ [TaskHandler.execute] 任务正在运行，跳过");
      return false;
    }

    //原生模板 / CustomAd / GridAd 强制重置全局展示状态，确保不会被其他广告的状态影响
    if (this.type === "native" || this.type === "custom" || this.type === "grid") {
      be_showing = false;
    }

    //其他全屏广告正在展示时，插屏和激励视频都不能同时调用平台API
    //原生模板广告不受此限制（原生是嵌入式的）
    // 小游戏取消该互斥，允许激励与插屏并行调度
    // console.log(`🎮 [TaskHandler.execute] 全局展示状态检查: be_showing=${be_showing}, type="${this.type}"`);
    if (
      !isMinigameRuntime() &&
      be_showing &&
      (this.type === "interstitial" || this.type === "reward")
    ) {
      // console.log("⚠️ [TaskHandler.execute] 其他全屏广告正在展示，检查是否需要强制重置");

      // 检查be_showing状态是否过期（超过120秒自动重置，防止状态卡死）
      let now = +new Date();
      let timeSinceLastShow = now - latest_show_time;
      if (timeSinceLastShow > 120 * 1000) {
        // console.log("🔧 [TaskHandler.execute] be_showing状态超时120s，强制重置");
        be_showing = false;
      } else {
        return false;
      }
    }

    try {
      this.ad_loading_time = +new Date();
      if (this._adTracker) {
        this._adTracker.syncParams(this.params, this.option);
        this._adTracker.beginRound({ isNewRound: this.error_times === 0 });
      }
    } catch (error) {
      // 忽略埋点错误
    } finally {
      // 原生模板 / 小游戏 CustomAd / GridAd 在每次执行前重置触发标记
      if (this.type === "native" || this.type === "custom" || this.type === "grid") {
        this.hasTriggeredShow = false;
      }
      this.hasTriggeredClose = false;

      // 倒计时结束，现在创建新的广告对象并显示
      switch (this.type) {
        case "reward": {
          adLoader.showReward(this.params, this.callbacks);
          break;
        }
        case "interstitial": {
          adLoader.showInterstitial(this.params, this.callbacks);
          break;
        }
        case "native": {
          adLoader.showNative(this.params, this.callbacks);
          break;
        }
        case "custom": {
          adLoader.showCustom(
            { ...(this.params || {}), adCode: this.code || this.params?.adCode },
            this.callbacks,
          );
          break;
        }
        case "grid": {
          adLoader.showGrid(
            { ...(this.params || {}), adCode: this.code || this.params?.adCode },
            this.callbacks,
          );
          break;
        }
        default: {
          throw new Error(`This type '${this.type}' is not supported`);
        }
      }

      //一次性任务在真正执行广告API后，才从队列中移除
      if (this.option.once) {
        // console.log("📌 [TaskHandler.execute] 一次性任务广告API已调用，从紧急队列移除");
        urgentADTask = urgentADTask.filter((item) => item !== this);
      }
    }

    //置为正在运行，避免被重复调度，待回调事件中重置
    // console.log("🔄 [TaskHandler.execute] 设置 is_running = true");
    this.is_running = true;

    //原生模板 / CustomAd / GridAd 不设置全局展示状态（嵌入式，不阻塞其他广告）
    // 小游戏也不用 be_showing 互斥激励/插屏
    if (
      !isMinigameRuntime() &&
      this.type !== "native" &&
      this.type !== "custom" &&
      this.type !== "grid"
    ) {
      // console.log("🎮 [TaskHandler.execute] 设置 be_showing = true (全局展示状态)");
      be_showing = true;
      // 同步更新全局时间戳，防止超时检查基于旧时间提前重置be_showing
      // 场景：两个广告间隔>120s时，新广告刚开始就被超时机制穿透
      latest_show_time = +new Date();
    }

    // console.log(`✅ [TaskHandler.execute] 执行成功 - code: "${this.code}"`);
    return true;
  }

  /**
   * @description
   * 返回距离下次执行的时间间隔，单位ms
   */
  getDelay() {
    // console.log(`🔍 [TaskHandler.getDelay] 计算延迟 - code: "${this.code}"`);

    let current = +new Date();
    // console.log(`⏰ [TaskHandler.getDelay] 当前时间: ${new Date(current).toLocaleTimeString()}`);
    // console.log(`⏰ [TaskHandler.getDelay] 上次时间: ${new Date(this.lastTimestamp).toLocaleTimeString()}`);
    // console.log(`⏰ [TaskHandler.getDelay] 间隔: ${((current - this.lastTimestamp)/1000).toFixed(1)}秒`);

    //当前时间-上次时间=已经经过的时间；延时-已经经过的时间，即为下次执行的时间
    let delay = this.option.interval * 1000 - (current - this.lastTimestamp);
    // console.log(`📅 [TaskHandler.getDelay] 基础延迟计算: interval=${this.option.interval}秒, 结果=${(delay/1000).toFixed(1)}秒`);

    if (this.is_first) {
      delay = this.option.delay * 1000 - (current - this.lastTimestamp);
      // console.log(`🎯 [TaskHandler.getDelay] 首次执行延迟: delay=${this.option.delay}秒, 结果=${(delay/1000).toFixed(1)}秒`);
    }

    //如果是插屏广告 不能小于全局间隔
    //即：小程序启动后30秒内才能展示插屏广告，距离上次展示广告60秒后，才能展示下一次
    if (this.type == "interstitial") {
      // console.log(`🎮 [TaskHandler.getDelay] 插屏广告特殊限制检查:`);
      // console.log(`  - 全局上次广告时间: ${new Date(latest_show_time).toLocaleTimeString()}`);
      // console.log(`  - 距全局上次: ${((current - latest_show_time)/1000).toFixed(1)}秒`);
      // console.log(`  - 已显示过插屏: ${interstitial_has_showed}`);

      //当前时间-全局上次时间=已经经过的时间，插屏全局延时-已经经过的时间，即为下次执行的时间
      let d = NEXT_SHOW_TIME * 1000 - (current - latest_show_time);
      if (!interstitial_has_showed) {
        d = AFTER_LAUNCH_TIME * 1000 - (current - latest_show_time);
        // console.log(`  - 使用启动限制: ${AFTER_LAUNCH_TIME}秒, 结果=${(d/1000).toFixed(1)}秒`);
      } else {
        // console.log(`  - 使用间隔限制: ${NEXT_SHOW_TIME}秒, 结果=${(d/1000).toFixed(1)}秒`);
      }

      //2者取大值
      let oldDelay = delay;
      delay = Math.max(delay, d);
      if (delay !== oldDelay) {
        // console.log(`  - 延迟被插屏限制调整: ${(oldDelay/1000).toFixed(1)}秒 → ${(delay/1000).toFixed(1)}秒`);
      }
    }


    //如果正在运行，延后60S
    if (this.is_running) {
      let oldDelay = delay;
      delay = Math.max(delay, 60 * 1000);
      // console.log(`⚠️ [TaskHandler.getDelay] 正在运行，延迟调整: ${(oldDelay/1000).toFixed(1)}秒 → ${(delay/1000).toFixed(1)}秒`);
    }

    // console.log(`🏁 [TaskHandler.getDelay] 最终延迟: ${(delay/1000).toFixed(1)}秒 (${delay <= 0 ? '立即执行' : '等待'})`);
    return delay;
  }
}

/**
  @description
  广告管理器
  1.小程序启动后30秒内才能展示插屏广告，距离上次展示广告60秒后，才能展示下一次
  2.处理各个页面定时弹出广告的时序问题，主动点击的广告优先展示，其他广告按顺序展示
*/
class AdManager {
  constructor(fbisdk) {
    this.fbisdk = fbisdk;

    // 初始化全局广告管理器
    if (fbisdk && fbisdk.ad) {
      globalAdManager.init(fbisdk.ad);
    }
  }

  /**
   * @description
   * 记录小程序启动时间，开屏广告首次展示以此刻开始计时，30s后才能展示
   */
  async appLaunch(scene) {
    latest_show_time = +new Date();
    lockAdEnterTime(latest_show_time);
    console.log("记录小程序启动时间");
    if (this.fbisdk && typeof this.fbisdk.trackAsync === "function") {
      try {
        console.log("记录小程序启动时间 $MPLaunch");
        this.fbisdk.trackAsync("$MPLaunch", {
          scene,
        });
		this.fbisdk.trackAsync("$BucketStart");
        console.log("✅ $MPLaunch 埋点上报成功");
      } catch (error) {
        console.error("❌ $MPLaunch 埋点上报失败:", error);
      }
    }
  }

  /**
   * #@description
   * 小程序展示时，激活定时任务 请放入App.vue中的onShow
   */
  appShow() {
    const now = +new Date();
    startTime = now;
    // 首次进入前台锁定广告 triggerTiming 起点；切后台再回不重置
    lockAdEnterTime(now);
    triggerTask();
  }

  /**
   * @description
   * 小程序隐藏时，暂停定时任务 请放入App.vue中的onHide
   */
  appHide() {

    if (this.fbisdk && typeof this.fbisdk.trackAsync === "function") {
      const start = Number(startTime) || 0;
      const ms = start > 0 ? Math.max(0, Date.now() - start) : 0;
      this.fbisdk.trackAsync("$MPHide", {
        time: ms,
      });
    }
    pauseTask();
  }

  /**
   * 预加载激励视频
   * @param {Object} code - 广告代码位
   * @param {Object} params - 加载广告的选项 { adUnitId }为必须，其他可选成员参见 https://developer.open-douyin.com/docs/resource/zh-CN/mini-app/develop/api/open-interface/ads/rewarded-video/tt-createRewardedVideoAd
   * @returns { Promise } 当广告拉取成功时，该 promise 会被 resolve；当发生错误时，该 promise 则被会 reject
   */
  async preloadRewardAsync(code, params) {
    return adLoader.preloadRewardAsync(params);
  }

  /**
   * 预加载插屏广告
   * @param {Object} code - 广告代码位
   * @param {Object} params - 加载广告的选项 { adUnitId }为必须
   * @returns { Promise } 当广告拉取成功时，该 promise 会被 resolve；当发生错误时，该 promise 则被会 reject
   */
  async preloadInterstitialAsync(code, params) {
    // 插屏广告不需要预加载，因为它会在展示时自动加载
    // 这里直接返回成功，保持API一致性
    return Promise.resolve();
  }


  /**
   * 预加载原生模板广告
   * @param {String} code - 广告代码位
   * @param {Object} params - 加载广告的选项 { adUnitId, style, adIntervals }为可选
   * @returns { Promise } 当广告拉取成功时，该 promise 会被 resolve；当发生错误时，该 promise 则被会 reject
   */
  async preloadNativeAsync(code, params) {
    return adLoader.preloadNativeAsync(params);
  }

  /**
   *	@description
   *	展示激励视频广告
   *	当无法展示时，触发onError
   *  @param {Object} code - 广告代码位
   *  @param {Object} params - 加载广告的选项 { adUnitId }为必须，其他可选成员参见 https://developer.open-douyin.com/docs/resource/zh-CN/mini-app/develop/api/open-interface/ads/rewarded-video/tt-createRewardedVideoAd
   *	@param {Object} callbacks - 回调函数
   *	@returns {Boolean} 请求成功返回true
   */
  showReward(code, params, callbacks) {
    // console.log('fbiadIndex showReward---->',params)
    // 去重：如果已有相同code的紧急任务等待执行，更新回调而非重复创建
    const existingIndex = urgentADTask.findIndex(
      (t) => t.code === code && !t.is_running,
    );
    if (existingIndex >= 0) {
      const task = urgentADTask[existingIndex];
      task.oc = callbacks;
      if (params) {
        task.params = params;
        task._adTracker && task._adTracker.syncParams(params, task.option);
      }
      triggerTask();
      return true;
    }
    this.registerTimingReward({
      code,
      params,
      callbacks,
      delay: 0,
      interval: 999,
      times: 1,
      once: true,
    });
    return true;
  }

  /**
    @description
    展示全屏视频广告
    当无法展示时，触发onError
  *   @param {Object} code - 广告代码位
    @param {String} params - 加载广告单元的选项 须传入 { adUnitId }
    @param {Object} callbacks - 回调函数 
    @returns{Boolean} 请求成功返回true
  */
  showInterstitial(code, params, callbacks) {
    // 去重：如果已有相同code的紧急任务等待执行，更新回调而非重复创建
    const existingIndex = urgentADTask.findIndex(
      (t) => t.code === code && !t.is_running,
    );
    if (existingIndex >= 0) {
      const task = urgentADTask[existingIndex];
      task.oc = callbacks;
      if (params) {
        task.params = params;
        task._adTracker && task._adTracker.syncParams(params, task.option);
      }
      triggerTask();
      return true;
    }
    this.registerTimingInterstitial({
      code,
      params,
      callbacks,
      delay: 0,
      interval: 999,
      times: 1,
      once: true,
    });
    return true;
  }



  /**
   * @description
   * 展示原生模板广告
   * 当无法展示时，触发onError
   * @param {String} code - 广告代码位
   * @param {Object} params - 加载广告的选项 { adUnitId }为必须，{ style, adIntervals }为可选
   * @param {Object} callbacks - 回调函数，支持 onLoad, onError, onShow, onClose, onHide, onResize
   * @returns {Boolean} 请求成功返回true
   */
  showNative(code, params, callbacks) {
    // 去重：如果已有相同code的紧急任务等待执行，更新回调而非重复创建
    const existingIndex = urgentADTask.findIndex(
      (t) => t.code === code && !t.is_running,
    );
    if (existingIndex >= 0) {
      const task = urgentADTask[existingIndex];
      task.oc = callbacks;
      if (params) {
        task.params = params;
        task._adTracker && task._adTracker.syncParams(params, task.option);
      }
      triggerTask();
      return true;
    }
    this.registerTimingNative({
      code,
      params,
      callbacks,
      delay: 0,
      interval: 999,
      times: 1,
      once: true,
    });
    return true;
  }

  /**
   * 展示小游戏原生模板广告（wx.createCustomAd，type=6）
   */
  showCustom(code, params, callbacks) {
    const existingIndex = urgentADTask.findIndex(
      (t) => t.code === code && !t.is_running,
    );
    if (existingIndex >= 0) {
      const task = urgentADTask[existingIndex];
      task.oc = callbacks;
      if (params) {
        task.params = params;
        task._adTracker && task._adTracker.syncParams(params, task.option);
      }
      triggerTask();
      return true;
    }
    const handle = new TaskHandler(this.fbisdk, "custom", {
      code,
      params,
      callbacks,
      delay: 0,
      interval: 999,
      times: 1,
      once: true,
    });
    urgentADTask.push(handle);
    triggerTask();
    return true;
  }

  hideCustom(code, params = {}) {
    return adLoader.hideCustom({
      adUnitId: params.adUnitId,
      adCode: code || params.adCode,
    });
  }

  /**
   * 展示小游戏格子广告（wx.createCustomAd 矩阵格子模板，type=7）
   */
  showGrid(code, params, callbacks) {
    const existingIndex = urgentADTask.findIndex(
      (t) => t.code === code && !t.is_running,
    );
    if (existingIndex >= 0) {
      const task = urgentADTask[existingIndex];
      task.oc = callbacks;
      if (params) {
        task.params = params;
        task._adTracker && task._adTracker.syncParams(params, task.option);
      }
      triggerTask();
      return true;
    }
    const handle = new TaskHandler(this.fbisdk, "grid", {
      code,
      params,
      callbacks,
      delay: 0,
      interval: 999,
      times: 1,
      once: true,
    });
    urgentADTask.push(handle);
    triggerTask();
    return true;
  }

  hideGrid(code, params = {}) {
    return adLoader.hideGrid({
      adUnitId: params.adUnitId,
      adCode: code || params.adCode,
    });
  }

  /**
   *
   *	@description
   *	注册定时激励广告
   *	定时弹出广告优先级最低，如果有用户主动请求广告，将影响定时弹出广告的时机
   * @param {Object} option - 示例：
   * {
   *		code: 'home',
   *		adUnitId: '',
   *		delay: 100,
   *		interval: 300,
   *		callbacks: {}
   *		times: 1
   *	}
   * @return {handle} 注销需要用到句柄
   */
  registerTimingReward(option) {
    let handle = new TaskHandler(this.fbisdk, "reward", option);
    if (option.once) {
      urgentADTask.push(handle);
    } else {
      timingAdTasks.push(handle);
    }

    triggerTask();

    return handle;
  }

  /**
   *	@description
   *	注册定时插屏广告
   *	定时弹出广告优先级最低，如果有用户主动请求广告，将影响定时弹出广告的时机
   * @param {Object} option - 示例：
   * {
   *		code: 'home',
   *		adUnitId: '',
   *		delay: 100,
   *		interval: 300,
   *		callbacks: {}
   *		times: 1
   *	}
   * @return {handle} 注销需要用到句柄
   */
  registerTimingInterstitial(option) {
    // console.log(`🎯 [AdManager] registerTimingInterstitial 开始 - code: "${option.code}"`);
    // console.log("📋 [AdManager] 任务配置:", JSON.stringify(option, null, 2));

    // console.log("🔧 [AdManager] 创建 TaskHandler...");
    let handle = new TaskHandler(this.fbisdk, "interstitial", option);
    // console.log("✅ [AdManager] TaskHandler 创建完成:", handle);
    // console.log(`📊 [AdManager] handle 类型检查: ${typeof handle}`);
    // console.log(`📊 [AdManager] handle 是否为空: ${handle == null}`);

    if (!handle) {
      // console.log("❌ [AdManager] TaskHandler 创建失败，handle为空");
      throw new Error("TaskHandler creation failed");
    }

    // console.log(`🔍 [AdManager] option.once = ${option.once}`);
    if (option.once) {
      // console.log("📌 [AdManager] 添加到紧急任务队列 (urgentADTask)");
      // console.log(`📊 [AdManager] 添加前紧急任务队列长度: ${urgentADTask.length}`);
      urgentADTask.push(handle);
      // console.log(`📊 [AdManager] 添加后紧急任务队列长度: ${urgentADTask.length}`);
      // console.log(`✅ [AdManager] 成功添加到紧急任务队列`);
    } else {
      // console.log("📌 [AdManager] 添加到定时任务队列 (timingAdTasks)");
      // console.log(`📊 [AdManager] 添加前定时任务队列长度: ${timingAdTasks.length}`);
      timingAdTasks.push(handle);
      // console.log(`📊 [AdManager] 添加后定时任务队列长度: ${timingAdTasks.length}`);
      // console.log(`✅ [AdManager] 成功添加到定时任务队列`);
    }

    // console.log("🚀 [AdManager] 调用 triggerTask 开始执行任务...");
    triggerTask();

    // console.log(`✅ [AdManager] registerTimingInterstitial 完成 - code: "${option.code}"`);
    return handle;
  }



  /**
   * @description
   * 注册定时原生模板广告
   * 注意：原生模板广告通常不适合定时弹出，建议使用 showNative 方法手动控制
   * @param {Object} option - 示例：
   * {
   *		code: 'home',
   *		params: { adUnitId: '', style: {}, adIntervals: 30 },
   *		delay: 100,
   *		interval: 300,
   *		callbacks: {}
   *		times: 1
   * }
   * @return {handle} 注销需要用到句柄
   */
  registerTimingNative(option) {
    let handle = new TaskHandler(this.fbisdk, "native", option);
    if (option.once) {
      urgentADTask.push(handle);
    } else {
      timingAdTasks.push(handle);
    }

    triggerTask();

    return handle;
  }

  /**
   * @description
   * 注销定时广告
   */
  unRegisterTimingAD(handle) {
    timingAdTasks = timingAdTasks.filter((item) => item !== handle);
    triggerTask();
  }
}

/**
 * @description
 * 基于SDK的广告管理器，依赖sdk
 * 内置SDK广告事件埋点上报
 * 内部自动处理插屏间隔问题
 */
export default AdManager;
