import http from "../fbiCoreHttp.js";
import utilsComfortable from "../../../utils/utilsComfortable/utilsCFIndex.js";

// 平台标识
const PLATFORM = 'WX';

const api = {
  DOMAIN: 'https://md.898mk.cn/',
  // DOMAIN: "https://test.ipandata.com/",
  TRACK_API: 'mini/track/captures',
}

const loginApi = {
  DOMAIN: "https://apile.898mk.cn/",
  // DOMAIN: "https://test.ipandata.com/",
  USER_LOGIN: "sp/mini/basic/user/login",
  AD_CONFIG: "sp/mini/app/conf/function",
  SCRRE_USERS: "sp/mini/basic/deliveryConf/screenRecordingUsers"
}

function normalizeHttpsDomain(url) {
  if (!url || typeof url !== "string") return "";
  let domain = url.trim();
  if (!domain) return "";
  if (!/^https?:\/\//i.test(domain)) {
    domain = `https://${domain}`;
  }
  if (!domain.endsWith("/")) {
    domain += "/";
  }
  return domain;
}

function getRuntimeHttpsConfig() {
  try {
    if (typeof utilsComfortable.getExtConfigSync === "function") {
      return utilsComfortable.getExtConfigSync() || {};
    }
  } catch (e) {}
  return {};
}

// 动态获取接口API配置：
// readyAsync(config) 或 getExtConfigSync 传入 requestHTTPS / trackHTTPS 时覆盖域名
function getInterfaceApi() {
  const config = getRuntimeHttpsConfig();
  // trackHTTPS → api.DOMAIN（默认 md.*，埋点）
  // requestHTTPS → loginApi.DOMAIN（默认 apile.*，登录/配置等业务请求）
  const trackDomain = normalizeHttpsDomain(config.trackHTTPS);
  const requestDomain = normalizeHttpsDomain(config.requestHTTPS);

  if (trackDomain) {
    api.DOMAIN = trackDomain;
  }
  if (requestDomain) {
    loginApi.DOMAIN = requestDomain;
  }

  const nextApi = { ...api };
  const nextLoginApi = { ...loginApi };

  if (trackDomain || requestDomain) {
    console.log("🔍 [微信平台] 使用 ext 配置覆盖域名", {
      trackHTTPS: nextApi.DOMAIN,
      requestHTTPS: nextLoginApi.DOMAIN,
    });
  } else {
    console.log("🔍 [微信平台] 动态获取接口API配置");
  }

  return {
    api: nextApi,
    loginApi: nextLoginApi,
  };
}

function formatSystem(e) {
  var t = e.toLowerCase();
  return "ios" === t ? "iOS" : "android" === t ? "Android" : e;
}

const deviceAsync = (distinct_id, app_id) => {
  return new Promise((resolve, reject) => {
    const getMpVersion = () => {
      try {
        if (typeof wx.getAccountInfoSync === "function") {
          const accountInfo = wx.getAccountInfoSync();
          return accountInfo.miniProgram ? accountInfo.miniProgram.version : "";
        }
      } catch (e) {}
      return "";
    };

    const buildDeviceInfo = (res) => {
      const version = getMpVersion();
      return {
        $model: res.model,
        $manufacturer: res.brand ? res.brand : "",
        $brand: res.brand ? res.brand.toUpperCase() : "",
        $screen_width: res.screenWidth,
        $screen_height: res.screenHeight,
        $os: `${formatSystem(res.platform)}`,
        $os_version: `${res.system}-${res.version || version}`,
        $network_type: res.networkType || "unknown",
        language: res.language,
      };
    };

    // 优先使用新拆分 API，避免 getSystemInfo 弃用警告
    if (
      typeof wx.getDeviceInfo === "function" &&
      typeof wx.getWindowInfo === "function" &&
      typeof wx.getAppBaseInfo === "function"
    ) {
      try {
        const deviceInfo = wx.getDeviceInfo();
        const windowInfo = wx.getWindowInfo();
        const appBaseInfo = wx.getAppBaseInfo();
        const finish = (networkType) => {
          resolve(
            buildDeviceInfo({
              model: deviceInfo.model,
              brand: deviceInfo.brand,
              platform: deviceInfo.platform,
              system: deviceInfo.system,
              screenWidth: windowInfo.screenWidth,
              screenHeight: windowInfo.screenHeight,
              version: appBaseInfo.version,
              language: appBaseInfo.language,
              networkType,
            }),
          );
        };

        if (typeof wx.getNetworkType === "function") {
          wx.getNetworkType({
            success: (net) => finish(net.networkType || "unknown"),
            fail: () => finish("unknown"),
          });
        } else {
          finish("unknown");
        }
        return;
      } catch (error) {
        // 新 API 失败时回退旧接口
      }
    }

    // 小游戏等环境可能只有 getSystemInfoSync / getSystemInfo
    if (typeof wx.getSystemInfoSync === "function") {
      try {
        const res = wx.getSystemInfoSync();
        const finish = (networkType) => {
          resolve(buildDeviceInfo({ ...res, networkType }));
        };
        if (typeof wx.getNetworkType === "function") {
          wx.getNetworkType({
            success: (net) => finish(net.networkType || "unknown"),
            fail: () => finish("unknown"),
          });
        } else {
          finish("unknown");
        }
        return;
      } catch (error) {
        // continue to async getSystemInfo
      }
    }

    if (typeof wx.getSystemInfo === "function") {
      wx.getSystemInfo({
        success: (res) => {
          try {
            resolve(buildDeviceInfo(res));
          } catch (error) {
            reject(error);
          }
        },
        fail: (error) => {
          reject(error);
        },
      });
      return;
    }

    reject(new Error("微信环境无法获取设备信息"));
  });
};

const requestAsync = (option) => {
  return new Promise((resolve, reject) => {
    wx.request({
      ...option,
      success: function (res) {
        // 修复：确保返回有效的响应数据
        let responseData = res.data;

        if (responseData.status != 0) {
          let serverError = new Error(`服务器错误: HTTP ${res.statusCode}`);
          let stack = JSON.stringify(option);
          serverError.name = "ServerError";
          serverError.statusCode = res.statusCode;
          serverError.stack = stack;
          serverError.message = responseData.error || responseData.msg;
          serverError.headers = res.header;

          reject(serverError);
          return;
        }

        resolve(responseData);
      },
      fail: function (error) {
        console.error("网络请求失败:", error);
        reject(error);
      },
    });
  });
};

/**
 * 比较版本号
 * @param {string} v1
 * @param {string} v2
 * @returns {number} 1: v1>v2, -1: v1<v2, 0: 相等
 */
function compareVersion(v1, v2) {
  if (typeof v1 !== "string" || typeof v2 !== "string") return 0;
  const arr1 = v1.split(".");
  const arr2 = v2.split(".");
  const len = Math.max(arr1.length, arr2.length);
  while (arr1.length < len) arr1.push("0");
  while (arr2.length < len) arr2.push("0");
  for (let i = 0; i < len; i++) {
    const n1 = parseInt(arr1[i], 10);
    const n2 = parseInt(arr2[i], 10);
    if (n1 > n2) return 1;
    if (n1 < n2) return -1;
  }
  return 0;
}

/**
 * 从本地存储中异步获取指定键的值
 * @param {string} key - 要获取的存储键名
 * @returns {any} 返回存储的值，如果不存在则返回undefined
 */
const getStorageAsync = async (key) => {
  return wx.getStorageSync(key);
};

const setStorageAsync = async (key, value) => {
  wx.setStorageSync(key, value);
};

// 登录【微信端】
const loginAsync = async (app_id, env, loginParams) => {
  // isWXGameSDK=true：走 DH 官方 SDK 登录
  try {
    const { default: dhMiniSDKManager } = await import(
      "../../../dhminisdk/DHMiniSDKManager.js"
    );
    if (dhMiniSDKManager && dhMiniSDKManager.isReady()) {
      console.log("📡 [微信登录] 使用 DHMiniSDK.login");
      return await dhMiniSDKManager.loginAsync(app_id);
    }
  } catch (error) {
    console.warn("⚠️ [微信登录] DH 登录不可用，回退 wx.login:", error && error.message);
  }

  return new Promise((resolve, reject) => {
    wx.login({
      success: async (resLogin) => {
        try {
          let { code } = resLogin;

          let data = {
            appId: app_id,
            loginAccount: code,
            loginType: PLATFORM
          };

          let result = await http.enviroment(env).userLoginAsync(data);
          console.log("userLoginAsync wx --->", result)
          let model = result.data;
          if (!model || !model.accessToken) {
            reject(new Error("微信登录成功但返回数据缺少 accessToken"));
            return;
          }
          //明确返回信息
          let dataModel = {
            accessToken: model.accessToken,
            appId: model.appId,
            createdDt: model.createdDt,
            expireAt: model.expireAt,
            userId: model.userId,
            // 兼容可能存在的额外字段
            openId: model.openid || model.openId || '',
            unionId: model.unionid || model.unionId || '',
            session_key: model.session_key || ''
          };
          console.log("✅ [微信登录] 成功", {
            userId: dataModel.userId,
            appId: dataModel.appId,
            expireAt: dataModel.expireAt,
          });

          resolve(dataModel);
        } catch (error) {
          reject(error);
        }
      },
      fail: reject
    });
  });
};


export default {
  deviceAsync,
  requestAsync,
  getStorageAsync,
  setStorageAsync,
  loginAsync,
  getInterfaceApi,
  PLATFORM
};

