import AdManager from "../fbiad/fbiadIndex.js";
import deploy from "./Deploy.js";
import globalAdManager from "../fbiad/GlobalManager.js";
const handles = new Map();
// 新增：存储预注册的事件处理器
const preRegisteredCallbacks = new Map();

// 延迟获取配置，避免在模块加载时就调用getExtConfig()
function getExtConfigs() {
  try {
    return deploy.getExtConfig().advertis || [];
  } catch (error) {
    console.warn("⚠️ [AD] 获取配置失败，使用空数组:", error);
    return [];
  }
}

function getDefaultRewardConfig() {
  const ext_configs = getExtConfigs();
  return ext_configs.find((i) => i.code == "default_reward") || {};
}

function getDefaultInterConfig() {
  const ext_configs = getExtConfigs();
  return ext_configs.find((i) => i.code == "default_interstitial") || {};
}

function getDefaultNativeConfig() {
  const ext_configs = getExtConfigs();
  return ext_configs.find((i) => i.code == "default_native") || {};
}

function getDefaultGameNativeConfig() {
  const ext_configs = getExtConfigs();
  return ext_configs.find((i) => i.code == "default_game_native") || {};
}

function getDefaultGridConfig() {
  const ext_configs = getExtConfigs();
  return ext_configs.find((i) => i.code == "default_grid") || {};
}

/**
 * 按 type 取本地默认广告位
 * 1 → default_reward
 * 2 → default_interstitial
 * 4 → default_native
 * 6 → default_game_native
 * 7 → default_grid
 */
function getDefaultConfigByType(type) {
  switch (+type) {
    case 2:
      return getDefaultInterConfig();
    case 4:
      return getDefaultNativeConfig();
    case 6:
      return getDefaultGameNativeConfig();
    case 7:
      return getDefaultGridConfig();
    case 1:
    default:
      return getDefaultRewardConfig();
  }
}

function hasAdUnitId(value) {
  return value !== undefined && value !== null && String(value).trim() !== "";
}

/**
 * adUnitId 优先级：远程配置 > 本地同 code > 本地默认类别位(按 type)
 */
function resolveAdUnitId(adSlot, ext_config, code) {
  if (hasAdUnitId(adSlot.adUnitId)) {
    return String(adSlot.adUnitId).trim();
  }

  const ext_configs = getExtConfigs();
  const candidates = [
    ext_config,
    ext_configs.find((item) => item.code === code),
    getDefaultConfigByType(adSlot.type),
  ];

  for (const item of candidates) {
    if (hasAdUnitId(item?.adUnitId)) {
      return String(item.adUnitId).trim();
    }
  }

  return "";
}


/**
 * @description
 * 广告插槽管理
 * 根据服务端下发的配置，实现自由控制
 */
class AD {
  constructor() {
    // 延迟初始化，等待 deploy 准备就绪
    this.adManager = null;
    this.hasPreloaded = false;
    this._initialized = false;

    // console.log('📦 [AD] 构造函数执行，等待 Deploy 初始化...');
  }

  /**
   * 初始化 AD
   * 这个方法应该在 Deploy.readyAsync() 完成后调用
   */
  init() {
    if (this._initialized) {
      // console.log('📦 [AD] 已经初始化过了');
      return;
    }

    try {
      if (!deploy) {
        throw new Error("Deploy 未定义");
      }

      if (!deploy.fbisdk) {
        throw new Error("Deploy.fbisdk 还未初始化");
      }

      // 设置循环引用
      deploy.fbisdk.ad = this;

      // 创建 AdManager 实例
      this.adManager = new AdManager(deploy.fbisdk);
      this._initialized = true;

      // console.log('✅ [AD] 初始化完成');
    } catch (error) {
      console.error("❌ [AD] 初始化失败:", error);
      throw error;
    }
  }

  /**
   * 检查是否已初始化，如果未初始化则等待初始化完成
   */
  async ensureInitialized() {
    console.log("🚀 [AD Trace] ensureInitialized 触发");
    if (!this._initialized) {
      console.log(
        "🔄 [AD.ensureInitialized] AD 未初始化，等待Deploy准备就绪...",
      );
      try {
        // 等待Deploy准备就绪
        await deploy.readyAsync();

        // 如果仍未初始化，说明Deploy中的初始化逻辑可能有问题，手动初始化
        if (!this._initialized) {
          console.log(
            "🔧 [AD.ensureInitialized] Deploy已就绪但AD仍未初始化，尝试手动初始化...",
          );
          this.init();
        }

        console.log("✅ [AD.ensureInitialized] 等待初始化完成");
      } catch (error) {
        console.error(
          "❌ [AD.ensureInitialized] 等待初始化失败:",
          error,
        );
        throw new Error("AD 初始化失败: " + error.message);
      }
    }
  }

  /**
   * 获取远程广告配置
   */
  async getAdvertConfigAsync() {
    let config = await deploy.getAdvertConfigAsync();
    console.log("🔍 [AD] 获取远程广告配置", config);

    config = config || {
      isClosed: false,
      isAdTimmingClosed: false,
      adSlots: [],
    };

    config.adSlots = Array.isArray(config.adSlots) ? config.adSlots : [];

    return config;
  }

  /**
   * 预加载广告
   */
  async preloadADAsync() {
    console.log("🚀 [AD Trace] preloadADAsync 触发");
    // 如果未初始化，等待Deploy准备就绪后自动初始化
    if (!this._initialized) {
      console.log(
        "🔄 [AD.preloadADAsync] AD 未初始化，等待Deploy准备就绪...",
      );
      try {
        // 等待Deploy准备就绪
        await deploy.readyAsync();

        // 如果仍未初始化，说明Deploy中的初始化逻辑可能有问题，手动初始化
        if (!this._initialized) {
          console.log(
            "🔧 [AD.preloadADAsync] Deploy已就绪但AD仍未初始化，尝试手动初始化...",
          );
          this.init();
        }

        console.log("✅ [AD.preloadADAsync] 等待初始化完成");
      } catch (error) {
        console.error(
          "❌ [AD.preloadADAsync] 等待初始化失败:",
          error,
        );
        return;
      }
    }

    //自动处理预加载
    if (this.hasPreloaded) {
      return;
    }
    this.hasPreloaded = true;

    let config = await this.getAdvertConfigAsync();
    const slots = Array.isArray(config?.adSlots) ? config.adSlots : [];
    let rewardPreloaded = false;

    const tryPreloadSlot = async (item) => {
      if (!item || !item.code) return false;
      let adSlot = await this.findAdSlotWithCodeAsync(item.code);
      if (!adSlot || adSlot.isClosed) return false;

      const adType = Number(adSlot.type);
      // 激励视频：远程未配 preload 时默认 true；显式 false 则跳过
      // 其他类型：仍需显式 preload: true
      const shouldPreload =
        adType === 1 ? item.preload !== false : item.preload === true;
      if (!shouldPreload) return false;

      console.log(
        `🚀 [AD Trace] 预加载广告位: "${item.code}" type=${adType}` +
          (adType === 1 && item.preload == null ? " (激励默认 preload=true)" : ""),
      );

      switch (adType) {
        case 1: {
          let params = {
            adUnitId: adSlot.adUnitId,
          };
          if (config.isRiskControl === false && adSlot.multiton) {
            params.multiton = adSlot.multiton;
          }
          adSlot.multitonRewardTimes &&
            (params.multitonRewardTimes = adSlot.multitonRewardTimes);
          adSlot.multitonRewardMsg &&
            (params.multitonRewardMsg = adSlot.multitonRewardMsg);
          adSlot.progressTip && (params.progressTip = adSlot.progressTip);
          await this.adManager.preloadRewardAsync(adSlot.code, params);
          console.log(
            `preload reward AD '${adSlot.code}-${adSlot.adUnitId}' success`,
          );
          return true;
        }
        case 2: {
          let params = {
            adUnitId: adSlot.adUnitId,
          };
          await this.adManager.preloadInterstitialAsync(adSlot.code, params);
          console.log(
            `preload interstitial AD '${adSlot.adUnitId}' success`,
          );
          return false;
        }
        case 4: {
          let params = {
            adUnitId: adSlot.adUnitId,
          };
          let style = adSlot.style || {};
          params.style = {
            left: style.left !== undefined ? style.left : 0,
            top: style.top !== undefined ? style.top : 0,
            width: style.width !== undefined ? style.width : "100%",
            fixed: style.fixed !== undefined ? style.fixed : true,
          };
          if (adSlot.adIntervals !== undefined) {
            params.adIntervals = Math.max(adSlot.adIntervals, 30);
          } else {
            params.adIntervals = 30;
          }
          await this.adManager.preloadNativeAsync(adSlot.code, params);
          console.log(
            `preload native AD '${adSlot.code}-${adSlot.adUnitId}' success`,
          );
          return false;
        }
        default:
          return false;
      }
    };

    await Promise.all(
      slots.map(async (item) => {
        try {
          const isReward = await tryPreloadSlot(item);
          if (isReward) rewardPreloaded = true;
        } catch (error) {
          console.error("preload AD error", error);
        }
      }),
    );

    // 远程未配任何激励位 / 漏配 preload：兜底预加载本地 default_reward
    if (!rewardPreloaded) {
      try {
        const defaultReward = getDefaultRewardConfig();
        if (defaultReward && defaultReward.adUnitId) {
          console.log(
            "🚀 [AD Trace] 远程未命中激励预加载，兜底预加载 default_reward",
          );
          await tryPreloadSlot({
            code: defaultReward.code || "default_reward",
            // 兜底视为默认开启
            preload: undefined,
          });
        }
      } catch (error) {
        console.error("preload default_reward error", error);
      }
    }
  }

  /**
   * @description
   * 通过 code 查找广告位配置并合并。
   * 优先级：远程同 code > 本地同 code > 按 type 的本地默认类别位
   * （default_reward / default_interstitial / default_native / default_game_native / default_grid）
   * @param {String} code
   * @param {Boolean} isStrict true=严格模式（远程必须有记录，否则 null；定时位用）
   * @param {Object|null} customStyle
   * @param {Number|String|null} hintType 调用方传入的 type（远程/本地都无 code 时用来选默认类别）
   */
  async findAdSlotWithCodeAsync(
    code,
    isStrict = false,
    customStyle = null,
    hintType = null,
  ) {
    console.log(
      `🔍 [AD.findAdSlotWithCodeAsync] 开始查找 - code: "${code}", isStrict: ${isStrict}, hintType: ${hintType}, customStyle: ${customStyle ? "object" : "null"}`,
    );

    let config = await this.getAdvertConfigAsync();

    let remoteSlot = config.adSlots.find((i) => i.code == code);
    console.log(`🔍 [findAdSlotWithCodeAsync] 远程配置中查找结果:`, remoteSlot);

    if (isStrict && !remoteSlot) {
      console.log(
        `❌ [findAdSlotWithCodeAsync] 严格模式且远程配置中未找到 "${code}" → 返回 null`,
      );
      return null;
    }

    const ext_configs = getExtConfigs();
    const localSame = ext_configs.find((i) => i.code == code) || null;
    console.log(`🔍 [findAdSlotWithCodeAsync] 本地同 code 查找结果:`, localSame);

    // 远程有 → 以远程为底；远程无 → 空壳，后续用本地 / 默认类别补
    let adSlot = remoteSlot
      ? JSON.parse(JSON.stringify(remoteSlot))
      : { code };

    // type：远程 > 本地同 code > 调用方传入的 code 类别(hintType) > 1
    let type = Number(
      adSlot.type != null && adSlot.type !== ""
        ? adSlot.type
        : localSame && localSame.type != null && localSame.type !== ""
          ? localSame.type
          : hintType != null && hintType !== ""
            ? hintType
            : 1,
    );
    if (!Number.isFinite(type) || type <= 0) {
      type = 1;
    }
    adSlot.type = type;

    // 填充源选择
    // 1) 有本地同 code → 用本地补远程缺口
    // 2) 远程、本地同 code 都没有 → 按该 code 的 type 类别套用默认配置
    //    （1 default_reward / 2 default_interstitial / 4 default_native /
    //      6 default_game_native / 7 default_grid）
    // 3) 仅有远程、无本地同 code → 仍按 type 用默认类别补 adUnitId 等
    let ext_config;
    if (localSame) {
      ext_config = localSame;
      console.log(`✅ [findAdSlotWithCodeAsync] 使用本地同 code 配置`);
    } else if (!remoteSlot) {
      ext_config = getDefaultConfigByType(type) || {};
      // 都没有该 code：以默认类别配置为底，保留业务 code / type
      adSlot = {
        ...JSON.parse(JSON.stringify(ext_config)),
        code,
        type,
      };
      console.log(
        `🔧 [findAdSlotWithCodeAsync] 远程与本地均无 code="${code}"，按 type=${type} 使用默认类别配置:`,
        ext_config,
      );
    } else {
      ext_config = getDefaultConfigByType(type) || {};
      console.log(
        `🔧 [findAdSlotWithCodeAsync] 本地无同 code，按 type=${type} 用默认类别补齐:`,
        ext_config,
      );
    }

    adSlot.type = type;
    adSlot.desc = adSlot.desc || ext_config.adPlacementName || "";
    adSlot.adUnitId = resolveAdUnitId(adSlot, ext_config, code);

    // 小游戏 CustomAd 特有字段：远程未配则用本地/默认
    if (adSlot.adIntervals === undefined && ext_config.adIntervals !== undefined) {
      adSlot.adIntervals = ext_config.adIntervals;
    }
    if (adSlot.autoOffTime === undefined && ext_config.autoOffTime !== undefined) {
      adSlot.autoOffTime = ext_config.autoOffTime;
    }
    // 插屏 autoOffTime：不配默认 0（是否真正启用还要看 isRiskControl）
    if (+adSlot.type === 2) {
      adSlot.autoOffTime = Number.isFinite(+adSlot.autoOffTime)
        ? +adSlot.autoOffTime
        : 0;
    }

    // 远程 + 本地都未配时的兜底默认值
    if (+adSlot.type === 6 || +adSlot.type === 7 || +adSlot.type === 4) {
      if (
        adSlot.adIntervals === undefined ||
        adSlot.adIntervals === null ||
        adSlot.adIntervals === ""
      ) {
        adSlot.adIntervals = 30;
      } else {
        adSlot.adIntervals = Math.max(+adSlot.adIntervals || 30, 30);
      }
    }

    console.log(
      `🔧 [findAdSlotWithCodeAsync] 基础属性设置: type=${adSlot.type}, adUnitId=${adSlot.adUnitId}`,
    );

    //未设置默认为5s（定时插槽测试）
    adSlot.delay = Number.isFinite(adSlot.delay) ? adSlot.delay : 5;
    // interval：远程未配则用本地/默认；都未配默认 10s
    if (!Number.isFinite(adSlot.interval) && Number.isFinite(ext_config.interval)) {
      adSlot.interval = ext_config.interval;
    }
    adSlot.interval = Number.isFinite(adSlot.interval)
      ? Math.max(adSlot.interval, 1)
      : 10;
    adSlot.times = Number.isFinite(adSlot.times) ? adSlot.times : 1;

    adSlot.isClosed = adSlot.isClosed === true || !hasAdUnitId(adSlot.adUnitId);

    // style：customStyle > 远程 > 本地/默认
    if (customStyle) {
      adSlot.style = {
        ...(ext_config.style || {}),
        ...(adSlot.style || {}),
        ...customStyle,
      };
    } else if (!adSlot.style && ext_config.style) {
      adSlot.style = ext_config.style;
    }

    if (!adSlot.adUnitId) {
      console.warn(
        `⚠️ [findAdSlotWithCodeAsync] adUnitId 为空 - code: "${code}"，isClosed 将为 true`,
      );
    }

    console.log(
      `✅ [findAdSlotWithCodeAsync] 最终结果:`,
      JSON.stringify(adSlot, null, 2),
    );
    return adSlot;
  }
  /**
   * @description
   * 广告总开关
   * @returns {Boolean} true为全局关闭广告
   */
  async isClosedAsync() {
    let config = await this.getAdvertConfigAsync();

    return config && config.isClosed == true;
  }

  /**
   * @description
   * 记录小程序启动时间，开屏广告首次展示以此刻开始计时，30s后才能展示
   */
  appLaunch() {
    console.log("🚀 [AD Trace] appLaunch 触发");
    if (this._initialized && this.adManager) {
      let scene = deploy.getScene();
      console.log(`🚀 [AD Trace] appLaunch: 调用 adManager.appLaunch, scene = ${scene}`);
      this.adManager.appLaunch(scene);
    } else {
      console.warn("⚠️ [AD Trace] appLaunch: AD 还未初始化");
    }
  }

  /**
   * #@description
   * 小程序展示时，激活定时任务 请放入App.vue中的onShow
   */
  appShow() {
    if (this._initialized && this.adManager) {
      this.adManager.appShow();
    } else {
      console.warn("⚠️ [AD] appShow: AD 还未初始化");
    }
  }

  /**
   * @description
   * 小程序隐藏时，暂停定时任务 请放入App.vue中的onHide
   */
  appHide() {
    if (this._initialized && this.adManager) {
      this.adManager.appHide();
    } else {
      console.warn("⚠️ [AD] appHide: AD 还未初始化");
    }
  }

  /**
   * @description
   * 直接调用广告展示，异步方法，需判断服务端开关，返回true or false
   * 后端可控制code的广告类型
   * 对于不同的广告类型，某些回调不会触发，比如interstitial时，onClose不会触发
   *
   * 支持两种调用方式：
   * 1. show(code, callbacks) - 传统方式，从远程/本地配置获取广告设置
   * 2. show({adUnitId, type, code}, callbacks) - 新方式，直接使用传入的配置
   *
   * @param {String|Object} codeOrConfig - 广告位代码（第一种方式）或配置对象（第二种方式）
   * @param {Object} callbacks - 回调函数对象
   */
  async show(codeOrConfig, callbacks) {
    console.log("🚀 [AD Trace] show 触发", typeof codeOrConfig === 'object' ? "[配置模式]" : `[代码位模式: ${codeOrConfig}]`);
    // 如果未初始化，等待Deploy准备就绪后自动初始化
    if (!this._initialized) {
      console.log(
        "🔄 [AD.show] AD 未初始化，等待Deploy准备就绪...",
      );
      try {
        // 等待Deploy准备就绪
        await deploy.readyAsync();

        // 如果仍未初始化，说明Deploy中的初始化逻辑可能有问题，手动初始化
        if (!this._initialized) {
          console.log(
            "🔧 [AD.show] Deploy已就绪但AD仍未初始化，尝试手动初始化...",
          );
          this.init();
        }

        console.log("✅ [AD.show] 等待初始化完成");
      } catch (error) {
        console.error("❌ [AD.show] 等待初始化失败:", error);
        if (callbacks && callbacks.onError) {
          callbacks.onError(
            new Error("AD 初始化失败: " + error.message),
          );
        }
        return;
      }
    }

    // 检查 adManager 是否存在
    if (!this.adManager) {
      console.error("❌ [AD.show] adManager 不存在");
      if (callbacks && callbacks.onError) {
        callbacks.onError(new Error("adManager 不存在，请检查初始化状态"));
      }
      return;
    }

    // 检测调用方式
    // 1) 完整直配：code + type + adUnitId
    // 2) 配置对象：至少有 code（可带 type/style，adUnitId 可省略 → 走远程/本地合并再覆盖）
    // 3) 字符串 code
    if (typeof codeOrConfig === "object" && codeOrConfig !== null) {
      const hasCode = !!codeOrConfig.code;
      const hasType =
        codeOrConfig.type !== undefined &&
        codeOrConfig.type !== null &&
        codeOrConfig.type !== "";
      const hasUnit = hasAdUnitId(codeOrConfig.adUnitId);

      if (hasCode && hasType && hasUnit) {
        return await this._showWithDirectConfig(codeOrConfig, callbacks);
      }
      if (hasCode) {
        return await this._showWithRemoteConfig(
          codeOrConfig.code,
          callbacks,
          codeOrConfig,
        );
      }
      console.error("❌ [AD.show] 配置对象缺少 code");
      if (callbacks && callbacks.onError) {
        callbacks.onError(new Error("The config.code is empty"));
      }
      return;
    }

    return await this._showWithRemoteConfig(codeOrConfig, callbacks);
  }

  /**
   * @description
   * 第一种调用方式：传统方式，从远程/本地配置获取广告设置
   * @param {String} code - 广告位代码
   * @param {Object} callbacks - 回调函数对象
   * @param {Object} [overrides] - 调用时传入的覆盖项（如 style / type / interval）
   */
  async _showWithRemoteConfig(code, callbacks, overrides = null) {
    console.log(`🚀 [AD Trace] _showWithRemoteConfig 触发 - code: "${code}"`);

    if (!code) {
      console.log("❌ [AD Trace] _showWithRemoteConfig 失败: code 为空");
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(callbacks, new Error("The 'code' is empty"));
      return;
    }

    //全局开关
    if (await this.isClosedAsync()) {
      console.log("❌ [AD Trace] _showWithRemoteConfig 失败: 全局开关已关闭");
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(
          callbacks,
          new Error("The global config is closed"),
        );
      return;
    }

    // 样式优先级：overrides.style > callbacks.style
    const customStyle =
      (overrides && overrides.style) ||
      (callbacks && callbacks.style) ||
      null;
    if (callbacks && callbacks.style) {
      // 从callbacks中移除style，避免传递给广告回调
      const { style, ...cleanCallbacks } = callbacks;
      callbacks = cleanCallbacks;
    }

    let config = await this.getAdvertConfigAsync();
    const hintType =
      overrides &&
      overrides.type !== undefined &&
      overrides.type !== null &&
      overrides.type !== ""
        ? overrides.type
        : null;
    let adSlot = await this.findAdSlotWithCodeAsync(
      code,
      false,
      customStyle,
      hintType,
    );

    // 用调用方传入的字段覆盖合并结果（不要求 adUnitId）
    if (overrides && typeof overrides === "object") {
      const prevType = adSlot.type;
      if (overrides.type !== undefined && overrides.type !== null && overrides.type !== "") {
        adSlot.type = Number(overrides.type);
      }
      if (hasAdUnitId(overrides.adUnitId)) {
        adSlot.adUnitId = String(overrides.adUnitId).trim();
        adSlot.isClosed = adSlot.isClosed === true ? true : false;
      } else if (
        Number(adSlot.type) !== Number(prevType) &&
        !hasAdUnitId(adSlot.adUnitId)
      ) {
        // type 被覆盖且仍无 adUnitId：按新 type 再从本地/默认类别补一次
        const fill = getDefaultConfigByType(adSlot.type);
        adSlot.adUnitId = resolveAdUnitId(adSlot, fill, code);
      }
      if (overrides.style && typeof overrides.style === "object") {
        adSlot.style = { ...(adSlot.style || {}), ...overrides.style };
      }
      if (overrides.interval !== undefined) {
        adSlot.interval = Number(overrides.interval);
      }
      if (overrides.adIntervals !== undefined) {
        adSlot.adIntervals = Number(overrides.adIntervals);
      }
      if (overrides.autoOffTime !== undefined) {
        adSlot.autoOffTime = Number(overrides.autoOffTime);
      }
      if (overrides.delay !== undefined) {
        adSlot.delay = Number(overrides.delay);
      }
      if (overrides.popPath !== undefined && overrides.popPath !== null && overrides.popPath !== "") {
        adSlot.popPath = String(overrides.popPath);
      }
      // 覆盖后重新判定关闭态
      adSlot.isClosed = adSlot.isClosed === true || !hasAdUnitId(adSlot.adUnitId);
    }

    console.log(
      "📋 [AD._showWithRemoteConfig] ad.show",
      code,
      adSlot,
    );

    if (!adSlot) {
      console.log(`❌ [AD Trace] _showWithRemoteConfig 失败: 未找到广告位 "${code}" 配置`);
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(
          callbacks,
          new Error("Not found the adSlot config"),
        );
      return;
    }

    //独立开关
    if (adSlot.isClosed) {
      console.log(`❌ [AD Trace] _showWithRemoteConfig 失败: 广告位 "${code}" 已关闭`);
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(callbacks, new Error("The 'code' is closed"));
      return;
    }

    return await this._executeAdShow(adSlot, callbacks);
  }

  /**
   * @description
   * 第二种调用方式：直接使用传入的配置对象，不从远程/本地获取配置
   * @param {Object} config - 直接配置对象 {adUnitId, type, code}
   * @param {Object} callbacks - 回调函数对象
   */
  async _showWithDirectConfig(config, callbacks) {
    console.log(
      `🎯 [AD._showWithDirectConfig] 开始显示广告 - 直接配置:`,
      config,
    );

    // 验证必要参数
    if (!config.code) {
      // console.log(`❌ [AD._showWithDirectConfig] config.code为空`);
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(
          callbacks,
          new Error("The config.code is empty"),
        );
      return;
    }

    if (!config.adUnitId) {
      // console.log(`❌ [AD._showWithDirectConfig] config.adUnitId为空`);
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(
          callbacks,
          new Error("The config.adUnitId is empty"),
        );
      return;
    }

    if (!config.type) {
      // console.log(`❌ [AD._showWithDirectConfig] config.type为空`);
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(
          callbacks,
          new Error("The config.type is empty"),
        );
      return;
    }

    //全局开关检查（小游戏环境使用开发者配置时跳过）
    const advertConfig = await this.getAdvertConfigAsync();
    if (!advertConfig.useDevConfig && (await this.isClosedAsync())) {
      // console.log(`❌ [AD._showWithDirectConfig] 全局开关关闭`);
      callbacks &&
        callbacks.onError &&
        callbacks.onError.call(
          callbacks,
          new Error("The global config is closed"),
        );
      return;
    }

    if (advertConfig.useDevConfig) {
      console.log(
        "🎮 [AD._showWithDirectConfig] 小游戏环境，跳过全局开关检查，使用开发者配置",
      );
    }

    // 构造adSlot对象，直接使用传入的配置
    const adSlot = {
      code: config.code,
      type: Number(config.type),
      adUnitId: config.adUnitId,
      desc: config.desc || "",
      isClosed: false, // 直接配置模式下不检查关闭状态
      // 其他可选参数
      multiton: config.multiton,
      multitonRewardTimes: config.multitonRewardTimes,
      multitonRewardMsg: config.multitonRewardMsg,
      progressTip: config.progressTip,
      style: config.style,
      adIntervals: config.adIntervals,
      // 关闭后 interval 秒重新拉起（type 4/6/7）
      interval: config.interval,
      autoOffTime: config.autoOffTime,
      // 🔧 新增：哔哩哔哩平台场景ID支持
      sceneId: config.sceneId,
      popPath: config.popPath,
    };

    console.log(
      "📋 [AD._showWithDirectConfig] 构造的adSlot:",
      JSON.stringify(adSlot, null, 2),
    );

    return await this._executeAdShow(adSlot, callbacks);
  }

  /**
   * @description
   * 执行广告显示的通用逻辑
   * @param {Object} adSlot - 广告位配置对象
   * @param {Object} callbacks - 回调函数对象
   */
  async _executeAdShow(adSlot, callbacks) {
    console.log(`🚀 [AD Trace] _executeAdShow 触发 - adSlot.code: "${adSlot.code}", type: ${adSlot.type}`);

    // 检查 adSlot 参数
    if (!adSlot) {
      console.error("❌ [AD Trace] _executeAdShow 失败: adSlot 参数为空");
      if (callbacks && callbacks.onError) {
        callbacks.onError(new Error("adSlot 参数为空"));
      }
      return;
    }

    // 检查 adManager 是否存在
    if (!this.adManager) {
      console.error("❌ [AD Trace] _executeAdShow 失败: adManager 不存在");
      if (callbacks && callbacks.onError) {
        callbacks.onError(new Error("adManager 不存在"));
      }
      return;
    }

    let adUnitId = adSlot.adUnitId;

    const code = adSlot.code;
    let config = await this.getAdvertConfigAsync();
    // 统一成数字，避免远程下发字符串 "7" 时 switch 严格相等匹配失败
    const adType = Number(adSlot.type);
    // AD.show({ popPath }) 优先；未传默认 AUTO_PULL（定时自动拉起等同默认）
    const popPath =
      adSlot.popPath !== undefined &&
      adSlot.popPath !== null &&
      adSlot.popPath !== ""
        ? String(adSlot.popPath)
        : "AUTO_PULL";

    switch (adType) {
      case 2: {
        // 不配默认 0（不自动关闭）；仅广告用户（!isRiskControl）且 autoOffTime > 0 时开启
        const rawAutoOff = Number.isFinite(+adSlot.autoOffTime) ? +adSlot.autoOffTime : 0;
        const autoOffTime =
          !config.isRiskControl && rawAutoOff > 0 ? rawAutoOff : 0;
        if (rawAutoOff > 0 && config.isRiskControl) {
          console.log(
            `ℹ️ [AD] 插屏 autoOffTime=${rawAutoOff} 已配置，但当前为风控用户(isRiskControl=true)，不自动关闭`,
          );
        } else if (autoOffTime > 0) {
          console.log(`⏰ [AD] 插屏将在展示成功后 ${autoOffTime} 秒自动关闭`);
        }
        let params = {
          adUnitId: adUnitId,
          adType: 2,
          autoOffTime: autoOffTime,
          popPath,
        };
        this.adManager.showInterstitial(code, params, callbacks);
        return;
      }

      case 4: {
        // 小程序原生模板（Vue <ad-custom>）
        let params = {
          adUnitId: adUnitId,
          adType: 4,
          adCode: code, // 传递广告代码位
          popPath,
        };
        // 添加原生模板广告特有的配置
        // 设置style默认值
        let style = adSlot.style || {};
        params.style = {
          left: style.left !== undefined ? style.left : 0,
          top: style.top !== undefined ? style.top : 0,
          width: style.width !== undefined ? style.width : "100%",
          fixed: style.fixed !== undefined ? style.fixed : true,
        };
        // 设置adIntervals默认值，最小30秒
        if (adSlot.adIntervals !== undefined) {
          params.adIntervals = Math.max(adSlot.adIntervals, 30);
        } else {
          params.adIntervals = 30;
        }

        // 增强错误处理：包装回调函数，添加重试机制
        const enhancedCallbacks = {
          onShow: callbacks && callbacks.onShow,
          onClose: callbacks && callbacks.onClose,
          onHide: callbacks && callbacks.onHide,
          onError: (error) => {
            // 如果错误是组件未找到，尝试延迟重试一次
            if (
              error &&
              error.message &&
              error.message.includes("未找到广告组件")
            ) {
              console.log(
                "[AD] 检测到组件未找到错误，尝试延迟重试...",
              );

              setTimeout(() => {
                try {
                  this.adManager.showNative(code, params, {
                    onShow: callbacks && callbacks.onShow,
                    onClose: callbacks && callbacks.onClose,
                    onHide: callbacks && callbacks.onHide,
                    onError: callbacks && callbacks.onError,
                  });
                } catch (retryError) {
                  if (callbacks && callbacks.onError) {
                    callbacks.onError(retryError);
                  }
                }
              }, 200);

              return;
            }

            if (callbacks && callbacks.onError) {
              callbacks.onError(error);
            }
          },
        };

        this.adManager.showNative(code, params, enhancedCallbacks);
        return;
      }

      case 6: {
        // 小游戏原生模板 wx.createCustomAd（type=6，默认位 default_game_native）
        const style = adSlot.style || {};
        const params = {
          adUnitId,
          adType: 6,
          adCode: code || "default_game_native",
          popPath,
          // 用户关闭后 interval 秒重新拉起（与小程序 native 一致）
          interval: Number.isFinite(adSlot.interval) ? adSlot.interval : 0,
          // 远程/本地未配 adIntervals → 默认 30
          adIntervals: Math.max(
            adSlot.adIntervals !== undefined && adSlot.adIntervals !== null && adSlot.adIntervals !== ""
              ? +adSlot.adIntervals || 30
              : 30,
            30,
          ),
          style: {
            left: style.left !== undefined ? Number(style.left) || 0 : 0,
            top: style.top !== undefined ? Number(style.top) || 0 : 0,
            width: style.width !== undefined ? Number(style.width) || 300 : 300,
            fixed: style.fixed !== undefined ? !!style.fixed : true,
          },
        };
        console.log(`📋 [AD] dispatch type=6 → showCustom (埋点 FLOW) code=${code}`);
        this.adManager.showCustom(code || "default_game_native", params, callbacks);
        return;
      }

      case 7: {
        // 小游戏格子广告：与 type=6 共用 wx.createCustomAd（style 仅 left/top/width/fixed）
        const style = adSlot.style || {};
        const params = {
          adUnitId,
          adType: 7,
          adCode: code || "default_grid",
          popPath,
          interval: Number.isFinite(adSlot.interval) ? adSlot.interval : 0,
          adIntervals: Math.max(
            adSlot.adIntervals !== undefined && adSlot.adIntervals !== null && adSlot.adIntervals !== ""
              ? +adSlot.adIntervals || 30
              : 30,
            30,
          ),
          style: {
            left: style.left !== undefined ? Number(style.left) || 0 : 0,
            top: style.top !== undefined ? Number(style.top) || 0 : 0,
            width: style.width !== undefined ? Number(style.width) || 300 : 300,
            fixed: style.fixed !== undefined ? !!style.fixed : true,
          },
        };
        console.log(`📋 [AD] dispatch type=7 → showGrid (埋点 GRID) code=${code}`);
        this.adManager.showGrid(code || "default_grid", params, callbacks);
        return;
      }

      case 1:
      default: {
        //激励视频，支持更多功能
        let params = {
          adUnitId: adUnitId,
          adType: 1,
          popPath,
        };
        if (config.isRiskControl === false && adSlot.multiton) {
          params.multiton = adSlot.multiton;
        }
        adSlot.multitonRewardTimes &&
          (params.multitonRewardTimes = adSlot.multitonRewardTimes);
        adSlot.multitonRewardMsg &&
          (params.multitonRewardMsg = adSlot.multitonRewardMsg);
        adSlot.progressTip && (params.progressTip = adSlot.progressTip);
        // 🔧 新增：哔哩哔哩平台场景ID支持
        adSlot.sceneId && (params.sceneId = adSlot.sceneId);
        this.adManager.showReward(code, params, callbacks);
        return;
      }
    }
  }

  /**
   * @description
   * 隐藏原生模板 / 小游戏 CustomAd / GridAd
   * @param {String} code 广告代码位
   * @param {Object} [option] 可选 { adUnitId, type }
   */
  async hide(code, option = {}) {
    if (!code && !option.adUnitId) {
      console.warn("AD.hide: code is empty");
      return;
    }

    try {
      await this.ensureInitialized();
      const type = option.type;
      const adUnitId = option.adUnitId;

      if (type === 6 || type === "custom") {
        await this.adManager.hideCustom(code, { adUnitId, adCode: code });
        return;
      }
      if (type === 7 || type === "grid") {
        await this.adManager.hideGrid(code, { adUnitId, adCode: code });
        return;
      }

      // 小游戏默认优先尝试 custom/grid hide
      if (deploy.isMinigame && deploy.isMinigame()) {
        try {
          await this.adManager.hideCustom(code, { adUnitId, adCode: code });
        } catch (e) {}
        try {
          await this.adManager.hideGrid(code, { adUnitId, adCode: code });
        } catch (e) {}
      }

      // 小程序原生模板：尝试 GlobalManager 已注册组件
      if (globalAdManager && typeof globalAdManager.hasComponentSystem === "function" && globalAdManager.hasComponentSystem()) {
        try {
          if (typeof globalAdManager.hideNativeAdByCode === "function") {
            globalAdManager.hideNativeAdByCode(code);
            return;
          }
        } catch (e) {
          console.warn("AD.hide GlobalManager 失败:", e);
        }
      }

      console.warn("AD.hide: 未找到可隐藏的广告实例", code);
    } catch (error) {
      console.error("隐藏广告失败:", error);
    }
  }

  /**
   * @description
   * 注册插槽，一般放在onShow中，在onHide中注销
   * 注意：如果后端未下发对应code的配置，视为关闭状态，注册将无效
   * @param {String} code - 广告位代码
   * @param {Object} callbacks - 回调函数
   * @param {Object} options - 可选配置项 { style: {...} }
   */
  async registerAdSlot(code, callbacks, options) {
    // console.log(`🎯 [AD] registerAdSlot 开始 - code: "${code}"`);
    // console.log(`📋 [AD] 传入参数: code="${code}", callbacks=${callbacks ? 'object' : 'undefined'}, options=${options ? 'object' : 'undefined'}`);

    if (!code) {
      // console.log("❌ [AD] registerAdSlot 失败: code为空 → RETURN 1");
      return;
    }

    // 先存储callbacks，无论是否能创建定时任务都保存起来
    if (callbacks && typeof callbacks === "object") {
      console.log(
        "🔄 [AD] 存储事件处理器:",
        code,
        Object.keys(callbacks),
      );
      preRegisteredCallbacks.set(code, callbacks);
      // console.log("✅ [AD] 事件处理器已存储，继续检查是否可以创建定时任务");
    }

    // 提取传入的style
    const customStyle = options && options.style ? options.style : null;
    if (customStyle) {
      // console.log(`🎨 [AD] 传入自定义样式:`, JSON.stringify(customStyle, null, 2));
    }

    // console.log("✅ [AD] 参数检查通过，继续执行...");

    // console.log("🔍 [AD] 检查全局开关...");
    const globalClosed = await this.isClosedAsync();
    // console.log(`📊 [AD] 全局开关状态: ${globalClosed}`);
    if (globalClosed) {
      // console.log("❌ [AD] registerAdSlot 失败: 全局广告开关已关闭 → RETURN 3");
      return;
    }
    // console.log("✅ [AD] 全局开关正常");

    //定时类广告开关
    // console.log("🔍 [AD] 检查定时广告开关...");
    let config = await this.getAdvertConfigAsync();
    // console.log(`📊 [AD] 获取配置:`, JSON.stringify(config, null, 2));
    // console.log(`📊 [AD] isAdTimmingClosed状态: ${config.isAdTimmingClosed}`);
    if (config.isAdTimmingClosed) {
      // console.log("❌ [AD] registerAdSlot 失败: 定时广告开关已关闭 → RETURN 4");
      return;
    }
    // console.log("✅ [AD] 定时广告开关正常");

    let adSlot = await this.findAdSlotWithCodeAsync(code, true, customStyle);

    if (!adSlot) {
      console.log(`❌ [AD Trace] registerAdSlot 失败: 未找到广告位 "${code}" 配置`);
      return;
    }

    //独立开关
    if (adSlot.isClosed) {
      console.log(`❌ [AD Trace] registerAdSlot 失败: 广告位 "${code}" 已关闭`);
      return;
    }

    //有重复在的 不报错，直接返回
    if (handles.has(code)) {
      console.log(`⚠️ [AD Trace] registerAdSlot 跳过: 任务 "${code}" 已存在`);
      return;
    }


    //通用必要参数
    let as = {
      code: adSlot.code,
      type: adSlot.type,
      delay: adSlot.delay,
      interval: adSlot.interval,
      times: adSlot.times,
      params: {
        adUnitId: adSlot.adUnitId
      },
      callbacks,
    };

    // console.log("🔧 [AD] 构建任务参数:", JSON.stringify(as, null, 2));

    let handle;

    // console.log(`🎯 [AD] 广告类型: ${adSlot.type} (${adSlot.type === 2 ? '插屏广告' : '其他类型'})`);
    // console.log("🔄 [AD] 准备进入 switch 语句...");

    switch (Number(adSlot.type)) {
      case 2: {
        // console.log("✅ [AD] 匹配到插屏广告类型 (case 2)");
        // console.log("🚀 [AD] 调用 registerTimingInterstitial...");
        // console.log("📋 [AD] 传递给 AdManager 的参数:", JSON.stringify(as, null, 2));
        // 不配默认 0；仅广告用户（!isRiskControl）且 autoOffTime > 0 时开启
        const rawAutoOff = Number.isFinite(+adSlot.autoOffTime) ? +adSlot.autoOffTime : 0;
        const autoOffTime =
          !config.isRiskControl && rawAutoOff > 0 ? rawAutoOff : 0;
        if (rawAutoOff > 0 && config.isRiskControl) {
          console.log(
            `ℹ️ [AD] 定时插屏 autoOffTime=${rawAutoOff} 已配置，但当前为风控用户(isRiskControl=true)，不自动关闭`,
          );
        }
        as.params.autoOffTime = autoOffTime;
        as.params.adType = 2;
        handle = this.adManager.registerTimingInterstitial(as);
        // console.log("✅ [AD] registerTimingInterstitial 完成, handle:", handle);
        // console.log("🎯 [AD] handle 类型:", typeof handle);
        break;
      }

      case 4: {
        // 原生模板广告定时注册
        // 添加原生模板广告特有的配置
        // 设置style默认值
        let style = adSlot.style || {};
        as.params.adType = 4;
        as.params.style = {
          left: style.left !== undefined ? style.left : 0,
          top: style.top !== undefined ? style.top : 0,
          width: style.width !== undefined ? style.width : "100%",
          fixed: style.fixed !== undefined ? style.fixed : true,
        };
        // 设置adIntervals默认值，最小30秒
        if (adSlot.adIntervals !== undefined) {
          as.params.adIntervals = Math.max(adSlot.adIntervals, 30);
        } else {
          as.params.adIntervals = 30;
        }
        handle = this.adManager.registerTimingNative(as);
        break;
      }

      case 6: {
        // 小游戏 CustomAd：展示一次，关闭后 interval 秒重拉由 AdLoader 处理
        {
          const style = adSlot.style || {};
          as.params.adType = 6;
          as.params.adCode = as.code;
          as.params.style = {
            left: style.left !== undefined ? Number(style.left) || 0 : 0,
            top: style.top !== undefined ? Number(style.top) || 0 : 0,
            width: style.width !== undefined ? Number(style.width) || 300 : 300,
            fixed: style.fixed !== undefined ? !!style.fixed : true,
          };
          as.params.adIntervals = Math.max(
            adSlot.adIntervals !== undefined ? +adSlot.adIntervals || 30 : 30,
            30,
          );
          as.params.interval = Number.isFinite(adSlot.interval) ? adSlot.interval : 0;
          this.adManager.showCustom(as.code, as.params, as.callbacks);
          handle = { code: as.code, type: 6 };
        }
        break;
      }

      case 7: {
        // 小游戏格子：与 type=6 共用 createCustomAd；关闭后 interval 重拉由 AdLoader 处理
        {
          const style = adSlot.style || {};
          as.params.adType = 7;
          as.params.adCode = as.code;
          as.params.style = {
            left: style.left !== undefined ? Number(style.left) || 0 : 0,
            top: style.top !== undefined ? Number(style.top) || 0 : 0,
            width: style.width !== undefined ? Number(style.width) || 300 : 300,
            fixed: style.fixed !== undefined ? !!style.fixed : true,
          };
          as.params.adIntervals = Math.max(
            adSlot.adIntervals !== undefined ? +adSlot.adIntervals || 30 : 30,
            30,
          );
          as.params.interval = Number.isFinite(adSlot.interval) ? adSlot.interval : 0;
          this.adManager.showGrid(as.code, as.params, as.callbacks);
          handle = { code: as.code, type: 7 };
        }
        break;
      }

      case 1:
      default: {
        // console.log(`📊 [AD] 匹配到激励视频类型 (case 1 或 default), type=${adSlot.type}`);
        //adConfig为true时（非暴力广告），不开启激励视频插槽
        // console.log(`📊 [AD] adConfig检查: ${config.isRiskControl}`);

        if (config.isRiskControl === true) {
          // console.log("❌ [AD] registerAdSlot 失败: adConfig=true，不开启激励视频插槽 → RETURN 8");
          return;
        }

        //激励视频追加额外功能
        // console.log("🎁 [AD] 配置激励视频额外功能...");
        as.params.adType = 1;
        if (config.isRiskControl === false && adSlot.multiton) {
          as.params.multiton = adSlot.multiton;
        }
        adSlot.multitonRewardTimes &&
          (as.params.multitonRewardTimes = adSlot.multitonRewardTimes);
        adSlot.multitonRewardMsg &&
          (as.params.multitonRewardMsg = adSlot.multitonRewardMsg);
        adSlot.progressTip && (as.params.progressTip = adSlot.progressTip);
        // 🔧 新增：哔哩哔哩平台场景ID支持
        adSlot.sceneId && (as.params.sceneId = adSlot.sceneId);
        // console.log("🚀 [AD] 调用 registerTimingReward...");
        handle = this.adManager.registerTimingReward(as);
        // console.log("✅ [AD] registerTimingReward 完成, handle:", handle);
        break;
      }
    }

    // console.log("🔄 [AD] switch 语句执行完成");
    // console.log(`📊 [AD] 获得的 handle:`, handle);
    // console.log(`📊 [AD] handle 类型: ${typeof handle}`);
    // console.log(`📊 [AD] handle 是否为空: ${handle == null}`);

    if (!handle) {
      // console.log("❌ [AD] registerAdSlot 失败: handle为空，可能switch没有匹配到正确的case → RETURN 9");
      return;
    }

    // console.log(`🔧 [AD] 保存 handle 到 handles Map...`);
    handles.set(code, handle);
    // console.log(`✅ [AD] registerAdSlot 成功完成 - code: "${code}", handle已保存`);
    // console.log(`📊 [AD] handles Map 大小: ${handles.size}`);
  }

  /**
   * @description
   * 注销插槽，一般放在onHide中，onShow中完成注册
   * @param {Object} code
   * @return {Boolean} true表示找到并注销成功
   */
  unRegisterAdSlot(code) {
    if (!code) {
      return false;
    }

    // console.log("ad.unRegisterAdSlot", code);

    // 新增：清理预注册的事件处理器
    if (preRegisteredCallbacks.has(code)) {
      // console.log("[AD] 清理预注册事件处理器:", code);
      preRegisteredCallbacks.delete(code);
    }

    if (handles.has(code)) {
      let handle = handles.get(code);
      this.adManager.unRegisterTimingAD(handle);
      return handles.delete(code);
    }
    return false;
  }

  /**
   * @description
   * 获取预注册的事件处理器
   * @param {String} code 广告代码位
   * @returns {Object|null} 事件处理器对象
   */
  getPreRegisteredCallbacks(code) {
    return preRegisteredCallbacks.get(code) || null;
  }

  /**
   * @description
   * 检查是否有预注册的事件处理器
   * @param {String} code 广告代码位
   * @returns {Boolean}
   */
  hasPreRegisteredCallbacks(code) {
    return preRegisteredCallbacks.has(code);
  }
}

/**
 * @description
 * 广告插槽控制器
 * 根据后端数据控制每个插槽的广告表现
 */
let ad = new AD();

export { AD };
export default ad;
