const LIB_VERSION = "1.0.17";
import http from "./fbiCoreHttp.js";
import device from "./fbiDevice.js";
import login from "./fbiCoreLogin.js";
import comfortable from "./fbiCoreComfortable/fbiCoreCFIndex.js";
import { applyPageUrlToProperties } from "./fbiCorePageUrl.js";
import uniCompatible from "../../utils/utilsComfortable/uniCompatible.js";

/**
 * @description
 * SDK实现
 * 内部依赖login登录，获取accessToken
 */
class FBISDKCore {
	constructor(
		app_id,
		app_name,
		app_version,
		enviroment,
		runtimeConfig
	) {
		this.app_id = app_id;
		this.app_name = app_name || "";
		this.app_version = app_version ?
			app_version :
			runtimeConfig.app_version || "";
		this.enviroment = enviroment || "production";
		this.api = http.enviroment(this.enviroment);
		this.runtimeConfig = runtimeConfig || {};

		//签名和登录 都需要单列执行
		this.__attribution_cache__ = null;
		this.__attribution_promise__ = null;
		this.__login_cache__ = null;
		this.__login_promise__ = null;
		this.__adConfig_cache__ = null;
		this.__adConfig_promise__ = null;
		this.__deviceInfo = null;
		this.__info__ = null;
		this.anonymous_id = null;
		this.__login_params__ = {};
	}

	/**
	 * 获取或生成匿名 ID
	 */
	async getAnonymousIdAsync() {
		if (this.anonymous_id) {
			return this.anonymous_id;
		}

		let storedId = "";
		try {
			storedId = await comfortable.getStorageAsync("fbi_anonymous_id");
		} catch (e) {
			console.warn("⚠️ [FBISDKCore] 获取 anonymous_id 失败:", e);
		}

		if (!storedId) {
			storedId = getUUID();
			try {
				await comfortable.setStorageAsync("fbi_anonymous_id", storedId);
			} catch (e) {
				console.warn("⚠️ [FBISDKCore] 保存 anonymous_id 失败:", e);
			}
		}

		this.anonymous_id = storedId;
		return this.anonymous_id;
	}

	/**
	 * @description
	 * 设置启动参数延时回调函数，待初始化时调用
	 * @param {Object} func
	 */
	setLaunchOptions(func) {
		this.__launchOptionsFunction = func;
	}
	
	// 上报截图/录屏用户（Deploy 对外入口）
	riskControlListen() {
		return this.riskControlListenAsync();
	}

	riskControlListenAsync() {
		const params = this._getRiskControlParams();
		return comfortable.riskControlListenAsync(this.enviroment, params).then((res) => {
			console.log("[riskControlListen]", res);
			return res;
		}).catch((err) => {
			console.log("riskControlListenAsync-err--res", err);
			const msgStr = String(err?.message || err || "").split("\n    at")[0];
			this.trackAsync("$AppError", {
				name: 'riskControlListen',
				reason: msgStr
			});
			throw err;
		});
	}

	_getRiskControlParams() {
		const base =
			(this.__login_params__ && Object.keys(this.__login_params__).length > 0)
				? this.__login_params__
				: this.launchOptions
					? { ...this.runtimeConfig, ...this.launchOptions }
					: { ...this.runtimeConfig };

		return {
			...base,
			appId: this.app_id || base.appId,
			userId: this.userId || this.__login_cache__?.userId || base.userId || "",
		};
	}

	/**
	 * 获取应用ID
	 */
	getAppId() {
		return this.app_id;
	}

	/**
	 * @description
	 * 初始化
	 * 返回归因信息
	 */
	async initAsync() {

		if (this.__attribution_cache__ != null) {
			// // console.log('✅ [FBISDKCore] 归因缓存已存在，直接返回:', this.__attribution_cache__);
			return this.__attribution_cache__;
		}

		// // console.log('📋 [FBISDKCore] 检查启动参数回调函数...');
		if (!(this.__launchOptionsFunction instanceof Function)) {
			console.error("❌ [FBISDKCore] 启动参数回调函数未设置");
			throw new Error("Please set the launchOptions callback function first");
		}

		// // console.log('📋 [FBISDKCore] 获取启动参数...');
		this.launchOptions = this.__launchOptionsFunction();
		// // console.log('✅ [FBISDKCore] 启动参数获取成功:', this.launchOptions);

		if (!this.launchOptions) {
			console.error("❌ [FBISDKCore] 启动参数回调函数返回空值");
			throw new Error(
				"The launchOptions callback function returned unexpected values",
			);
		}

		if (this.__attribution_promise__ == null) {
			// // console.log('📋 [FBISDKCore] 创建新的归因Promise');

			this.__attribution_promise__ = new Promise(async (resolve, reject) => {
				this.__login_params__ = {
					...this.runtimeConfig,
					...this.launchOptions
				};
				//完成登录
				let loginData = await login(
					this.app_id,
					this.enviroment, this.__login_params__,
				).catch((error) => reject(error));

				let {
					aid,
					channel
				} = this.launchOptions;

				// 巨量引擎-小程序事件回传接口
				if (channel != "xcx" && aid) this.api.startAccountAsync(this.launchOptions);

				try {
					let {
						accessToken,
						userId,
						openId,
						unionId,
						session_key,
						expireAt,
						createdDt
					} = loginData;
					this.__login_cache__ = loginData;
					this.userId = userId;
					this.openId = openId || "";
					this.unionId = unionId || "";
					this.session_key = session_key || "";

					this.__info__ = {
						appId: this.app_id,
						expireAt,
						openId,
						unionId,
						session_key,
						createdDt,
						userId,
						accessToken,
					};

					//返回归因信息
					resolve(this.__info__);
				} catch (error) {
					reject(error);
				}
			});
		}

		try {
			this.__attribution_cache__ = await this.__attribution_promise__;

			// console.log('✅ [FBISDKCore] SDK初始化完全成功！');
			// // console.log('📊 [FBISDKCore] 最终归因结果:', this.__attribution_cache__);

			// 用完解除引用，避免内存泄漏（启动参数已落到全局 __resolved_launch_options__）
			this.__launchOptionsFunction = null;
			// 与全局锁定值对齐，防止 init 快照落后于后续 setLaunchOptions
			const globalLaunch = uniCompatible.getResolvedLaunchOptions();
			if (globalLaunch) {
				this.launchOptions = { ...globalLaunch };
			}
			return this.__attribution_cache__;
		} catch (error) {
			console.error("❌ [FBISDKCore] SDK初始化失败:", error.message);
			// 失败时清掉 promise，允许重试；成功时保留 resolved promise 供并发调用复用
			this.__attribution_promise__ = null;
			throw error;
		}
	}

	/**
	 * @description
	 * 事件埋点
	 * @param {Object} event_name - 事件名
	 * @param {Object} params - 事件属性集
	 * @param {Boolean} isLogin - 是否登录
	 * @return{Promise}
	 */
	async trackAsync(event_name, properties, isLogin = true) {
		//等待归因完成
		if (isLogin) await this.initAsync();

		if (this.__adConfig_cache__) await this.adConfigAsync();
		console.log("this.__adConfig_cache__---->",this.__adConfig_cache__)

		properties = properties || {};

		const anonymousId = await this.getAnonymousIdAsync();
		const userId = this.__login_cache__?.userId || this.userId || "";
		const createdDt = this.__login_cache__?.createdDt || "";
		const adScene = this.__adConfig_cache__?.bucket || "";
		
		// 计算是否首日用户
		let isFirstDay = false;
		if (createdDt) {
			try {
				const createdDate = createdDt.split(" ")[0];
				const now = new Date();
				const year = now.getFullYear();
				const month = String(now.getMonth() + 1).padStart(2, "0");
				const day = String(now.getDate()).padStart(2, "0");
				const currentDate = `${year}-${month}-${day}`;
				isFirstDay = (currentDate === createdDate);
			} catch (e) {}
		}

		// 获取渠道等推广参数（优先全局锁定的启动参数，避免切页后掉回 xcx）
		const launchOpts =
			uniCompatible.getResolvedLaunchOptions() ||
			this.launchOptions ||
			{};
		const channel = launchOpts.channel || "xcx";
		const aid = launchOpts.aid || "";
		const csite = launchOpts.csite || "";

		// 宿主APP名
		let appName = "";
		try {
			if (typeof tt !== "undefined" && tt.getSystemInfoSync) {
				appName = tt.getSystemInfoSync().appName || "";
			} else if (typeof wx !== "undefined") {
				if (typeof wx.getAppBaseInfo === "function") {
					const baseInfo = wx.getAppBaseInfo() || {};
					appName = baseInfo.appName || baseInfo.host?.env || "";
				} else if (typeof wx.getSystemInfoSync === "function") {
					appName = wx.getSystemInfoSync().appName || "";
				}
			}
		} catch (e) {}

		const platform = await comfortable.getPlatform();
		const identityKey = platform === 'DY' ? '$identity_byte_mp_id' : '$identity_wechat_mp_id';

		let identities = {
			$identity_anonymous_id: anonymousId,
		};
		identities[identityKey] = anonymousId;

		const trackId = Number(
			String(getRandom()).slice(2, 5) +
			String(getRandom()).slice(2, 4) +
			String(Date.now()).slice(-4)
		);

		if (!this.__deviceInfo) {
			let deviceInfo = await device();
			this.__deviceInfo = deviceInfo;
		}
		let ops = {};
		try {
			// 统一走全局合并后的启动参数
			ops = uniCompatible.getLaunchOptionsSync() || {};
		} catch (e) {
			ops = {};
		}

		// 组装 SensorsData 规范的数据对象
		let sensorEvent = {
			distinct_id: userId || anonymousId,
			anonymous_id: anonymousId,
			lib: {
				$lib: platform,
				$lib_method: "SDK",
				$lib_version: LIB_VERSION,
			},
			properties: applyPageUrlToProperties({
				...this.__deviceInfo,
				$app_id: this.app_id,
				$app_version: this.app_version,
				isFirstDay,
				sourcePackageName: appName,
				$timezone_offset: new Date().getTimezoneOffset(),
				$lib: platform,
				$lib_version: LIB_VERSION,
				sourceAppend: csite,
				scene: String(
					launchOpts.scene ||
						ops.scene ||
						ops.query?.scene ||
						"",
				),
				analysis: {
					channel,
					formId: aid,
					adScene,
					scene: String(
						launchOpts.scene ||
							ops.scene ||
							ops.query?.scene ||
							"",
					),
					...(properties || {})
				}
			}),
			type: "track",
			event: event_name,
			time: Date.now(),
			identities: identities,
			_track_id: trackId
		};

		if (userId) {
			sensorEvent.user_id = userId;
		}

		if (event_name == "$Shield") {
			sensorEvent.properties.analysis['jumpUrl'] = sensorEvent.properties.$url_path
		}
		if(event_name == "$BucketStart" && adScene === ""){
			console.log("---不请求$BucketStart adScene为空---")
			return
		}

		try {
			await this.api.trackAsync(sensorEvent);
		} catch (e) {
			console.error(e);
		}
	}

	async trackAfterLoginAsync(event_name, properties) {
		return this.trackAsync(event_name, properties, false);
	}

	async requestAsync(options) {
		let method = options.method;
		let url = options.url;
		let data = options.data;
		return this.api.requestAsync(method, url, data);
	}

	async requestAfterLoginAsync(options) {
		let method = options.method;
		let url = options.url;
		let data = options.data;
		return this.api.requestAsync(method, url, data);
	}

	/**
	 * @description
	 * 加载广告配置信息
	 */
	async adConfigAsync() {
		// console.log("🔍 加载广告配置信息", this.__adConfig_cache__);
		if (this.__adConfig_cache__ != null) {
			return this.__adConfig_cache__;
		}

		await this.initAsync();

		if (this.__adConfig_promise__ == null) {
			this.__adConfig_promise__ = new Promise(async (resolve, reject) => {
				let deviceInfo = await device();
				this.__deviceInfo = deviceInfo;
				const osMatch = String(deviceInfo?.$os || "").match(/^([^-]+)/);
				let platform = (osMatch && osMatch[1]) || "unknown";
				// 等配置接口
				const options = {
					...this.launchOptions,
					platform
				};

				this.api
					.getAdConfigAsync(options)
					.then((result) => {
						console.log("获取广告配置成功：", result);
						// 仅微信：抖音环境也会有 wx 别名，必须排除 tt
						if (
							typeof wx !== "undefined" &&
							typeof tt === "undefined" &&
							typeof wx.getSystemInfoSync === "function"
						) {
							let jsonContent = result?.data?.jsonContent || '{}';
							let bucket = result?.data?.bucket || 'BUCKET_DEFAULT';
							resolve({...JSON.parse(jsonContent),bucket});
						}else{
							resolve(result?.data);
						}
						
					})
					.catch((error) => {
						reject(error);
					});
			});
		}


		try {
			let result = await this.__adConfig_promise__;

			if (!result) {
				console.error("❌ 广告配置返回空响应");
				throw new Error("获取广告配置失败：服务器返回空响应");
			}

			this.__adConfig_cache__ = result;

			return this.__adConfig_cache__;
		} catch (error) {
			throw error;
		} finally {
			this.__adConfig_promise__ = null;
		}
	}


}

// 自定义 UUID 算法实现
const getRandomBasic = (() => {
	let e = new Date().getTime();
	return (t) => {
		return Math.ceil(((e = (9301 * e + 49297) % 233280) / 233280) * t);
	};
})();

function getRandom() {
	if (typeof Uint32Array === "function") {
		let crypt = null;
		if (typeof crypto !== "undefined") {
			crypt = crypto;
		} else if (typeof msCrypto !== "undefined") {
			crypt = msCrypto;
		}
		if (crypt && crypt.getRandomValues) {
			try {
				const t = new Uint32Array(1);
				crypt.getRandomValues(t);
				return t[0] / Math.pow(2, 32);
			} catch (e) {}
		}
	}
	return getRandomBasic(1e19) / 1e19;
}

function getUUID() {
	return (
		Date.now() +
		"-" +
		Math.floor(1e7 * getRandom()) +
		"-" +
		getRandom().toString(16).replace(".", "") +
		"-" +
		String(31242 * getRandom())
		.replace(".", "")
		.slice(0, 8)
	);
}

/**
 * @description
 * SDK核心实现
 */
export default FBISDKCore;