/**
 * 广告生命周期埋点辅助：对齐埋点表 $AdRequest / $AdShow，关闭用 $WatchVideo，并带 popPath
 */

const AD_LOAD_TIMEOUT_MS = 10000;
const AD_SHOW_TIMEOUT_NATIVE_MS = 3000;
const AD_SHOW_TIMEOUT_FULLSCREEN_MS = 10000;

const TYPE_DAILY_KEYS = {
  REWARDED_VIDEO: "fbiad_show_daily_REWARDED_VIDEO",
  INSERT_SCREEN: "fbiad_show_daily_INSERT_SCREEN",
};

/** 本次进程内：各广告类型已触发次数（第几次） */
const processTypeTriggerTimes = Object.create(null);

function bumpProcessTypeTimes(adType) {
  if (!adType) return 0;
  const next = (Number(processTypeTriggerTimes[adType]) || 0) + 1;
  processTypeTriggerTimes[adType] = next;
  return next;
}

function getProcessTypeTimes(adType) {
  if (!adType) return 0;
  return Number(processTypeTriggerTimes[adType]) || 0;
}

function storageGet(key) {
  try {
    if (typeof uni !== "undefined" && uni.getStorageSync) {
      return uni.getStorageSync(key);
    }
    if (typeof wx !== "undefined" && wx.getStorageSync) {
      return wx.getStorageSync(key);
    }
  } catch (e) {}
  return null;
}

function storageSet(key, val) {
  try {
    if (typeof uni !== "undefined" && uni.setStorageSync) {
      return uni.setStorageSync(key, val);
    }
    if (typeof wx !== "undefined" && wx.setStorageSync) {
      return wx.setStorageSync(key, val);
    }
  } catch (e) {}
}

function todayStr() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${d.getFullYear()}-${m}-${day}`;
}

function clipMs(ms) {
  const n = Number(ms);
  if (!Number.isFinite(n) || n < 0) return 0;
  if (n > 2147483647) return -1;
  return Math.round(n);
}

function clipStr(v, max) {
  if (v == null || v === "") return "";
  if (typeof v === "object") return "";
  const s = String(v);
  if (s === "[object Object]") return "";
  return s.slice(0, max || 32);
}

function clipReason(v) {
  return clipStr(v, 128);
}

/** 微信失败 reason：`errCode:errMsg`；两项都没有 → `没有返回` */
export function formatWxAdReason(error) {
  let raw = error;
  if (Array.isArray(raw)) raw = raw[0];
  if (Array.isArray(raw)) raw = raw[0];

  let code = "";
  let msg = "";
  if (raw && typeof raw === "object") {
    if (raw.errCode != null && raw.errCode !== "") code = String(raw.errCode);
    else if (raw.errorCode != null && raw.errorCode !== "")
      code = String(raw.errorCode);
    msg = String(raw.errMsg || raw.message || raw.errDetail || "").trim();
    if (msg === "[object Object]") msg = "";
  } else if (typeof raw === "string") {
    msg = raw === "[object Object]" ? "" : raw.trim();
  } else if (raw != null) {
    msg = String(raw);
  }
  if (!code && !msg) return "没有返回";
  return `${code}:${msg}`;
}

export function errCodeFromAdError(error) {
  let raw = error;
  if (Array.isArray(raw)) raw = raw[0];
  if (Array.isArray(raw)) raw = raw[0];
  if (raw == null || typeof raw !== "object") return "";
  const code =
    raw.errCode != null
      ? raw.errCode
      : raw.errorCode != null
        ? raw.errorCode
        : raw.code;
  if (code == null || code === "") return "";
  return String(code);
}

export function resolvePopPath(params) {
  const v = params && params.popPath;
  return v !== undefined && v !== null && v !== "" ? String(v) : "AUTO_PULL";
}

export function typeToName(type, params) {
  const adType = Number(
    params && (params.adType != null ? params.adType : params.type),
  );
  if (adType === 7) return "GRID";
  if (adType === 6) return "NATIVE";
  if (adType === 4) return "NATIVE";
  if (adType === 2) return "INSERT_SCREEN";
  if (adType === 1) return "REWARDED_VIDEO";

  switch (type) {
    case "reward":
      return "REWARDED_VIDEO";
    case "interstitial":
      return "INSERT_SCREEN";
    case "native":
    case "custom":
      return "NATIVE";
    case "grid":
      return "GRID";
    default:
      return type + "";
  }
}

function isFullscreenType(adType) {
  return adType === "REWARDED_VIDEO" || adType === "INSERT_SCREEN";
}

/** 腾讯营销 DataNexus（未配置 / 非小游戏构建时静默跳过） */
function notifyDataNexus(fn) {
  try {
    // eslint-disable-next-line global-require
    const mod = require("../datanexus/DataNexusManager.js");
    const dn = mod && mod.default;
    if (!dn || typeof fn !== "function") return;
    fn(dn);
  } catch (e) {}
}

export function getTypeDailyShowCount(adType) {
  const key = TYPE_DAILY_KEYS[adType];
  if (!key) return 0;
  const stored = storageGet(key);
  if (!stored) return 0;
  const date = stored.date || stored.d;
  const count = Number(stored.count != null ? stored.count : stored.c) || 0;
  if (date !== todayStr()) return 0;
  return Math.max(0, count);
}

export function markTypeShowCompleted(adType) {
  const key = TYPE_DAILY_KEYS[adType];
  if (!key) return;
  const next = getTypeDailyShowCount(adType) + 1;
  storageSet(key, { date: todayStr(), count: next });
}

function canUpgradeTimeout(prev, next) {
  return (
    prev === "timeout" && (next === "success" || next === "failure")
  );
}

/**
 * @param {object} ctx
 * @param {Function} ctx.trackAsync
 * @param {Function} ctx.getStartTime
 * @param {string} ctx.code
 * @param {string} ctx.handlerType reward|interstitial|native|custom|grid
 * @param {object} ctx.params
 * @param {object} ctx.option
 */
export function createTaskAdTracker(ctx) {
  const state = {
    req: "",
    reqResult: "",
    show: "",
    showResult: "",
    closed: false,
    loadStart: 0,
    showStart: 0,
    trackTimes: 0,
    loadTimer: null,
    showTimer: null,
  };

  function clearTimers() {
    if (state.loadTimer) {
      clearTimeout(state.loadTimer);
      state.loadTimer = null;
    }
    if (state.showTimer) {
      clearTimeout(state.showTimer);
      state.showTimer = null;
    }
  }

  function triggerTiming() {
    let start =
      typeof ctx.getStartTime === "function" ? Number(ctx.getStartTime()) : 0;
    if (!Number.isFinite(start) || start <= 0) {
      start = Date.now();
    }
    // 埋点表：广告 triggerTiming = 进小程序第 N 秒
    const sec = Math.floor((Date.now() - start) / 1000);
    if (!Number.isFinite(sec) || sec < 0) return 0;
    return sec > 2147483647 ? -1 : sec;
  }

  function adType() {
    return typeToName(ctx.handlerType, ctx.params);
  }

  function pullLimit() {
    const p = ctx.params || {};
    const o = ctx.option || {};
    const n = Number(
      p.pullLimit != null
        ? p.pullLimit
        : o.pullLimit != null
          ? o.pullLimit
          : 0,
    );
    return Number.isFinite(n) && n > 0 ? n : 0;
  }

  function basePayload(extra) {
    const type = adType();
    const payload = {
      name: clipStr(ctx.code, 32),
      ad_code: ctx.code,
      type,
      adSpaceId: clipStr((ctx.params && ctx.params.adUnitId) || "", 32),
      popPath: resolvePopPath(ctx.params),
      triggerTiming: triggerTiming(),
      ad_platform:
        typeof ctx.getPlatform === "function" ? ctx.getPlatform() : undefined,
    };
    if (state.trackTimes > 0) {
      payload.times = state.trackTimes;
    } else {
      // 兜底：未走过 beginRound 时也带上进程内该类型当前次数
      const n = getProcessTypeTimes(type);
      if (n > 0) payload.times = n;
    }
    if (extra && typeof extra === "object") {
      Object.keys(extra).forEach((k) => {
        if (extra[k] !== undefined) payload[k] = extra[k];
      });
    }
    return payload;
  }

  function emit(event, payload) {
    if (typeof ctx.trackAsync !== "function") return;
    try {
      ctx.trackAsync(event, payload);
    } catch (e) {}
  }

  function withCost(extra, startedAt) {
    const next = extra && typeof extra === "object" ? { ...extra } : {};
    if (next.time == null && startedAt) {
      next.time = clipMs(Date.now() - startedAt);
    }
    return next;
  }

  function buildRequestShowPayload(value, extra, stage) {
    const type = adType();
    const payload = basePayload({});
    payload.value = value;

    if (
      stage === "request" &&
      value === "loading" &&
      isFullscreenType(type)
    ) {
      payload.reason = clipStr(`${pullLimit()},${getTypeDailyShowCount(type)}`, 32);
    } else if (extra && extra.reason != null && extra.reason !== "") {
      payload.reason = clipReason(extra.reason);
    }

    if (
      value === "success" &&
      (stage === "request" || stage === "show") &&
      extra &&
      extra.time != null
    ) {
      payload.time = clipMs(extra.time);
    }

    if (extra && extra.errCode != null && extra.errCode !== "") {
      payload.errCode = clipStr(extra.errCode, 32);
    }

    return payload;
  }

  function request(value, extra) {
    if (value === "loading") {
      if (state.req === "loading") return;
      state.req = "loading";
      state.reqResult = "";
      state.loadStart = Date.now();
      emit(
        "$AdRequest",
        buildRequestShowPayload(value, extra, "request"),
      );
      return;
    }
    if (state.req === "done" && !canUpgradeTimeout(state.reqResult, value)) {
      return;
    }
    state.req = "done";
    state.reqResult = value;
    if (state.loadTimer) {
      clearTimeout(state.loadTimer);
      state.loadTimer = null;
    }
    emit(
      "$AdRequest",
      buildRequestShowPayload(
        value,
        withCost(extra, state.loadStart),
        "request",
      ),
    );
  }

  function show(value, extra) {
    if (value === "loading") {
      if (state.show === "loading" || state.show === "done") return;
      state.show = "loading";
      state.showResult = "";
      state.showStart = Date.now();
      emit("$AdShow", buildRequestShowPayload(value, extra, "show"));
      return;
    }
    if (state.show === "done") {
      if (value === state.showResult) return;
      if (value === "success" && state.showResult !== "timeout") return;
      if (state.showResult === "failure") return;
    }
    state.show = "done";
    state.showResult = value;
    if (state.showTimer) {
      clearTimeout(state.showTimer);
      state.showTimer = null;
    }
    if (value === "success" && isFullscreenType(adType())) {
      markTypeShowCompleted(adType());
    }
    emit(
      "$AdShow",
      buildRequestShowPayload(value, withCost(extra, state.showStart), "show"),
    );
    // 对齐 shared：激励不报 AD_IMPRESSION；AD_PLACEMENT_SHOW 由业务在
    // 广告点位曝光/展示意图发生时显式调用 DataNexus.reportAdPlacementShow。
    if (value === "success" && adType() !== "REWARDED_VIDEO") {
      notifyDataNexus((dn) => dn.reportAdImpression(adType()));
    }
  }

  function close(isFinish) {
    const type = adType();
    if (!isFullscreenType(type)) return;
    if (state.closed) return;
    state.closed = true;
    const result = isFinish ? "success" : "failure";
    const payload = basePayload({});
    // 关闭事件不写 times / time
    delete payload.times;
    delete payload.time;
    emit(
      "$WatchVideo",
      Object.assign(payload, {
        result,
        value: result,
      }),
    );
    if (isFinish && type === "REWARDED_VIDEO") {
      notifyDataNexus((dn) => dn.reportAdVideoFinish(ctx.code));
    }
  }

  function beginRound({ isNewRound }) {
    clearTimers();
    if (isNewRound) {
      // 本次进程内该广告类型第几次触发（跨 code 累计；失败重试不递增）
      state.trackTimes = bumpProcessTypeTimes(adType());
      // 对齐 shared：激励业务 show 入口上报 AD_CLICK（非微信组件 onClick）
      if (adType() === "REWARDED_VIDEO") {
        notifyDataNexus((dn) => dn.reportAdClick(ctx.code));
      }
    }
    state.req = "";
    state.reqResult = "";
    state.show = "";
    state.showResult = "";
    state.closed = false;
    state.loadStart = 0;
    state.showStart = 0;
    request("loading");
    state.loadTimer = setTimeout(() => {
      state.loadTimer = null;
      if (state.req === "loading") {
        request("timeout", { reason: "load_timeout" });
      }
    }, AD_LOAD_TIMEOUT_MS);
  }

  /** 同步最新 params（如 AD.show 传入的 popPath） */
  function syncParams(params, option) {
    if (params) ctx.params = params;
    if (option) ctx.option = option;
  }

  function onLoadSuccess() {
    request("success");
    show("loading");
    const type = adType();
    const timeoutMs = isFullscreenType(type)
      ? AD_SHOW_TIMEOUT_FULLSCREEN_MS
      : AD_SHOW_TIMEOUT_NATIVE_MS;
    state.showTimer = setTimeout(() => {
      state.showTimer = null;
      if (state.show !== "loading") return;
      if (isFullscreenType(type)) {
        // 超时已出屏：success + reason=show_timeout
        show("success", { reason: "show_timeout" });
      } else {
        show("timeout");
      }
    }, timeoutMs);
  }

  function onShowSuccess() {
    // 若尚未走过 onLoad（部分平台直接露出），补齐 request success + show loading
    if (state.req === "loading" || state.req === "") {
      request("success");
    }
    if (state.show === "" || state.show === "loading") {
      if (state.show === "") show("loading");
      show("success");
    } else if (state.show === "done" && state.showResult === "timeout") {
      // native timeout 后真实露出可升级；fullscreen show_timeout 已是 success
      show("success");
    }
  }

  function onError(error) {
    const reason = formatWxAdReason(error);
    const errCode = errCodeFromAdError(error);
    const extra = { reason, errCode };
    // 请求未完成 → $AdRequest failure
    if (state.req === "loading" || state.req === "") {
      request("failure", extra);
      return;
    }
    // 展示阶段 / 展示中出错 → $AdShow failure
    if (state.show === "") show("loading");
    show("failure", extra);
  }

  function destroy() {
    clearTimers();
  }

  return {
    beginRound,
    syncParams,
    onLoadSuccess,
    onShowSuccess,
    onError,
    close,
    destroy,
    clearTimers,
    getTrackTimes: () => state.trackTimes,
  };
}

export {
  AD_LOAD_TIMEOUT_MS,
  AD_SHOW_TIMEOUT_NATIVE_MS,
  AD_SHOW_TIMEOUT_FULLSCREEN_MS,
};
