/**
 * Uni-App 兼容性模块
 * 提供uni-app平台的兼容性功能
 * 支持微信、抖音多平台
 */

// 内存存储备选方案
const memoryStorage = new Map();

// Deploy 写入的启动参数（平台 getLaunchOptionsSync + 手动 params 合并结果）
// raw: { path, scene, query, ... }；resolved: SDK 扁平字段（含 channel）
let __launchOptionsOverride = null;
let __resolvedLaunchOptions = null;

// 平台检测：微信（含无 getWindowInfo 的运行环境）
const isWX = () =>
  typeof wx !== "undefined" &&
  typeof tt === "undefined" &&
  !!(
    wx.getWindowInfo ||
    wx.getSystemInfoSync ||
    wx.getSystemInfo ||
    wx.login ||
    wx.createRewardedVideoAd
  ) && "wx";
const isTT = () => typeof tt !== "undefined" && tt.getSystemInfo && "tt";


// 获取当前平台的API对象
const getPlatformAPI = () => {
  if (isWX()) {
    return wx;
  }
  if (isTT()) {
    return tt;
  }

  // 返回null表示没有可用的平台API
  console.warn("⚠️ [uniCompatible] 平台API未加载");
  return null;
};

// 安全的API调用包装器 - 同步版本
const safeApiCall = (apiFunc, fallback = null) => {
  try {
    return apiFunc();
  } catch (error) {
    console.warn("API调用失败，使用降级处理:", error.message);
    return fallback;
  }
};

// 安全的异步API调用包装器 - 异步版本
const safeAsyncApiCall = async (apiFunc, fallback = null) => {
  try {
    const api = getPlatformAPI();
    if (!api) {
      console.warn("平台API未就绪，使用降级处理");
      return fallback;
    }
    return await apiFunc(api);
  } catch (error) {
    console.warn("异步API调用失败，使用降级处理:", error.message);
    return fallback;
  }
};

const uniCompatible = {
  // 检测uni-app环境
  isUniApp: function () {
    return typeof uni !== "undefined";
  },

  // 获取uni-app API
  getUniAPI: function () {
    return typeof uni !== "undefined" ? uni : null;
  },

  // 同步存储方法
  setStorageSync: function (key, data) {
    // console.log("📦 [uniCompatible] setStorageSync:", key, typeof data);

    if (typeof uni !== "undefined" && uni.setStorageSync) {
      // Uni-app环境
      return uni.setStorageSync(key, data);
    } else {
      return safeApiCall(() => {
        const api = getPlatformAPI();
        if (api && api.setStorageSync) {
          return api.setStorageSync(key, data);
        } else {
          // 其他环境，使用内存存储
          try {
            const value =
              typeof data === "string" ? data : JSON.stringify(data);
            memoryStorage.set(key, value);
            // console.log("✅ [uniCompatible] 降级到内存存储");
          } catch (error) {
            console.error("❌ [uniCompatible] 内存存储失败:", error);
          }
        }
      });
    }
  },

  getStorageSync: function (key) {
    // console.log("📦 [uniCompatible] getStorageSync:", key);

    if (typeof uni !== "undefined" && uni.getStorageSync) {
      // Uni-app环境
      return uni.getStorageSync(key);
    } else {
      return safeApiCall(() => {
        const api = getPlatformAPI();
        if (api && api.getStorageSync) {
          const result = api.getStorageSync(key);
          return result;
        } else {
          // 其他环境，使用内存存储
          try {
            const value = memoryStorage.get(key);
            console.log(
              "✅ [uniCompatible] 内存存储读取(降级):",
              key,
              "=>",
              value
            );
            if (value === undefined) {
              return null;
            }
            // 尝试解析JSON，如果失败则返回原字符串
            try {
              return JSON.parse(value);
            } catch (e) {
              return value;
            }
          } catch (error) {
            console.error("❌ [uniCompatible] 内存存储读取失败:", error);
            return null;
          }
        }
      }, null);
    }
  },

  removeStorageSync: function (key) {
    // console.log("📦 [uniCompatible] removeStorageSync:", key);

    if (typeof uni !== "undefined" && uni.removeStorageSync) {
      // Uni-app环境
      return uni.removeStorageSync(key);
    } else {
      // 其他环境，使用内存存储
      memoryStorage.delete(key);
      // console.log("✅ [uniCompatible] 内存存储删除(降级)");
    }
  },

  /**
   * 写入启动参数覆盖（平台原生 + Deploy.setLaunchOptions(params) 的合并结果）
   * 之后 getLaunchOptionsSync 一律返回这份，保证全库读到的启动参数一致且更齐全
   */
  setLaunchOptionsOverride: function (options) {
    if (!options || typeof options !== "object") {
      __launchOptionsOverride = null;
      return;
    }
    __launchOptionsOverride = {
      ...options,
      query: { ...(options.query || {}) },
    };
  },

  /**
   * 写入解析后的扁平启动参数（全局单例，供埋点等直接读 channel/aid）
   */
  setResolvedLaunchOptions: function (options) {
    if (!options || typeof options !== "object") {
      __resolvedLaunchOptions = null;
      return;
    }
    __resolvedLaunchOptions = { ...options };
  },

  /**
   * 读取解析后的扁平启动参数（全局）
   */
  getResolvedLaunchOptions: function () {
    return __resolvedLaunchOptions ? { ...__resolvedLaunchOptions } : null;
  },

  /**
   * 是否已有合并后的启动参数覆盖
   */
  hasLaunchOptionsOverride: function () {
    return !!__launchOptionsOverride;
  },

  /**
   * 仅读平台原生启动参数（忽略手动覆盖），用于合并时重新拉取平台侧字段
   */
  getPlatformLaunchOptionsSync: function () {
    if (typeof uni !== "undefined" && uni.getLaunchOptionsSync) {
      try {
        return uni.getLaunchOptionsSync() || { query: {}, path: "", scene: "0" };
      } catch (e) {
        return { query: {}, path: "", scene: "0" };
      }
    }
    return safeApiCall(
      () => {
        const api = getPlatformAPI();
        if (isWX() || isTT()) {
          return api.getLaunchOptionsSync() || { query: {}, path: "", scene: "0" };
        }
        return { query: {}, path: "", scene: "0" };
      },
      { query: {}, path: "", scene: "0" },
    );
  },

  /**
   * 获取启动选项：优先返回全局合并结果，否则读平台
   */
  getLaunchOptionsSync: function () {
    if (__launchOptionsOverride) {
      return {
        ...__launchOptionsOverride,
        query: { ...(__launchOptionsOverride.query || {}) },
      };
    }
    return this.getPlatformLaunchOptionsSync();
  },

  /**
   * 显示模态框
   */
  showModal: function (options) {
    // console.log("📦 [uniCompatible] showModal:", options);

    if (typeof uni !== "undefined" && uni.showModal) {
      uni.showModal(options);
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.showModal({
              ...options,
              success: resolve,
              fail: reject,
            });
          }),
        new Promise((resolve) => {
          // 降级处理

          console.log(
            "📱 [Modal]",
            options.title || "提示",
            ":",
            options.content || ""
          );
          // 默认确认
          resolve({
            confirm: true,
            cancel: false,
          });
        })
      ).then((result) => {
        if (options.success) {
          options.success(result);
        }
      });
    }
  },

  /**
   * 网络请求 - 直接方法（兼容旧调用方式）
   */
  request: function (options) {
    const requestId =
      Date.now() + "_" + Math.random().toString(36).substr(2, 6);

    // 详细的请求前日志
    // console.log("🚀 [网络请求] ===== 请求开始 =====");
    // console.log(`📋 [网络请求] 请求ID: ${requestId}`);
    // console.log(`📋 [网络请求] URL: ${options?.url}`);
    // console.log(`📋 [网络请求] 方法: ${options?.method || "GET"}`);
    // console.log(
    //   `📋 [网络请求] 请求头:`,
    //   options?.header || options?.headers || {}
    // );
    // console.log(`📋 [网络请求] 请求数据:`, options?.data || "None");
    // console.log(`📋 [网络请求] 超时时间: ${options?.timeout || "Default"}ms`);
    // console.log(`📋 [网络请求] 数据类型: ${options?.dataType || "json"}`);
    // console.log(`📋 [网络请求] 响应类型: ${options?.responseType || "text"}`);
    // console.log(`📋 [网络请求] 完整参数:`, options);

    const startTime = Date.now();

    if (typeof uni !== "undefined" && uni.request) {
      // Uni-app环境
      // console.log("🌐 [网络请求] 使用uni.request进行网络请求");

      return new Promise((resolve, reject) => {
        uni.request({
          ...options,
          success: (res) => {
            const endTime = Date.now();
            const duration = endTime - startTime;

            // console.log("✅ [网络请求] ===== 请求成功 =====");
            // console.log(`📋 [网络请求] 请求ID: ${requestId}`);
            // console.log(`📋 [网络请求] 耗时: ${duration}ms`);
            // console.log(`📋 [网络请求] 状态码: ${res.statusCode}`);
            // console.log(`📋 [网络请求] 响应头:`, res.header || {});
            // console.log(`📋 [网络请求] 响应数据:`, res.data);
            // console.log(`📋 [网络请求] 完整响应:`, res);
            // console.log("🚀 [网络请求] ===== 请求结束 =====");

            // 修复：同时调用传入的success回调和Promise resolve
            if (options.success && typeof options.success === "function") {
              // console.log("🔧 [网络请求] 触发传入的success回调...");
              try {
                options.success(res);
              } catch (callbackError) {
                console.error(
                  "❌ [网络请求] success回调执行出错:",
                  callbackError
                );
              }
            }

            resolve(res);
          },
          fail: (err) => {
            const endTime = Date.now();
            const duration = endTime - startTime;

            console.error("❌ [网络请求] ===== 请求失败 =====");
            console.error(`📋 [网络请求] 请求ID: ${requestId}`);
            console.error(`📋 [网络请求] 耗时: ${duration}ms`);
            console.error(`📋 [网络请求] 错误信息:`, err);
            console.error("🚀 [网络请求] ===== 请求结束 =====");

            // 修复：同时调用传入的fail回调和Promise reject
            if (options.fail && typeof options.fail === "function") {
              // console.log("🔧 [网络请求] 触发传入的fail回调...");
              try {
                options.fail(err);
              } catch (callbackError) {
                console.error("❌ [网络请求] fail回调执行出错:", callbackError);
              }
            }

            reject(err);
          },
        });
      });
    }

    // 优先使用平台原生API
    const api = getPlatformAPI();
    if (api && api.request) {
      // 使用平台原生请求方法
      const platformName = isWX()
        ? "wx"
        : isTT()
          ? "tt"
          : "unknown";
      // console.log(`🌐 [网络请求] 使用${platformName}.request进行网络请求`);

      return new Promise((resolve, reject) => {
        api.request({
          ...options,
          success: (res) => {
            const endTime = Date.now();
            const duration = endTime - startTime;

            // console.log("✅ [网络请求] ===== 请求成功 =====");
            // console.log(`📋 [网络请求] 请求ID: ${requestId}`);
            // console.log(`📋 [网络请求] 平台: ${platformName}`);
            // console.log(`📋 [网络请求] 耗时: ${duration}ms`);
            // console.log(`📋 [网络请求] 状态码: ${res.statusCode}`);
            // console.log(`📋 [网络请求] 响应头:`, res.header || {});
            // console.log(`📋 [网络请求] 响应数据:`, res.data);
            // console.log(`📋 [网络请求] 完整响应:`, res);
            // console.log("🚀 [网络请求] ===== 请求结束 =====");

            // 修复：同时调用传入的success回调和Promise resolve
            if (options.success && typeof options.success === "function") {
              // console.log("🔧 [网络请求] 触发传入的success回调...");
              try {
                options.success(res);
              } catch (callbackError) {
                console.error(
                  "❌ [网络请求] success回调执行出错:",
                  callbackError
                );
              }
            }

            resolve(res);
          },
          fail: (err) => {
            const endTime = Date.now();
            const duration = endTime - startTime;

            console.error("❌ [网络请求] ===== 请求失败 =====");
            console.error(`📋 [网络请求] 请求ID: ${requestId}`);
            console.error(`📋 [网络请求] 平台: ${platformName}`);
            console.error(`📋 [网络请求] 耗时: ${duration}ms`);
            console.error(`📋 [网络请求] 错误信息:`, err);
            console.error("🚀 [网络请求] ===== 请求结束 =====");

            // 修复：同时调用传入的fail回调和Promise reject
            if (options.fail && typeof options.fail === "function") {
              // console.log("🔧 [网络请求] 触发传入的fail回调...");
              try {
                options.fail(err);
              } catch (callbackError) {
                console.error("❌ [网络请求] fail回调执行出错:", callbackError);
              }
            }

            reject(err);
          },
        });
      });
    }


  },

  /**
   * 下载文件
   */
  downloadFile: function (options) {
    if (typeof uni !== "undefined" && uni.downloadFile) {
      return new Promise((resolve, reject) => {
        uni.downloadFile({
          ...options,
          success: resolve,
          fail: reject,
        });
      });
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.downloadFile({
              ...options,
              success: resolve,
              fail: reject,
            });
          }),
        Promise.reject(new Error("downloadFile API未就绪"))
      );
    }
  },

  /**
   * 获取文件系统管理器
   */
  getFileSystemManager: function () {
    if (typeof uni !== "undefined" && uni.getFileSystemManager) {
      return uni.getFileSystemManager();
    } else {
      return safeApiCall(
        () => {
          const api = getPlatformAPI();
          if (!api) {
            return { readFile: () => { } };
          }
          return api.getFileSystemManager();
        },
        { readFile: () => { } }
      );
    }
  },

  /**
   * 切换Tab
   */
  switchTab: function (options) {
    if (typeof uni !== "undefined" && uni.switchTab) {
      return new Promise((resolve, reject) => {
        uni.switchTab({
          ...options,
          success: resolve,
          fail: reject,
        });
      });
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.switchTab({
              ...options,
              success: resolve,
              fail: reject,
            });
          }),
        Promise.reject(new Error("switchTab API未就绪"))
      );
    }
  },

  /**
   * 导航到页面
   */
  navigateTo: function (options) {
    if (typeof uni !== "undefined" && uni.navigateTo) {
      return new Promise((resolve, reject) => {
        uni.navigateTo({
          ...options,
          success: resolve,
          fail: reject,
        });
      });
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.navigateTo({
              ...options,
              success: resolve,
              fail: reject,
            });
          }),
        Promise.reject(new Error("navigateTo API未就绪"))
      );
    }
  },

  /**
   * 重定向到页面
   */
  redirectTo: function (options) {
    if (typeof uni !== "undefined" && uni.redirectTo) {
      return new Promise((resolve, reject) => {
        uni.redirectTo({
          ...options,
          success: resolve,
          fail: reject,
        });
      });
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.redirectTo({
              ...options,
              success: resolve,
              fail: reject,
            });
          }),
        Promise.reject(new Error("redirectTo API未就绪"))
      );
    }
  },

  /**
   * 检查API是否可用
   */
  canIUse: function (api) {
    if (typeof uni !== "undefined" && uni.canIUse) {
      return uni.canIUse(api);
    } else {
      return safeApiCall(() => {
        const platformAPI = getPlatformAPI();
        if (!platformAPI) {
          return false;
        }
        const result = platformAPI.canIUse ? platformAPI.canIUse(api) : false;
        return result;
      }, false);
    }
  },

  /**
   * 获取系统信息
   */
  getSystemInfo: function (options) {
    if (typeof uni !== "undefined" && uni.getSystemInfo) {
      return new Promise((resolve, reject) => {
        uni.getSystemInfo({
          ...options,
          success: resolve,
          fail: reject,
        });
      });
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.getSystemInfo({
              ...options,
              success: resolve,
              fail: reject,
            });
          }),
        Promise.reject(new Error("getSystemInfo API未就绪"))
      );
    }
  },

  /**
   * 获取账号信息
   */
  getAccountInfoSync: function () {
    if (typeof uni !== "undefined" && uni.getAccountInfoSync) {
      return uni.getAccountInfoSync();
    } else {
      return safeApiCall(
        () => {
          const api = getPlatformAPI();

          if (api && api.getAccountInfoSync) {
            // 其他平台正常调用
            const result = api.getAccountInfoSync();
            return result;
          } else {
            return {
              miniProgram: {
                appId: "",
                version: "1.0.0",
                envVersion: "release",
              },
            };
          }
        },
        { miniProgram: { appId: "", version: "1.0.0", envVersion: "release" } }
      );
    }
  },

  /**
   * 显示Toast提示
   */
  showToast: function (options) {
    if (typeof uni !== "undefined" && uni.showToast) {
      uni.showToast(options);
    } else {
      const api = getPlatformAPI();
      if (api && api.showToast) {
        api.showToast(options);
      } else {
        console.log("🍞 [Toast]", options.title || options.message || "");
      }
    }
  },

  /**
   * 显示Loading
   */
  showLoading: function (options) {
    if (typeof uni !== "undefined" && uni.showLoading) {
      uni.showLoading(options);
    } else {
      const api = getPlatformAPI();
      if (api && api.showLoading) {
        api.showLoading(options);
      } else {
        console.log("⏳ [Loading]", options?.title || "加载中...");
      }
    }
  },

  /**
   * 隐藏Loading
   */
  hideLoading: function () {
    if (typeof uni !== "undefined" && uni.hideLoading) {
      uni.hideLoading();
    } else {
      const api = getPlatformAPI();
      if (api && api.hideLoading) {
        api.hideLoading();
      }
    }
  },

  /**
   * 登录
   */
  login: function (options) {
    if (typeof uni !== "undefined" && uni.login) {
      return new Promise((resolve, reject) => {
        uni.login({
          ...options,
          success: resolve,
          fail: reject,
        });
      });
    } else {
      return safeAsyncApiCall(
        (api) =>
          new Promise((resolve, reject) => {
            api.login({
              ...options,
              success: (res) => {
                resolve(res);
              },
              fail: (err) => {
                console.error("平台登录API失败:", err);
                reject(err);
              },
            });
          }),
        Promise.reject(new Error("login API未就绪"))
      );
    }
  },

  /**
   * 禁用用户截屏和录屏
   */
  disableUserScreenRecord: function (options) {
    if (typeof uni !== "undefined" && uni.disableUserScreenRecord) {
      uni.disableUserScreenRecord(options);
    } else {
      const api = getPlatformAPI();
      if (isTT() && api && api.disableUserScreenRecord) {
        api.disableUserScreenRecord(options);
      } else if (isWX()) {
        uniCompatible.showToast({
          title: "开发中",
          icon: "none"
        });
      } else {
        console.log("开发中");
      }
    }
  },

  // 封装的uni API
  api: {
    // 请求封装
    request: function (options) {
      return uniCompatible.request(options);
    },

    // 存储封装
    setStorage: function (key, data) {
      if (typeof uni !== "undefined") {
        return new Promise((resolve, reject) => {
          uni.setStorage({
            key,
            data,
            success: resolve,
            fail: reject,
          });
        });
      } else {
        // 设置存储（降级处理）
        uniCompatible.setStorageSync(key, data);
        return Promise.resolve();
      }
    },

    getStorage: function (key) {
      if (typeof uni !== "undefined") {
        return new Promise((resolve, reject) => {
          uni.getStorage({
            key,
            success: resolve,
            fail: reject,
          });
        });
      } else {
        // 获取存储（降级处理）
        const data = uniCompatible.getStorageSync(key);
        return Promise.resolve({ data });
      }
    },

    // 显示提示
    showToast: function (options) {
      if (typeof uni !== "undefined") {
        uni.showToast(options);
      } else {
        // console.log("🍞 [Toast]", options.title || options.message || "");
      }
    },

    // 显示加载中
    showLoading: function (options) {
      if (typeof uni !== "undefined") {
        uni.showLoading(options);
      } else {
        console.log(
          "⏳ [Loading]",
          options.title || options.message || "加载中..."
        );
      }
    },

    hideLoading: function () {
      if (typeof uni !== "undefined") {
        uni.hideLoading();
      } else {
        // console.log("✅ [Loading] 已隐藏");
      }
    },
  },

  // 平台检测
  platform: {
    // 获取平台信息
    getPlatform: function () {
      if (typeof uni !== "undefined") {
        return uni.getSystemInfoSync().platform;
      } else {
        return "unknown";
      }
    },

    // 是否为微信小程序
    isWeChat: function () {
      if (typeof uni !== "undefined") {
        const systemInfo = uni.getSystemInfoSync();
        return systemInfo.uniPlatform === "mp-weixin";
      }
      return false;
    },

    // 是否为头条小程序
    isTikTok: function () {
      if (typeof uni !== "undefined") {
        const systemInfo = uni.getSystemInfoSync();
        return systemInfo.uniPlatform === "mp-toutiao";
      }
      return false;
    },
  },
};

export default uniCompatible;
