import comfortable from "./fbiCoreComfortable/fbiCoreCFIndex.js"


let cache = null;

/** 开发版 SDK，或开发者工具（devtools）下埋点 $os/$brand 写死 IPHONE */
function applyDevTrackDeviceOverrides(deviceInfo) {
	let isDevBuild = false;
	try {
		// webpack DefinePlugin 会把 process.env.NODE_ENV 替换成字面量；
		// 小游戏运行时通常没有 process，不能先判断 typeof process
		isDevBuild = process.env.NODE_ENV === "development";
	} catch (e) {}

	const brand = String((deviceInfo && deviceInfo.$brand) || "").toUpperCase();
	const os = String((deviceInfo && deviceInfo.$os) || "").toLowerCase();
	const isDevtools = brand === "DEVTOOLS" || os === "devtools";

	if (isDevBuild || isDevtools) {
		return {
			...deviceInfo,
			$os: "IPHONE",
			$brand: "IPHONE",
		};
	}
	return deviceInfo;
}

/**
 * 	获取设备信息
 */
const device = () => {
	console.log('📋 [device] 开始获取设备信息');
	
	return new Promise(async (resolve, reject) => {
		if(cache){
			console.log('✅ [device] 使用缓存的设备信息:', cache);
			resolve(JSON.parse(JSON.stringify(cache)));
			return;
		}
		
		console.log('📋 [device] 调用平台特定设备信息获取方法...');
		try {
			const deviceInfo = applyDevTrackDeviceOverrides(
				await comfortable.deviceAsync(),
			);
			console.log('✅ [device] 设备信息获取成功:', deviceInfo);
			
			// 修复：设置缓存
			cache = deviceInfo;
			
			resolve(deviceInfo);
		} catch (error) {
			console.error('❌ [device] 设备信息获取失败:', error);
			reject(error);
		}
	})
}


export default device;
