/**
 * DHMiniSDK 适配层（微信小游戏官方 DH SDK）
 * 统一管理初始化、登录、激励广告；由 Deploy.readyAsync 在 isWXGameSDK=true 时接入。
 */
import DHMiniSDK from "./dh-mini-sdk-for-wx-2.3.1.js";

const INIT_CONFIG_API = "https://gateway.op.dianhun.cn/LKvso/initConfig";

let __enabled = false;
let __initPromise = null;

function requestGet(url) {
	return new Promise((resolve, reject) => {
		if (typeof wx === "undefined" || typeof wx.request !== "function") {
			reject(new Error("当前环境不支持 wx.request，无法拉取 DH 初始化配置"));
			return;
		}
		wx.request({
			url,
			method: "GET",
			success(res) {
				resolve(res && res.data);
			},
			fail(err) {
				reject(err || new Error("wx.request 失败"));
			},
		});
	});
}

function normalizeInitConfig(raw) {
	if (!raw || typeof raw !== "object") {
		return null;
	}
	if (raw.requests) {
		return raw;
	}
	if (raw.config && raw.config.requests) {
		return raw.config;
	}
	if (raw.initConfig && raw.initConfig.requests) {
		return raw.initConfig;
	}
	if (raw.sdkConfig && raw.sdkConfig.requests) {
		return raw.sdkConfig;
	}
	return raw;
}

async function fetchInitConfigByCode(code) {
	const url =
		INIT_CONFIG_API +
		(INIT_CONFIG_API.indexOf("?") >= 0 ? "&" : "?") +
		"code=" +
		encodeURIComponent(code);
	const parsed = await requestGet(url);
	const bizCode =
		parsed && (parsed.resultCode !== undefined ? parsed.resultCode : parsed.code);
	const bizMsg =
		(parsed && (parsed.resultInfo || parsed.message || parsed.msg)) || "";
	const ok = bizCode === 1 || bizCode === "1" || bizCode === undefined;
	if (parsed && bizCode !== undefined && !ok) {
		throw new Error(
			`DH initConfig 业务错误（${bizCode}）: ${bizMsg || JSON.stringify(parsed)}`,
		);
	}
	const config = normalizeInitConfig(
		(parsed && (parsed.datum || parsed.data)) || parsed,
	);
	if (!config || typeof config !== "object") {
		throw new Error("DH initConfig 返回为空或格式不正确");
	}
	return config;
}

/**
 * 无 code 时的占位参数（不得编造真实业务值；运行时须用 wxGameCode 或 wxGameSDKConfig 覆盖）
 */
function buildTodoInitOptions(overrides = {}) {
	return {
		requests: {
			login: "", // TODO: 登录服务接口地址（由 wxGameCode 拉取或 wxGameSDKConfig 传入）
			order: "", // TODO: 支付下单服务接口地址
			pay: "", // TODO: H5 支付服务接口地址
			midas: "", // TODO: 米大师支付服务接口地址
			customerService: "", // TODO: H5 客服服务接口地址
			svip: "", // TODO: SVIP 服务接口地址
			subscribe: "", // TODO: 订阅消息服务接口地址
			gameClub: "", // TODO: 游戏圈服务接口地址
			voiceChat: "", // TODO: 实时语音服务接口地址
			log: "", // TODO: 数据上报服务接口地址
			errorLog: "", // TODO: 日志上报服务接口地址
			dyb: "", // TODO: 冰柠乐渠道服务接口地址（非冰柠乐可空）
		},
		gameAppId: "", // TODO: 微信侧 AppID
		appId: "", // TODO: SDK 开放平台 AppID
		appVersion: "1.0.0",
		packageName: "", // TODO: 应用包名
		channel: 1398,
		mainChannel: 100761,
		secondChannel: 100762,
		heartbeatEnable: true,
		...overrides,
	};
}

class DHMiniSDKManager {
	constructor() {
		this.dhMiniSdk = null;
		this.rewardedAd = null;
		this._initOptions = null;
		this._ready = false;
	}

	setEnabled(enabled) {
		__enabled = !!enabled;
	}

	isEnabled() {
		return __enabled;
	}

	isReady() {
		return !!(__enabled && this._ready && this.dhMiniSdk);
	}

	/**
	 * 初始化 DH SDK
	 * @param {Object} runtime
	 * @param {boolean} runtime.isWXGameSDK
	 * @param {string} [runtime.wxGameCode] - 开放平台 code，用于拉取全量初始化参数
	 * @param {Object} [runtime.wxGameSDKConfig] - 直接传入的 DHMiniSDK options（可与 code 拉取结果合并，后者覆盖）
	 * @param {string} [runtime.appVersion]
	 * @param {string} [runtime.appId] - readyAsync(config).appId，写入 DH 的 gameAppId（微信侧 AppID）
	 */
	async initAsync(runtime = {}) {
		const enabled = runtime.isWXGameSDK === true;
		this.setEnabled(enabled);
		if (!enabled) {
			console.log("ℹ️ [DHMiniSDKManager] isWXGameSDK=false，跳过 DH 官方 SDK 接入");
			return null;
		}

		if (this._ready && this.dhMiniSdk) {
			return this.dhMiniSdk;
		}
		if (__initPromise) {
			return __initPromise;
		}

		__initPromise = this._doInit(runtime).catch((err) => {
			__initPromise = null;
			throw err;
		});
		return __initPromise;
	}

	async _doInit(runtime = {}) {
		const code =
			runtime.wxGameCode != null && String(runtime.wxGameCode).trim() !== ""
				? String(runtime.wxGameCode).trim()
				: "";
		const direct =
			runtime.wxGameSDKConfig && typeof runtime.wxGameSDKConfig === "object"
				? runtime.wxGameSDKConfig
				: null;
		const readyAppId =
			runtime.appId != null && String(runtime.appId).trim() !== ""
				? String(runtime.appId).trim()
				: "";

		if (!code && !direct) {
			throw new Error(
				"isWXGameSDK=true 时请传入 config.wxGameCode（推荐）或 config.wxGameSDKConfig",
			);
		}

		let options = buildTodoInitOptions({
			appVersion: runtime.appVersion || "1.0.0",
		});

		if (code) {
			const remote = await fetchInitConfigByCode(code);
			options = {
				...options,
				...remote,
				requests: {
					...(options.requests || {}),
					...((remote && remote.requests) || {}),
				},
			};
		}

		if (direct) {
			options = {
				...options,
				...direct,
				requests: {
					...(options.requests || {}),
					...((direct && direct.requests) || {}),
				},
			};
		}

		// 微信侧 gameAppId 固定用 readyAsync(config).appId
		if (readyAppId) {
			options.gameAppId = readyAppId;
		}

		this._initOptions = options;
		this.dhMiniSdk = new DHMiniSDK(options);
		this._ready = true;
		console.log("✅ [DHMiniSDKManager] DHMiniSDK 初始化完成", {
			gameAppId: options.gameAppId,
			appId: options.appId,
		});
		return this.dhMiniSdk;
	}

	getSdk() {
		return this.dhMiniSdk;
	}

	/**
	 * 登录（Promise 版，供 fbiCore 登录链路调用）
	 * 将 DH 返回映射为本 SDK 既有 userInfo 结构
	 */
	loginAsync(appId) {
		return new Promise((resolve, reject) => {
			if (!this.isReady()) {
				reject(new Error("DHMiniSDK 未初始化，请先 readyAsync({ isWXGameSDK: true, wxGameCode })"));
				return;
			}
			this.dhMiniSdk.login({
				success: (res) => {
					if (!res || Number(res.code) !== 0 || !res.data) {
						reject(
							new Error(
								(res && res.message) ||
									`DH 登录失败 code=${res && res.code}`,
							),
						);
						return;
					}
					const data = res.data;
					const expireTs = Number(data.expireTimestamp);
					const expireAt = Number.isFinite(expireTs)
						? expireTs > 1e12
							? expireTs
							: expireTs * 1000
						: Date.now() + 7 * 24 * 3600 * 1000;
					resolve({
						accessToken: data.token,
						appId: appId || (this._initOptions && this._initOptions.appId) || "",
						createdDt: Number(data.loginTimestamp)
							? Number(data.loginTimestamp) > 1e12
								? Number(data.loginTimestamp)
								: Number(data.loginTimestamp) * 1000
							: Date.now(),
						expireAt,
						userId: String(data.accountId),
						openId:
							(data.userExtraInfo &&
								(data.userExtraInfo.openId || data.userExtraInfo.openid)) ||
							"",
						unionId: "",
						session_key: "",
						// 保留 DH 原始字段，便于业务扩展
						dhLogin: data,
					});
				},
				fail: (res) => {
					reject(
						new Error(
							(res && res.message) ||
								`DH 登录失败 code=${res && res.code}`,
						),
					);
				},
			});
		});
	}

	/**
	 * 文档形态 login（success/fail/complete）
	 */
	login(options = {}) {
		if (!this.isReady()) {
			if (typeof options.fail === "function") {
				options.fail({ code: -1, message: "DHMiniSDK 未初始化" });
			}
			if (typeof options.complete === "function") {
				options.complete({ code: -1, message: "DHMiniSDK 未初始化" });
			}
			return;
		}
		this.dhMiniSdk.login(options);
	}

	/**
	 * 创建激励视频广告（DH createRewardedVideoAd）
	 */
	createRewardedVideoAd(options = {}) {
		if (!this.isReady()) {
			console.warn("⚠️ [DHMiniSDKManager] createRewardedVideoAd: SDK 未就绪");
			return undefined;
		}
		const ad = this.dhMiniSdk.createRewardedVideoAd({
			adPlatform: "weixin",
			...options,
		});
		this.rewardedAd = ad;
		return ad;
	}

	/**
	 * 展示激励广告（带失败重载重试）
	 */
	showRewardedAd(options, retryTimes) {
		if (!this.rewardedAd) {
			return;
		}
		retryTimes = retryTimes !== undefined ? retryTimes : 3;
		this.rewardedAd.show(options, (showRes) => {
			if (showRes && showRes.code == 0) {
				return;
			}
			if (retryTimes > 0) {
				this.rewardedAd.load((loadRes) => {
					if (loadRes && loadRes.code == 0) {
						this.showRewardedAd(options, retryTimes - 1);
					} else {
						console.warn(
							"⚠️ [DHMiniSDKManager] 激励广告 load 失败",
							loadRes && loadRes.message,
						);
					}
				});
			} else {
				console.warn("⚠️ [DHMiniSDKManager] 激励广告展示重试耗尽");
			}
		});
	}
}

const dhMiniSDKManager = new DHMiniSDKManager();
export default dhMiniSDKManager;
