import comfortable from "./fbiadComfortable/fbiadCFIndex.js";

/**
 * 激励视频广告加载器 - 简化版本
 * 原则：直接使用平台基类，不做复杂包装
 */

let RewardedVideoAdLoaderBase = null;

const initRewardedVideoAdLoaderBase = async () => {
	RewardedVideoAdLoaderBase = await comfortable.RewardedVideoAdLoaderAsync();
	return RewardedVideoAdLoaderBase;
};

/**
 * @description: 初始化一个激励广告，开发者需要将参数置换为自己小程序的广告id
 */
class RewardedVideoAdLoader {
    constructor(params) {
        this.params = params;
        this.initialized = false;
        this.baseLoader = null;
        this.initPromise = this.initBase();
    }
    
    async initBase() {
        if (!RewardedVideoAdLoaderBase) {
            await initRewardedVideoAdLoaderBase();
        }
        this.baseLoader = new RewardedVideoAdLoaderBase(this.params);
        this.initialized = true;
        return this.baseLoader;
    }
    
    async ensureInitialized() {
        if (!this.initialized || !this.baseLoader) {
            this.initPromise = this.initBase();
            await this.initPromise;
        }
        return this.baseLoader;
    }
    
    async load() {
        const loader = await this.ensureInitialized();
        return loader.load();
    }
    
    async show() {
        const loader = await this.ensureInitialized();
        return loader.show();
    }
    
    async destroy() {
        if (this.baseLoader && typeof this.baseLoader.destroy === 'function') {
            await this.baseLoader.destroy();
        }
        this.baseLoader = null;
        this.initialized = false;
    }
    
    isSame(params) {
        return false; // 永远返回 false，强制重建
    }
    
    onLoad(callback) {
        if (this.baseLoader && callback && typeof callback === 'function') {
            this.baseLoader.onLoad(callback);
        }
    }
    
    onError(callback) {
        if (this.baseLoader && callback && typeof callback === 'function') {
            this.baseLoader.onError(callback);
        }
    }
    
    onClose(callback) {
        if (this.baseLoader && callback && typeof callback === 'function') {
            this.baseLoader.onClose(callback);
        }
    }
    
    offLoad(callback) {
        if (this.baseLoader && callback && typeof callback === 'function') {
            this.baseLoader.offLoad(callback);
        }
    }
    
    offError(callback) {
        if (this.baseLoader && callback && typeof callback === 'function') {
            this.baseLoader.offError(callback);
        }
    }
    
    offClose(callback) {
        if (this.baseLoader && callback && typeof callback === 'function') {
            this.baseLoader.offClose(callback);
        }
    }

    /** 复用平台单例前清空业务监听，避免叠 onError/onClose */
    clearListeners() {
        if (this.baseLoader && typeof this.baseLoader.clearListeners === 'function') {
            this.baseLoader.clearListeners();
        }
    }
}

export default RewardedVideoAdLoader;