import deploy from "./Deploy.js";

/**
 * 事件收集器
 */
class Track {

	constructor() {
		// 事件缓存队列：SDK 未初始化时缓存事件，初始化后自动发送
		this._pendingEvents = [];
		this._isProcessingQueue = false;
	}

	/**
	 * 检查SDK是否已准备就绪
	 */
	_checkReady() {
		if (!deploy) {
			return false;
		}

		// 检查 SDK 是否真正初始化完成
		if (!deploy.isReady || !deploy.isReady()) {
			return false;
		}

		return true;
	}

	/**
	 * 处理缓存的事件队列
	 */
	async _processQueue() {
		if (this._isProcessingQueue || this._pendingEvents.length === 0) {
			return;
		}

		// 检查 SDK 是否已就绪
		if (!this._checkReady()) {
			return;
		}

		this._isProcessingQueue = true;
		console.log(`📤 [Track] 开始发送缓存的 ${this._pendingEvents.length} 个事件`);

		while (this._pendingEvents.length > 0) {
			const event = this._pendingEvents.shift();
			try {
				if (event.isLogin) {
					await deploy.fbisdk.trackAsync(event.event_name, event.properties);
				} else {
					await deploy.fbisdk.trackAfterLoginAsync(event.event_name, event.properties);
				}
				console.log(`✅ [Track] 缓存事件 '${event.event_name}' 发送成功`);
			} catch (error) {
				console.warn(`⚠️ [Track] 缓存事件 '${event.event_name}' 发送失败:`, error);
			}
		}

		this._isProcessingQueue = false;
	}

	/**
	 * 事件收集
	 * @param {string} event_name 事件名
	 * @param {Object} properties 事件属性
	 * @param {Boolean} isLogin - 是否登录
	 */
	async track(event_name, properties = {}, isLogin = true) {

		try {
			// 参数验证
			if (!event_name || typeof event_name !== 'string') {
				console.error('❌ [Track] 事件名必须是非空字符串');
				return Promise.resolve(false);
			}

			// 检查SDK是否就绪
			if (!this._checkReady()) {
				// SDK 未就绪，缓存事件
				console.log(`📋 [Track] SDK未就绪，缓存事件 '${event_name}'，等待初始化后发送`);
				this._pendingEvents.push({ event_name, properties, isLogin, timestamp: Date.now() });
				return Promise.resolve(true); // 返回 true 表示已缓存
			}

			// 先处理缓存的事件
			if (this._pendingEvents.length > 0) {
				await this._processQueue();
			}

			// 调用埋点
			return isLogin ? deploy.fbisdk
				.trackAsync(event_name, properties)
				.then(() => {
					return true;
				})
				.catch(error => {
					console.warn(`⚠️ [Track] 事件 '${event_name}' 记录失败:`, error);
					return false;
				}) : deploy.fbisdk
					.trackAfterLoginAsync(event_name, properties)
					.then(() => {
						return true;
					})
					.catch(error => {
						console.warn(`⚠️ [Track] 事件 '${event_name}' 记录失败:`, error);
						return false;
					});

		} catch (error) {
			console.error('❌ [Track] 埋点上传异常:', error);
			return Promise.resolve(false);
		}
	}

	/**
	 * 事件收集（登录前可调用）
	 * @param {string} event_name 事件名
	 * @param {Object} properties 事件属性
	 */
	async trackAfterLogin(event_name, properties = {}) {
		return this.track(event_name, properties, false);
	}

	/**
	 * 安全的埋点方法，即使SDK未初始化也不会报错
	 * @param {string} event_name 事件名
	 * @param {Object} properties 事件属性
	 */
	safTrack(event_name, properties = {}) {
		try {
			return this.track(event_name, properties);
		} catch (error) {
			console.warn(`⚠️ [Track] safeTrack静默处理错误:`, error);
			return Promise.resolve(false);
		}
	}

	/**
	 * 手动触发发送缓存的事件（SDK初始化后调用）
	 */
	async flushPendingEvents() {
		return this._processQueue();
	}

	/**
	 * 获取当前缓存的事件数量
	 */
	getPendingCount() {
		return this._pendingEvents.length;
	}
}

/**
 * @description
 * 事件收集器实例
 */
let track = new Track()

// 同时导出类和实例
export { Track };
export default track;